UPDATE characters SET description = '戦闘スタイル：太陽の呼吸　ツギクニ・ヨリイチは、『鬼滅の刃』の主要な脇役の一人である。戦国時代、鬼殺隊に所属していた伝説の鬼殺隊員であった。' WHERE character_id = 'CH015069';
UPDATE characters SET description = '釜戸家の先祖であり、津木国頼一の親しい知人である。' WHERE character_id = 'CH015070';
