UPDATE characters SET description = '上弦の月4の位を持つ、12のキズキの悪魔。' WHERE character_id = 'CH015072';
UPDATE characters SET description = '刀鍛冶の村の長。' WHERE character_id = 'CH015073';
UPDATE characters SET description = 'ウブヤシキ・ニチカは、カガヤ・ウブヤシキの長女の一人である。' WHERE character_id = 'CH015074';
UPDATE characters SET description = '玉光（ぎょっこ）は、『鬼滅の刃』の「刀鍛冶の里編」に登場する主要な敵役の一人である。また、「十二鬼月」の一員であり、上弦の五の地位にある。' WHERE character_id = 'CH015075';
UPDATE characters SET description = 'コテツは、刀鍛冶の村出身の若い村人だ。彼の先祖は、戦闘人形「ヨリイチ・タイプゼロ」を作り上げた。' WHERE character_id = 'CH015076';
UPDATE characters SET description = '種族：人間　年齢：不明　道属性：不明　職業：アサエモン　所属：山田一族　階級：11位　キショウは山田一族の11位のアサエモンであり、犯罪者「ワープド・ケイウン」の監視を任されていた。  キショウは、決して冷静さを失わず、積極的に行動することもめったにない人物として知られている。彼は状況の全体像を見通すことができ、自分の対処法に異議を唱えられると不快に感じる。キショウは、手っ取り早い方法を選ぶことを厭わない姿勢を見せているが、' WHERE character_id = 'CH015079';
UPDATE characters SET description = '鉄心は、かつて山田家の朝右衛門であり、紫苑の最初の弟子であった。' WHERE character_id = 'CH015080';
UPDATE characters SET description = 'このドウシはテンセン卿の配下であり、コタク島に上陸した人間たちを監視するよう命じられた数少ない者の一人だった。' WHERE character_id = 'CH015082';
UPDATE characters SET description = '種族：テンセン・タオ　属性：土　職業：コタクの支配者　所属：テンセン卿　ムー・ダンはテンセン卿の一員であり、コタクの支配者の一人でもある。　ムー・ダンは陽気でありながら、非常にサディスティックな性格をしている。 彼は物言いが非常に率直で、自身の力に対する自信ゆえに、敵が何を望んでいるかを臆することなく告げる。ム・ダンは人間を、単に研究材料であり、自分の好きなように扱える「おもちゃ」と見なしている。彼は他のテたちとも、かなり良好な関係を築いているようだ。' WHERE character_id = 'CH015083';
UPDATE characters SET description = 'このドウシはテンセン卿の配下であり、コタク島に上陸した人間たちを監視するよう命じられた数少ない者の一人だった。' WHERE character_id = 'CH015084';
UPDATE characters SET description = '将軍のために不老不死の霊薬を手に入れるよう命じられた犯罪者の一人。' WHERE character_id = 'CH015085';
UPDATE characters SET description = '「不老不死の霊薬」を探すためにスカウトされた死刑囚。僧兵としての修行中に、ケイウンは武器や鎧に執着するようになり、武術家たちを殺害してその武器を奪うことで、修行をさらなる高みへと引き上げようと決意した。' WHERE character_id = 'CH015086';
UPDATE characters SET description = '引きこもりの良介は、精神的に不安定な人物で、人生で愛されていると感じられるようにとアイドルに救いを求めている。彼は星野アイの熱狂的なファンである。' WHERE character_id = 'CH015088';
UPDATE characters SET description = '涼白マナは、新進アイドルグループ「B-Komachi」のステージを見たことをきっかけに、芸能活動を辞めることを決めたアンダーグラウンドアイドルである。' WHERE character_id = 'CH015089';
UPDATE characters SET description = '星野ルビーを自社のアイドルとしてスカウトしたいと考えている事務所のアイドル。' WHERE character_id = 'CH015090';
