UPDATE characters SET description = 'ストロベリー・プロダクションズに所属する有名なフィットネス系YouTuberで、同事務所のトップ稼ぎ手である。同社の社長である齋藤都からの依頼を受け、自身のチャンネルで星野ルビーや有馬カナとコラボしたフィットネス動画を公開し、新製品「B-Komachi」のプロモーションを行っている。' WHERE character_id = 'CH015092';
UPDATE characters SET description = 'イーストン・マジック・アカデミーの副校長。' WHERE character_id = 'CH015094';
UPDATE characters SET description = 'クロード・ルッチはイーストン・マジック・アカデミーの教授であり、次世代の魔術師たちを指導する役割を担っている。' WHERE character_id = 'CH015096';
UPDATE characters SET description = 'アンナ・クラウンは、ランス・クラウンの妹です。' WHERE character_id = 'CH015097';
UPDATE characters SET description = '「マギア・ルプス」の第三の牙。オルター・マドルの弟。' WHERE character_id = 'CH015098';
UPDATE characters SET description = 'ユニコーンは生徒たちの考えを読み取り、それぞれのハウスに分類することができます。' WHERE character_id = 'CH015099';
UPDATE characters SET description = '魔法の警察官。' WHERE character_id = 'CH015100';
UPDATE characters SET description = 'イーソン・マジック・アカデミーの生徒。 manipulative で自己中心的な少女であるローレンは、男性を自分に夢中にさせる名もなき魔法を持っている。' WHERE character_id = 'CH015103';
