UPDATE characters SET description = 'イーストン・マジック・アカデミーの2年生で、ラング・ハウスの所属。イーストンでの1年目に、なんとかゴールドコインを2枚手に入れた。しかし、生徒や教師を頻繁に襲ったため、本人も驚くことに留年となってしまった。' WHERE character_id = 'CH015106';
UPDATE characters SET description = 'イーストン・マジック・アカデミーの1年生。' WHERE character_id = 'CH015108';
UPDATE characters SET description = 'イーストン・マジック・アカデミーの生徒。ダブルライナーであり、自らを「オルカ寮のマグマ・マスター」と呼んでいる。' WHERE character_id = 'CH015109';
UPDATE characters SET description = 'マルは、「天国」という場所を探している少年です。' WHERE character_id = 'CH015110';
UPDATE characters SET description = 'キルコはマルのお供であり、「ヘブン」と呼ばれる場所を探している。' WHERE character_id = 'CH015111';
UPDATE characters SET description = '彼女はトキオの同級生で、ダンスが得意だ。' WHERE character_id = 'CH015112';
UPDATE characters SET description = '高原学園の施設で保護されているヒルコの子供の一人。親友はハニだ。' WHERE character_id = 'CH015121';
UPDATE characters SET description = '栄は、茨城県復興省の職員である。平馬や竹塚美智香とともに、マルとキルコを探す任務を任されている。' WHERE character_id = 'CH015126';
UPDATE characters SET description = '青島裕子は高原学園の看護師であり、後に同学園の副園長に就任した。' WHERE character_id = 'CH015129';
UPDATE characters SET description = '沢渡は、高原学園で勤務する医師です。' WHERE character_id = 'CH015134';
UPDATE characters SET description = '彼は、高原アカデミーの所長である上中志乃氏の夫である。また、同アカデミーで役員としても勤務している。' WHERE character_id = 'CH015142';
UPDATE characters SET description = '彼はリヴィウマンの幹部の一人である。' WHERE character_id = 'CH015146';
UPDATE characters SET description = '茜は、元カレと別れたばかりの大学生だ。別れた主な理由は、彼がゲーム『フォレスト・オブ・セイヴィア（FOS）』で出会った別の女性ゲーマーに恋をしてしまったためだ。彼女もそのゲームのプレイヤーであり、[チョコレート・ラビット]というギルドに所属している。 彼女のキャラクター名は「茜」で、クラスはパラディンだ。彼女はテクノロジーにはあまり詳しくないが、ゲームをプレイすることや、みんなと仲良く過ごすことが大好きだ。' WHERE character_id = 'CH015154';
UPDATE characters SET description = '山田は、頭が良くてイケメンな高校生だ。恋愛には興味がなく、ゲームに没頭している。彼は有名なプロゲーマーであり、スポンサーから報酬を得ている。 主にFPS（ファーストパーソン・シューター）ゲームをプレイしている。『フォレスト・オブ・セイバー（FOS）』のプレイヤーであり、[チョコレート・ラビット]というギルドに所属している。キャラクター名は「山田」で、クラスはウィザードだ。' WHERE character_id = 'CH015155';
UPDATE characters SET description = 'タクマの現在の彼女。' WHERE character_id = 'CH015156';
UPDATE characters SET description = '佐々木は佐々木ルナの兄である。また、故郷では山田くんの先輩でもある。趣味はゲームをすることだ。彼も『フォレスト・オブ・セイバー（FOS）』をプレイしており、ギルド「チョコレート・ラビット」のメンバーでもある。' WHERE character_id = 'CH015157';
UPDATE characters SET description = 'ルナは、普段はロリータファッションを着ている中高生だ。佐々木栄太の妹である。また、週末には山田から指導を受けている。さらに、ゲーム『フォレスト・オブ・セイバー（FOS）』のプレイヤーであり、ギルド「チョコレート・ラビット」のメンバーでもある。' WHERE character_id = 'CH015158';
UPDATE characters SET description = 'タケゾウは、穏やかで優しい人柄の高齢の男性です。年齢にもかかわらず、チョコレート・ラビット・ギルドの活発なメンバーとして、その活動に貢献し続けています。彼はイチゴ農園を経営しています。' WHERE character_id = 'CH015160';
UPDATE characters SET description = 'コンビニであかねと一緒に働いている同僚。' WHERE character_id = 'CH015162';
UPDATE characters SET description = 'エイタとルナの母親。' WHERE character_id = 'CH015164';
UPDATE characters SET description = 'あかねの元カレ。' WHERE character_id = 'CH015165';
UPDATE characters SET description = 'ルリ姫のファン。' WHERE character_id = 'CH015166';
UPDATE characters SET description = 'イバラ大臣は、「宝島編」の主な敵役である。' WHERE character_id = 'CH015167';
UPDATE characters SET description = 'その名は世界中に知れ渡る、アメリカの有名な歌姫。冒険への情熱から、千空の父である石神白夜と共に国際宇宙ステーション（ISS）へと乗り込んだ。' WHERE character_id = 'CH015168';
UPDATE characters SET description = '石神村の年配の住民の一人。村随一の漁師であり、魚や船から離れている姿はほとんど見られない。サンゴと結婚しており、他の年長者たち、特にアルミやナトリとよく一緒にいる姿が描かれている。' WHERE character_id = 'CH015169';
UPDATE characters SET description = '地球の人々が恐怖に凍りついた当時、国際宇宙ステーションに滞在していた宇宙飛行士の一人であったNASA職員。' WHERE character_id = 'CH015170';
UPDATE characters SET description = '石神村の村人。カルボの父親であり、アルミの夫である。' WHERE character_id = 'CH015171';
UPDATE characters SET description = 'コハクとルリの父。センクが目を覚ました当時、石神村の村長を務めていた。' WHERE character_id = 'CH015172';
UPDATE characters SET description = 'シャミルは、地球の地表で石化現象が発生した当時、国際宇宙ステーション（ISS）に滞在していたロシア人宇宙飛行士だった。彼はISSの他の乗組員たちと共に地球の地表に戻り、石神村の設立に貢献した。 地球に戻った後、シャミルはISSの同僚宇宙飛行士であるコニー・リーと結婚し、数人の子供に恵まれた。彼の性格は白哉とは正反対で、無口で、冷静沈着、真面目で、現実的な人物だった。' WHERE character_id = 'CH015173';
UPDATE characters SET description = '石神村の村人。カルボの母親であり、ナトリの妻である。' WHERE character_id = 'CH015174';
UPDATE characters SET description = '夫のヤコフ・ニキティンと共に国際宇宙ステーション（ISS）に滞在していたロシアの宇宙飛行士兼医師。宇宙滞在中、彼女は地球の地表におけるすべての生命が石化していく様子を目の当たりにした。' WHERE character_id = 'CH015175';
UPDATE characters SET description = 'ガネンは石神村の村人である。彼はサガンとエンの息子である。' WHERE character_id = 'CH015176';
UPDATE characters SET description = 'ロシアの宇宙飛行士であり、医師でもある。地球の人々が恐怖に凍りついた当時、国際宇宙ステーションに滞在していた宇宙飛行士の一人、ダーリヤ・ニキティナの夫である。' WHERE character_id = 'CH015177';
UPDATE characters SET description = 'アマリリスは、石化王国で最も美しい少女と見なされている。' WHERE character_id = 'CH015178';
UPDATE characters SET description = '石神村の住人で、規則を厳格に守る人物。ターコイズと共に、村の巫女の護衛を務めている。' WHERE character_id = 'CH015179';
UPDATE characters SET description = '石化王国の戦士。島で最も強力な人物の一人と見なされている。' WHERE character_id = 'CH015180';
UPDATE characters SET description = '石神村の一員。ジャスパーと共に、ルリの護衛の一人として仕えている。' WHERE character_id = 'CH015181';
UPDATE characters SET description = 'ワンタロは、山田アンナの飼い犬のウェルシュ・コーギーです。' WHERE character_id = 'CH015182';
UPDATE characters SET description = 'バスケットボールが誤って山田の顔に当たってしまった女の子。' WHERE character_id = 'CH015183';
UPDATE characters SET description = '『僕の心のヤバイやつ』に登場するルシファー・ニゴリカワは、市川が想像の中で生み出した架空の存在である。厳密には「キャラクター」というわけではないが、ニゴリカワは市川が自身の感情面の欠点を克服するために思い描いた架空の人物である。 その姿は、主に山田のお気に入りの少女漫画『Your Color''s Octave』の主人公である「ニゴリカワくん」をモデルにしている。「ルシファー」という呼び名や、時折生えてくる黒い翼は、市川の「中二病」的な妄想による付け足しである。' WHERE character_id = 'CH015184';
UPDATE characters SET description = '天上悠也は、このシリーズの主人公である。祖父の秘密の部屋で、悠也は異世界「アルゲナ」へと通じる扉を見つけ、そこで力を手に入れた。地球とアルゲナを行き来できるようになった悠也は、両方の世界で非凡な存在となった。' WHERE character_id = 'CH015185';
UPDATE characters SET description = '王星学園の理事長・北条司の娘である北条香織は、コンビニの近くで見知らぬ男たちに絡まれていたところを、天上悠也に助けられた。彼女の推薦があったおかげで、彼は王星学園への入学を許可されたのである。' WHERE character_id = 'CH015186';
UPDATE characters SET description = '天上陽太の双子の兄弟。' WHERE character_id = 'CH015192';
UPDATE characters SET description = '天上悠也の亡き祖父。亡くなる前、彼は悠也に対し、どんな状況にあっても諦めないよう励ました。' WHERE character_id = 'CH015197';
UPDATE characters SET description = '天上ソラの双子の兄弟。' WHERE character_id = 'CH015201';
UPDATE characters SET description = 'レクシア・フォン・アルセリアの騎士。' WHERE character_id = 'CH015202';
UPDATE characters SET description = '北条香織の父であり、王星学園の理事長。' WHERE character_id = 'CH015206';
UPDATE characters SET description = '天上悠也が変身し、転校する前の主ないじめっ子。' WHERE character_id = 'CH015209';
UPDATE characters SET description = 'アーノルド・フォン・アルセリアは、アルセリア王国の国王である。' WHERE character_id = 'CH015210';
UPDATE characters SET description = '天上悠也の同級生の一人。' WHERE character_id = 'CH015212';
UPDATE characters SET description = '秀知院学園の生徒会副会長であり、名門・四ノ宮家の令嬢である彼女は、本気を出せば何でもこなせる多才な天才だ。育ちのせいで、本能的に他人を見下し、自分の利益のために他人をどう利用するかばかりを考えている。 かぐやは生徒会に入る前は他人とほとんど関わりがなかったが、その状況も変わり始めている。彼女は極めて保護された環境で育ったため、いくつかの点で未熟な部分がある。' WHERE character_id = 'CH015214';
UPDATE characters SET description = '彼は秀知院学園の2年生で、生徒会長を務めている。美幸は金髪に青い目をしたハンサムな青年だ。慢性的な睡眠不足と近視のため、その目は鋭く光っているように見える。 普段は、首元に「エギュイエット」と呼ばれる金色の鎖状の装飾品を身につけた、秀知院学園の標準的な男子黒制服を着用している。エギュイエットは、生徒会長としての彼の権威を象徴している。白銀は勤勉な生徒であり、たとえ……' WHERE character_id = 'CH015215';
UPDATE characters SET description = 'マキはナギサの同級生であり友人だ。短い髪を短いおさげに結っている。ナギサとは仲が良いが、ナギサと彼女の彼氏との関係を密かに妬んでいる。というのも、彼女自身も柏木の彼氏に好意を抱いていたが、以前、告白できなかったからだ。 四ノ宮一族の分家の一員として、彼女はかぐやの再従二親等にあたるため、時折かぐやを「おばさん」と呼ぶことがある。美雪とユウは、彼女の振る舞いが非常にツンデレ（外見は冷たいが、内心は愛情を求めたい）であり、まるで……のようだと指摘している。' WHERE character_id = 'CH015216';
UPDATE characters SET description = 'ツバメは3年生で、チアリーディング部の副キャプテンであり、新体操選手でもある。彼女はとても人気がある。チアリーディングの活動では、ユウを励ましている。' WHERE character_id = 'CH015217';
UPDATE characters SET description = 'コバチは、メガネをかけたミコの同級生で、生徒会に所属している。彼女は10年以上もミコの面倒を見てきた。' WHERE character_id = 'CH015218';
UPDATE characters SET description = 'シュチイン学園生徒会の書記。彼女の行動は予測不可能で、本心も読み取れない。ただそこにいるだけで無意識のうちにすべてを混乱に陥れる「自然災害」とも呼ばれる存在であり、別名「被験体F」とも称される。' WHERE character_id = 'CH015219';
UPDATE characters SET description = '秀知院学園の生徒会会計。学園の資金管理をすべて一人で担っていることから、美雪からは非常に重宝されている。また、かぐやを恐れているが、その理由は他の誰にもわからない。 ユウは物静かで、めったに口を開かないが、口を開くとよくトラブルに巻き込まれる。劣等感を抱きつつ、人生に対して悲観的な見方をしている。その態度とは対照的に、困っている人を助けようとし、必要とあれば自分のプライドも犠牲にする。彼とは異なり、' WHERE character_id = 'CH015220';
UPDATE characters SET description = '白銀ケイは、白銀ミユキの妹である。修智院中学校に通っており、同校の中学生会の会計を務めている。兄と同じように努力家だが、時折非常にプライドが高い面もある。 また、兄と同じ正義感を受け継いでおり、ある状況下で誰かが正しい行動をとらないことを嫌う。兄と同様、たとえ手間がかかっても、困っている人を助けることが好きだ。彼女は、' WHERE character_id = 'CH015221';
UPDATE characters SET description = '彼女は秀知院私立学園の1年生で、生徒会の監事である。ミコは正義感が強く、善悪について他人を正そうとする。 残念ながら、そのせいでいじめの標的となってしまったが、それでも彼女は「正しいこと」という信念を貫き続けている。彼女は藤原千佳を崇拝しており、たとえそれが千佳を楽しませるためであっても、彼女の言うことなら何でも聞き入れている。' WHERE character_id = 'CH015222';
UPDATE characters SET description = 'モエハはチカの妹で、中学生だ。彼女は中学校の生徒会副会長を務めている。彼女もミユキに憧れており、いつか告白したいと思っている。彼女は暗い考えを口に出す癖があり、それがカグヤを大いに不安にさせている。' WHERE character_id = 'CH015223';
UPDATE characters SET description = '田沼正三は、世界的に有名な心臓外科医であり、四宮家の主治医でもある。また、ツバサの祖父でもある。' WHERE character_id = 'CH015224';
UPDATE characters SET description = 'ナギサは、時折カグヤに恋愛の悩みを相談してくる同級生。ツバサの彼女。' WHERE character_id = 'CH015225';
UPDATE characters SET description = '桃・竜珠は、このシリーズの脇役の一人である。彼女は天文部の部長であり、「インポッシブル・ガールズ」の一員でもある。 ヤクザ一家の娘である彼女は、校内で帽子をかぶったり、携帯電話でゲームをしたりするなど、校則をあまり重視していない。また、短気な性格で、周囲からは威圧的な存在と見なされている。' WHERE character_id = 'CH015226';
UPDATE characters SET description = '彼女は秀知院学園のマスメディア部の部員です。' WHERE character_id = 'CH015227';
UPDATE characters SET description = '彼は秀知院高校の生徒で、恋愛のことになるといつも白銀美由紀にアドバイスを求めている。柏木の彼氏。' WHERE character_id = 'CH015228';
UPDATE characters SET description = '白銀美由紀とケイの父。' WHERE character_id = 'CH015229';
UPDATE characters SET description = '彼女は秀知院学園のマスメディア部の部員です。' WHERE character_id = 'CH015230';
UPDATE characters SET description = '早坂愛は、修智院学園の2年生であり、四ノ宮家の執事である。彼女は、代々四ノ宮家に仕え、その信頼を勝ち取ってきた早坂家の出身である。  彼女と共に秀知院学園に入学するよう直接命じられたアイは、篠宮かぐやの高校生活を支え、10年間にわたりかぐやの生活の一部となってきた。その親密な関係ゆえに、アイはかぐやの愛想の良さが「演技」ではないと理解している数少ない人物の一人である。  ' WHERE character_id = 'CH015231';
UPDATE characters SET description = '前生徒会長（本名不明）は、本作に登場する脇役の一人である。彼は秀知院学園の高校3年生であり、第66代生徒会長を務めている。  彼は秀知院学園の高校3年生であり、白銀美雪が1年生だった当時、生徒会の会長を務めていた。' WHERE character_id = 'CH015232';
UPDATE characters SET description = '石川県鈴津近郊の郊外から東京に引っ越してきた高校1年生。神童として育てられ、クラスでトップの成績で高校に入学したが、運動神経はまったくない。その純粋な人柄が、知らず知らずのうちに周囲の人々に影響を与えている。妹と弟がいる。' WHERE character_id = 'CH015233';
UPDATE characters SET description = '女子に人気の、ミツミの同級生。入学式を台無しにしたり、授業をサボったりすることで知られている。入学式をサボるつもりだったが、ミツミと出会い、二人で一緒に学校へ駆け込んだ。' WHERE character_id = 'CH015234';
UPDATE characters SET description = 'フミノはミツミの幼なじみだ。ミツキが東京の高校に通っている間、彼女は石川に残っている。距離は離れているものの、二人は今でも親友であり、頻繁にビデオ通話で近況を語り合い、互いに打ち明け合っている。' WHERE character_id = 'CH015235';
UPDATE characters SET description = 'ミツミの父方の叔母。トランスジェンダーの女性で、スタイリストとして働いている。ミツミが東京に引っ越して以来、彼女の保護者となっている。' WHERE character_id = 'CH015236';
UPDATE characters SET description = 'ミツミの同級生であり、東京で初めてできた友人。男子からの人気が高かったため、他の女子から疎まれることへのコンプレックスを抱くようになった。幼少期に留学経験があり、金髪であることから、英語が得意だと周囲に思われているが、本人はそれほど得意ではないと語っている。' WHERE character_id = 'CH015237';
UPDATE characters SET description = 'ミツミの同級生で、中学時代からのソウスケの友人。物静かで心優しい。' WHERE character_id = 'CH015238';
UPDATE characters SET description = '2年生の生徒会役員。極端な完璧主義者で、自ら厳しい日課を課している。以前は無愛想な性格だったが、ミツミと出会ってからは優しくなった。' WHERE character_id = 'CH015239';
UPDATE characters SET description = 'ミツミがソウスケと友達になった後、彼女に近づいてきたミツミの同級生。ミツミの純粋な人柄に触発され、自身のコンプレックスと向き合うようになった。彼女はミツミと心を通わせる関係を築いていく。' WHERE character_id = 'CH015241';
UPDATE characters SET description = 'ミツミの同級生。内向的な性格で、孤立してしまうことを心配している。何らかのコミュニティに属したいと思い、生徒会に入部した際にミツミと知り合った。軽薄な人は好きではないが、ミツミを通じてユズキと出会い、二人は親しい友人になった。' WHERE character_id = 'CH015243';
UPDATE characters SET description = 'ミツミの同級生であり、ソウスケの友人。クラスのお調子者で、みんなから愛され、からかわれながらも、人や動物には全く害を及ぼさない。しかし、意外にも真面目な一面があり、クラスのみんなのためにクッキーを焼いたり、ひっそりとクラスメートを支えたりしている。' WHERE character_id = 'CH015245';
UPDATE characters SET description = 'シマの友人の一人。' WHERE character_id = 'CH015246';
UPDATE characters SET description = '岩倉光美の同級生で、演劇部の部員。意志が強く、特に演技といった自分の興味のあることには情熱を注ぐ。好きなことには惜しみなく時間と労力を費やす姿勢を見せており、他人を巻き込むことにも躊躇しない。 一方で、演技への愛情や、それを皆と分かち合いたいという強い思いのあまり、他人の感情に気づきにくい面もある。時折感情に鈍感になることもあるが、常に他人を助け、気遣っている。' WHERE character_id = 'CH015247';
UPDATE characters SET description = 'ガンタと同じように不眠症に悩む、陽気な女子高生。最初に廃墟となった天文台を見つけ、ガンタが現れるまではそこを自分の寝床としていた。' WHERE character_id = 'CH015248';
UPDATE characters SET description = '不眠症に悩む久代高校の高校生。その症状のせいで、不機嫌で人付き合いが苦手な印象を与える。ガンタは、天文台と復活した天文部（彼はその部長に就任した）を守ることを決意している。' WHERE character_id = 'CH015249';
UPDATE characters SET description = '学校看護師であり、天文部の顧問を務めている。' WHERE character_id = 'CH015254';
UPDATE characters SET description = '天文部の元部員で、全国高校天体写真コンテストで最優秀賞を受賞した。' WHERE character_id = 'CH015257';
UPDATE characters SET description = '「ザキ」という芸名で知られる崎宮美咲は、かつて崎宮製鉄の令嬢であり、初代篠山ポルカを暗殺するために雇われた殺し屋である。 自身の早すぎる死と、それに続くゾンビとしての復活――それぞれ「死体神」による偶然と意図的な仕業――を経て、彼女は死体神と同居し、彼の占い活動を助けるようになった。その後、死体神の魔法によってミサキはヴァンパイア・ラーヴァへと進化し、新たに得た力によって彼女は……' WHERE character_id = 'CH015262';
UPDATE characters SET description = '久留谷巧は、東京都新宿区を拠点とする情報屋で、違法ドローンを用いたデータ収集をはじめとする様々な手法を用いている。また、時折、殺し屋たちが被害者の遺体を隠蔽するのを手助けすることもある。 倉木リサの指示により、彼は「死体神」の付き人となり、占いのセッション中に顧客に関する情報を収集することで、その占いの事業を支援している。' WHERE character_id = 'CH015264';
UPDATE characters SET description = '西明寺ミコトは、東京の複数の管轄区域でトラブルメーカー関連の事件を担当する、法科学の「トラブルメーカー」専門家である。' WHERE character_id = 'CH015265';
UPDATE characters SET description = 'レイ・シャオユーは、かつて「ハイレイ」のメンバーであったが、現在は篠山一族に仕えている。彼の現在の任務は、篠山サヨが、彼女の異母叔父を装う偽者に身を寄せている間、彼女を守ることであり、現在もその任務を遂行中である。' WHERE character_id = 'CH015266';
UPDATE characters SET description = '「ユートウコロウ」のバーテンダー。' WHERE character_id = 'CH015267';
UPDATE characters SET description = '細苅雅は、死神との契約に基づき、咲見宮美咲のシャープペンシルに憑依している精霊である。現在は死神の占い業において「仕掛け」として働き、死神の正当性を客に納得させるため、自律的に動くシャープペンシルとして振る舞っている。  生前、細苴木は警察署長を務め、岩ノ目椿と共に特定のシンボルを調査していた内部調査課の捜査官でもあった。彼は事件を最後まで追及する前に殺害され、最期の言葉は……' WHERE character_id = 'CH015268';
UPDATE characters SET description = '職業：警察官　所属：資料編纂第3グループ副課長。' WHERE character_id = 'CH015270';
UPDATE characters SET description = 'ロザン・シノヤマは、シノヤマ一族の当主であり、シノヤマ・ファイナンシャル・グループのトップである。' WHERE character_id = 'CH015271';
UPDATE characters SET description = '「放浪のバルコニー」という異名を持ち、書籍ではしばしば「半島の悪魔」とも呼ばれるイーズリーズ・ソードフレイルは、強力なネクロマンサーであり、かつてバイアンディ帝国の宮廷魔術師として第2位の地位に就き、また「死体の神」のネクロマンシー師でもあった人物である。[1]' WHERE character_id = 'CH015272';
UPDATE characters SET description = '「ザ・グローサー」は、コンプス-3の管轄下にあるトラブルメーカーで、見込み客にあらゆる種類の商品を販売したり物々交換したりしている。岩ノ目椿に逮捕され、現在は刑務所で服役中だが、政府との取り決めに基づき、独房からビジネスを続けている。' WHERE character_id = 'CH015274';
UPDATE characters SET description = '「ローミング・ウッドランズ」ことロメルカ・リメルカは、バイアンディ帝国の崩壊まで、同帝国宮廷魔術師の第七位を務めたウッドメイジである。' WHERE character_id = 'CH015275';
UPDATE characters SET description = '「災厄砕き」の称号を持つシャグルア・エディス・ラグリード卿は、ゲルドウッド教会の制圧部隊に所属していた元騎士であり、「邪眼」の能力を持つ。' WHERE character_id = 'CH015276';
UPDATE characters SET description = '職業：警察官　所属：第3資料収集班。元ヤクザで、現在、新宿警察署地域安全課の第3資料収集班の刑事として勤務している。' WHERE character_id = 'CH015277';
UPDATE characters SET description = '篠山タケルの妻。' WHERE character_id = 'CH015279';
UPDATE characters SET description = 'クラリッサの愛称でも知られるリサ・クラキは、メディエーター兼バーテンダーであり、新宿で活動する「ユートウコロウ」――合法のバーでありながら、違法なフリーランス事務所でもある――を経営している。' WHERE character_id = 'CH015280';
UPDATE characters SET description = '職業：警察官　所属：資料収集班第3組のメンバー。ヤツは敵対者に対して歯を見せるようなニヤリと笑みを浮かべ、クールな自信を見せつけることもあるが、不利益を被った際には不満を口にすることもあり、うっとうしい相手に対しては露骨に顔をしかめることもある。 第3資料編纂グループの他のメンバーと同様、彼は岩ノ目に対して揺るぎない忠誠心を抱いているが、その一方で、不快な真実であっても躊躇なく指摘することもある。' WHERE character_id = 'CH015281';
UPDATE characters SET description = '篠山静樹は、篠山一樹の双子の弟であり、篠山羅山の末孫である。彼と一樹は、互いに気づいていないが、亡き姉・鈴香の霊に付きまとわれている。' WHERE character_id = 'CH015282';
UPDATE characters SET description = '新宿を拠点とする、放火を専門とするトラブルメーカーだ。' WHERE character_id = 'CH015285';
UPDATE characters SET description = '篠山サヨは、篠山ロザンの次女の孫娘である。現在は無職で、篠山邸に住んでいる。' WHERE character_id = 'CH015286';
UPDATE characters SET description = '羽渕秀明氏は、東京都警察本部の警視長である。' WHERE character_id = 'CH015287';
UPDATE characters SET description = '彼女は「ユートウコロウ」で働く用心棒だ。' WHERE character_id = 'CH015288';
UPDATE characters SET description = '彼は、篠山ロザンの姪の夫です。' WHERE character_id = 'CH015289';
UPDATE characters SET description = '警察本部の総監。' WHERE character_id = 'CH015290';
UPDATE characters SET description = '篠山和樹は、篠山静樹の双子の妹であり、篠山羅山の末の孫娘である。彼女も兄もそのことを知らないが、亡くなった姉の鈴香は今も霊となって二人を守り続けている。' WHERE character_id = 'CH015291';
UPDATE characters SET description = 'レミングスは、篠山タケル率いる「ドラゴン・キングズ・パレス・エージェンシー」の精鋭であり、凄腕のメンバーだ。新宿の住民の多くは彼を都市伝説の存在だと考えているが、コンプス-3は彼を複数の犯罪に関与していると見なし、その逮捕を目指している。' WHERE character_id = 'CH015292';
UPDATE characters SET description = '彼女はタブロイド紙『ウィークリー・ドライ』の記者で、政治から芸術に至るまで幅広い分野の記事を担当している。まだ新人記者ではあるが、これまでに数々の「優れたスクープ記事」を執筆しており、有能な記者として定評がある。とはいえ、彼女の調査によって不利益を被る可能性のある人々にとっては、彼女は目の上のたんこぶと見なされがちだ。' WHERE character_id = 'CH015293';
UPDATE characters SET description = '大司祭レキュリア・ロフィラルドは、ニャニルド王国を拠点とするゲルドウッド教会の強力な神術師である。彼女は、シャグルア・ルグリッドがゲルドウッドから離反した際、ゲルドウッドよりもシャグルアへの忠誠を優先したため、その結果、ゲルドウッドの上層部から激しい怒りを買うこととなった。' WHERE character_id = 'CH015294';
UPDATE characters SET description = '篠山タケルのもとで働いている女性。' WHERE character_id = 'CH015295';
UPDATE characters SET description = 'リンネは、兄のヒイロと同様、元アガクラの狙撃手である。' WHERE character_id = 'CH015296';
UPDATE characters SET description = '台北はハイレイの一員であり、現在はバオと共に篠山タケルの下で活動している。' WHERE character_id = 'CH015297';
UPDATE characters SET description = '篠山タケルは、篠山ロザンの長孫であり、篠山セキュリティの社長であり、「ドラゴン・キングズ・パレス・エージェンシー」として知られる精鋭チームの雇用主である。' WHERE character_id = 'CH015298';
UPDATE characters SET description = 'ヒイロは、妹のリンネと共に、元アガクラの狙撃手である。' WHERE character_id = 'CH015300';
UPDATE characters SET description = '篠山タケルのもとで働いている女性。' WHERE character_id = 'CH015301';
UPDATE characters SET description = '職業：警察官　所属：資料収集班第3班のメンバー。同班の班長であり、現在は「ファントム・ソリティア」事件の捜査における管轄業務を担当している。' WHERE character_id = 'CH015302';
UPDATE characters SET description = '篠山鈴香は、篠山羅山の亡き長孫娘であり、双子の篠山静希と篠山一希の姉にあたる。彼女の霊は、ノーズの手によって殺害される直前、双子を愛し、その安全を案じていた鈴香の想いが形となり、この1年間、双子のそばに寄り添い続けている。' WHERE character_id = 'CH015303';
UPDATE characters SET description = '篠山ポルカは、篠山ロザンの次男であり、篠山フィナンシャルグループの2人の後継者のうちの1人である。家出をして間もなく、ポルカは殺し屋の咲宮美咲によって暗殺される。 「死神」は、殺害されたばかりのポルカの体に転生し、ポルカの魂をその体に定着させた後、すぐにその魂を久留谷巧のドローンの一つへと移す。 その後、彼は再びポルカの魂をカツオザメのぬいぐるみへと移す。ポルカは「死体神」に対し、自分の名前を使用することを許可しており、' WHERE character_id = 'CH015304';
UPDATE characters SET description = '新宿駅で25年間勤務してきた高齢の女性。' WHERE character_id = 'CH015305';
UPDATE characters SET description = '彼女は「ユートウコロウ」で働く用心棒だ。' WHERE character_id = 'CH015306';
UPDATE characters SET description = '好きなもの：数学、物理学、金融　心優しく、カリスマ性があり、知性的だが、それは特定の分野に限られる。 ユザキ・ナサは、高校教育など必要ないと決め込みましたが、まあ、その判断は概ね正しかったと言えます。彼は、友人が小石につまずいて怪我をするのを心配している間に、自分自身が崖から転落してしまうようなタイプの人物です。彼は妻を深く愛しています。' WHERE character_id = 'CH015307';
UPDATE characters SET description = '親族：月読時子（大叔母）、柚崎絆（義父）、柚崎香乃香（義母）　柚崎司は柚崎ナサの妻である。 彼女についてはあまり知られていないが、謎めいた可愛らしさを持っていることは確かだ。  ツカサは、後ろで留め具で留めた長いピンクの髪と、ピンクがかった赤い瞳をしている。彼女はエレガントな服装とスカートを身につけている。自宅では、たいてい現代風の服を着ている。京都への旅行中は、花柄の浴衣を着ていた。 ツカサは穏やかで冷静な印象を与える。参照' WHERE character_id = 'CH015308';
UPDATE characters SET description = '彼女はカナメの同級生で、いつも彼女を探している。論理的思考に欠けており、いつも奇妙な結論を導き出す。一言で言えば、ドジっ子だ。（出典：とにかくかわいいWiki）' WHERE character_id = 'CH015309';
UPDATE characters SET description = '彼女はナサの中学時代の同級生で、彼と同い年だ。現在は電気店を経営しており、どうやら恋愛関係に対する明確な願望はないようだ。（出典：とにかくかわいいWiki）' WHERE character_id = 'CH015310';
UPDATE characters SET description = '彼女は長い間、銭湯の手伝いをしている。 若くてもとても大人びており、ナサの夫婦生活がうまくいくよう、いつも良いアドバイスをくれる。母親と同じように下ネタが大好きで、ナサが入浴中だとしても、男性用浴場の掃除を平気でこなすようだ。恥ずかしがり屋ではなく、ストレートな物言いを好む。' WHERE character_id = 'CH015311';
UPDATE characters SET description = '彼女は教育大臣を務めていたが、ナサとツカサが結婚してから数日後に辞任した。 その理由について、彼女は健康を心配しているとし、年齢のせいで今後政治に関与できなくなるかもしれないと語っている。彼女には多大な影響力と権力がある。実際、彼女がまだナサのアパートに住んでいた頃でさえ、ツカサの居場所を容易に突き止めていた。' WHERE character_id = 'CH015312';
UPDATE characters SET description = '彼女はカナメの姉だ。のんびり屋で間抜けなところもあるが、カナメは彼女の学習能力の高さから、彼女を「天才寄り」だと見なしている。 それとは対照的に、彼女はたいてい重要なことを誤解してしまい、あっという間に大混乱に陥ってしまう。彼女の最大の趣味はおそらくビデオゲームで、よくカナメに「一緒に遊ぼう」とせがむ。' WHERE character_id = 'CH015313';
UPDATE characters SET description = 'どうやら、幼い頃、ツカサが崖から落ちそうになった彼女を助けてくれたらしい。千歳は、その恩返しとして、自分の命をツカサのために捧げようとしている。当然ながら、彼女はツカサがナサの手に落ちることを望んでいない。彼女には、オーロラとシャーロットという2人のメイドがいる。 千歳は、強気な態度からすぐに泣き言を言うような態度へと一転してしまう性格だ。彼女はツカサを姉のように思っている。（出典：とにかくカワイイウィキア）' WHERE character_id = 'CH015314';
UPDATE characters SET description = 'NASAとツカサの飼い猫。' WHERE character_id = 'CH015315';
UPDATE characters SET description = '彼女は千歳のメイドの一人だ。素朴で無邪気な性格から、巨大な剣を手に狂乱状態になるまで、その性格は瞬く間に一変する。しかし、彼女はいつも満面の笑みを浮かべて幸せそうだ。千歳に言われたことは、おそらくためらうことなく何でもやってくれるだろう。' WHERE character_id = 'CH015316';
UPDATE characters SET description = '彼女は、ナサがかつて通っていた中学校の教師です。彼女はいつも仕事でとても忙しく、私生活を楽しむ時間はあまりありません。しかし、ナサの結婚生活がどれほど幸せなものかを知ると、彼女も将来の恋愛に対して前向きになっていきます。彼女は自分自身を「つまらない人間」だと思っています。' WHERE character_id = 'CH015317';
UPDATE characters SET description = '彼はヤクザではないが、その佇まいはすべてヤクザを彷彿とさせる。実際、彼はいつもヤクザのような格好をしており、普通の言葉の代わりに、より怪しげで怪しい言葉を使うことが多い。そのほか、彼は高校生であり、ナサのいとこでもある。（出典：とにかくかわいいWiki）' WHERE character_id = 'CH015319';
UPDATE characters SET description = '彼はナサが通っていた中学校の教師で、ヤナギ先生にデートを申し込む勇気は出したものの、とても内気な性格だ。' WHERE character_id = 'CH015320';
UPDATE characters SET description = '彼女は千歳のメイドの一人である。普段は真面目で冷静な性格だ。おそらく、千歳のもう一人のメイドであるシャルロットとは正反対の性格だろう。彼女はいつもシャルロットと一緒に現れ、シャルロットが衝動的になりすぎないように抑えようとしている。（出典：とにかくかわいいウィキア）' WHERE character_id = 'CH015321';
UPDATE characters SET description = 'カナメとアヤの母親。' WHERE character_id = 'CH015322';
UPDATE characters SET description = 'ユキトとチヤマルの父親。' WHERE character_id = 'CH015325';
UPDATE characters SET description = 'シアンの母親。' WHERE character_id = 'CH015337';
UPDATE characters SET description = 'リッシュの母親。' WHERE character_id = 'CH015341';
UPDATE characters SET description = '性別：男性　彼は帝国近衛隊に所属していた騎士だった。' WHERE character_id = 'CH015343';
UPDATE characters SET description = 'シアンの父親。' WHERE character_id = 'CH015346';
UPDATE characters SET description = 'かつては特に目立った出来事のないごく普通の日本のティーンエイジャーだったが、現在はファンタジーに強く傾倒し、魔法と剣術に卓越した才能を持つ貴族の三男――カインは、自分のペースで物事を進めるのが好きな、のんきな人物だ。 貴族でありながら、彼は人の身分で評価することはなく、他人が肩書きを盾に横暴な態度をとるのを嫌うことが多く、必要とあれば生意気な一面も見せる。自分の真の実力を隠しておいたほうが良いことは分かっているが……' WHERE character_id = 'CH015347';
UPDATE characters SET description = 'レックス・テラ・エフォートの三女であり、エフォート王国の第三王女である。カイン・フォン・シルフォードに救われた後、彼に恋をし、婚約を結んだ。' WHERE character_id = 'CH015355';
UPDATE characters SET description = 'ダルマティアはかつて、闇の王子に仕える四天王の一人だったが、現在は引退している。彼は調査を専門としている。' WHERE character_id = 'CH015371';
UPDATE characters SET description = '婚約者の手によって命を落とす脇役に転生してしまったレイリアナ・マクミランは、運命に翻弄されて死ぬのではなく、自分の人生を生き抜くことを決意した、強気なヒロインである。 絶望の淵で、彼女はノア・ワイクナイトのもとを訪れ、原作の運命による破滅を回避するため、政略結婚の契約を申し出る。' WHERE character_id = 'CH015398';
UPDATE characters SET description = '有名なウィンナイト公爵であり、この物語の男性主人公。本来のタイムラインではベアトリスと結ばれるはずだったが、レイリアナが自身の運命を回避するために元のタイムラインを変えたため、代わりにレイリアナに恋をしてしまった。シアトリッチの弟である。' WHERE character_id = 'CH015399';
UPDATE characters SET description = 'ノアに仕える、腕の立つ若き騎士。非常に物静かで、特に信頼できない相手に対しては、表向きは冷静沈着な態度をとる。非常に騙されやすく、甘いものが好きだ。アラサの血を引いていることを理由に、差別を受けている。' WHERE character_id = 'CH015404';
UPDATE characters SET description = 'ノアの異母兄であり、チャモスの王。片足が完全に麻痺している。女好きで、おせっかいでおしゃべりな性格だ。うっかり者に見えるが、実はかなり狡猾である。' WHERE character_id = 'CH015406';
UPDATE characters SET description = 'ヴィヴィアンの兄であり、王に仕える騎士。' WHERE character_id = 'CH015410';
UPDATE characters SET description = 'ベアトリス・トランシェットは、幼なじみであるレイリアナ・マクミランの親友だ。彼女はまた、レイリアナが登場する小説のヒロインでもある。小説によると、ノア・ウィンナイトは、彼女が親友であるレイリアナの死に関する謎を解き明かした後、彼女に恋をする。' WHERE character_id = 'CH015413';
UPDATE characters SET description = 'ラエリアナの元婚約者で、彼女の殺害を企んでいる人物。' WHERE character_id = 'CH015416';
UPDATE characters SET description = 'ノアに想いを寄せる貴族の女性。高慢で、身分が自分より低い人々を見下している。' WHERE character_id = 'CH015418';
UPDATE characters SET description = '職業：漫画家　一郎は少女漫画家であり、シェアハウスのオーナーでもある。彼は、妹のマチと弟のフミオの2人の弟妹を一人で養っている、賢明な人物だ。' WHERE character_id = 'CH015420';
UPDATE characters SET description = '職業：漫画家のアシスタント。彼女がアシスタントを務める「久我一郎」という漫画家からは「神級のアシスタント」と評されており、ある王国の王女であると自称する謎めいた人物である。' WHERE character_id = 'CH015421';
UPDATE characters SET description = '漫画家の友人であり、久我一郎の元アシスタント。' WHERE character_id = 'CH015423';
UPDATE characters SET description = '久我マチは、久我一郎の妹であり、久我文雄の姉である。彼女は元気で優しい性格の子供で、一郎が仕事に集中できるよう、よく文雄の世話をしている姿が見られる。' WHERE character_id = 'CH015424';
UPDATE characters SET description = 'フミオは、久我一郎と久我マチの弟である。彼は内気な子供で、めったに話さず、よく姉にべったりと寄り添っている姿が見られる。' WHERE character_id = 'CH015425';
UPDATE characters SET description = 'クガの編集者であり、モモカの夫。' WHERE character_id = 'CH015427';
UPDATE characters SET description = '彼女はクガの幼なじみで、クガの編集者である森国と結婚している。' WHERE character_id = 'CH015428';
UPDATE characters SET description = 'ルリのおじいさん。' WHERE character_id = 'CH015435';
UPDATE characters SET description = '羽鳥千世は「スレイ・ベギー」であり、本作の主要な主人公の一人である。彼女はエリアス・エインズワースの弟子であり、妻でもある。  幼い頃から愛を知らずに育ったチセは、魔法と不思議なつながりを持っており、そのせいで妖精たちを引き寄せてしまう。彼女は、強力な魔術師であるエリアスの世話と指導を受ける中で、自身の魔法の能力についてさらに理解を深めていく。（出典：『古の魔術師の花嫁』Wiki & Crunchyroll）' WHERE character_id = 'CH015455';
UPDATE characters SET description = '彼は、人間と妖精の両方の特徴を併せ持つ、古の魔術師である。その外見とは裏腹に、人間に対しては穏やかで礼儀正しく、人間に強い関心を寄せている。彼は、人間がなぜそのような感情を抱くのかを理解しているが、自身はそうした感情を一度も経験したことがない。ある日、彼は闇市場で羽鳥チセを買い取り、彼女を自分の魔術見習いにした。' WHERE character_id = 'CH015456';
UPDATE characters SET description = 'このカレッジに通う学生で、ナルシス・モーガムの授業でチセの隣に座っている同級生。普段はエイプリルとメイ・アトウッド、そしてフィロメラと一緒にいることで知られている。' WHERE character_id = 'CH015457';
UPDATE characters SET description = 'チセの友人であり、イーサンの姉。' WHERE character_id = 'CH015460';
UPDATE characters SET description = '闇市場で働く競売人。' WHERE character_id = 'CH015461';
UPDATE characters SET description = 'リアン・スクリムジョーは、羽鳥チセと同じ学年の学生である。彼は魔術に深い関心を抱く魔術師であり、トーリー・イニスに師事している。スクリムジョー家の出身ではあるが、同家を離れるつもりだと述べている。' WHERE character_id = 'CH015462';
UPDATE characters SET description = '同大学の学生で、羽鳥千世の同級生。ヴェロニカ・リッケンバッカーとよく一緒にいる姿が見られ、エイプリル・アトウッドの兄である。' WHERE character_id = 'CH015463';
UPDATE characters SET description = 'カレッジの魔術師。リンデルの元教え子である。' WHERE character_id = 'CH015465';
UPDATE characters SET description = 'チセの使い魔であり、チャーチ・グリムの一体である。チセと精神的な絆で結ばれており、彼女を妹のように思っている。' WHERE character_id = 'CH015467';
UPDATE characters SET description = 'ゾーイ・アイビーは、このカレッジに通う学生です。' WHERE character_id = 'CH015468';
UPDATE characters SET description = '魔術師であり、カレッジの教師。生徒たちには「ナルシシスト教授」と呼ぶことを許している。' WHERE character_id = 'CH015469';
UPDATE characters SET description = '魔術師であり、アリスの師匠。' WHERE character_id = 'CH015473';
UPDATE characters SET description = 'フィロメラ・サーガントは、このカレッジの学生です。彼女はよくヴェロニカ・リッケンバッカーと一緒にいる姿が見られます。' WHERE character_id = 'CH015474';
UPDATE characters SET description = 'エリアスとチセの邸宅の家政婦。' WHERE character_id = 'CH015479';
UPDATE characters SET description = '魔術師であり、カレッジの教師。魔法に対して並々ならぬ情熱を注いでいる。' WHERE character_id = 'CH015480';
UPDATE characters SET description = 'リズベス・サーガントは魔術師であり、サーガント家の年老いた家長である。' WHERE character_id = 'CH015483';
UPDATE characters SET description = '魔術師であり、レンフレッドの弟子。' WHERE character_id = 'CH015484';
UPDATE characters SET description = 'リンデルの魔法の師匠を務めた魔術師。名前をつけるのが好きで、リンデルとエリアスの名前も彼女が名付けた。' WHERE character_id = 'CH015485';
UPDATE characters SET description = '同大学の学生で、羽鳥千世の同級生。ヴェロニカ・リッケンバッカーとよく一緒にいる姿が見られ、メイ・アトウッドの兄である。' WHERE character_id = 'CH015487';
UPDATE characters SET description = 'ルーシー・ウェブスターは、このカレッジの学生です。' WHERE character_id = 'CH015490';
UPDATE characters SET description = 'ドラゴンズランドに住む、エリアスの師匠である魔術師。通称はリンデル。その称号は「エコー、花の歌」である。（出典：MAL）' WHERE character_id = 'CH015491';
UPDATE characters SET description = '魔法使いと、自分専用の魔法店を営むアーティフィサー。' WHERE character_id = 'CH015493';
UPDATE characters SET description = 'エリアスの家の近くの村に住んでいて、彼と顔見知りである神父。' WHERE character_id = 'CH015494';
UPDATE characters SET description = 'このカレッジに通う学生。内気な性格に見えるが、「セブン・シールズ」のメンバーではないため、他の学生たちよりは親しみやすいと自認している。また、幅広い分野に詳しい。' WHERE character_id = 'CH015495';
UPDATE characters SET description = '人間を安全な道から誘い出す妖精。' WHERE character_id = 'CH015496';
UPDATE characters SET description = 'カルタフィラスは、このシリーズで繰り返し登場する敵役の魔術師である。  （出典：『古の魔術師の花嫁』ウィキア）' WHERE character_id = 'CH015498';
UPDATE characters SET description = 'エルゼは、両手にガントレットを装備した冒険者だ。彼女は口数より行動を重んじるタイプで、よく考えもせずに先走って行動してしまう。双子の姉である。  （出典：Honey''s Anime）' WHERE character_id = 'CH015499';
UPDATE characters SET description = 'トウヤは、この異世界へやってきた少年だ。普段は礼儀正しいが、身近な人が危害を加えられそうだと感じると、躊躇しない一面も持っている。（出典：Honey''s Anime）' WHERE character_id = 'CH015500';
UPDATE characters SET description = 'リンゼは姉と一緒に街にいて、何かの罠に嵌められそうになったまさにその瞬間、トウヤに助けられた。彼女は物静かだが、時折その内なる強さを見せることもある。彼女は双子の妹である。（出典：Honey''s Anime）' WHERE character_id = 'CH015501';
UPDATE characters SET description = 'ベルファストの王女であり、トリストウィン王とユエル王妃の娘。ユミナは、父親が毒殺未遂に遭った際、トウヤがその傷を癒やしたことをきっかけに彼と出会った。ユミナは「ミスティック・アイズ」というヌル魔法を操る。これは、彼女の異色眼に由来する能力であり、人の本質を見抜く力を与えてくれる。 この力ゆえに、父を救った後のトウヤを包む、無私で優しいオーラを見たユミナは、これ以上の夫候補は決して見つからないと確信し、彼との婚約を申し出た。' WHERE character_id = 'CH015502';
UPDATE characters SET description = '極東の国イーシェンで武士の一家に生まれたヤエは、故郷を離れ、他国で腕を磨くために旅に出た。旅の途中で、トウヤの一行は彼女と出会い、彼女を襲った一団の悪党を撃退する手助けをした。その後、彼女はトウヤの旅に同行することを決意した。' WHERE character_id = 'CH015503';
UPDATE characters SET description = '「ヒルデ」という愛称で知られるヒルデガルト・ミナス・レスティアは、望月トウヤの妻の一人である。ヒルデはレスティア騎士王国の第一王女でもあり、現在はブルンヒルド公国でトウヤや他の皆と共に暮らしている。' WHERE character_id = 'CH015504';
UPDATE characters SET description = '元々はホームレスのスリだったが、縄張り争いのせいで彼女を狙っていた他の2人のスリからトウヤに助け出された後、彼は彼女をメイドとして雇うことにした。' WHERE character_id = 'CH015505';
UPDATE characters SET description = '「ルー」という愛称で知られるルシア・レア・レグルスは、望月トウヤの妻の一人である。ルーはレグルス帝国の第三王女でもあり、現在はトウヤや他の皆と共にブルンヒルド公国で暮らしている。' WHERE character_id = 'CH015507';
UPDATE characters SET description = 'アルフレッド・エルネス・オルトリンデ公は、ベルファスト国王の弟である。' WHERE character_id = 'CH015508';
UPDATE characters SET description = 'サクラは、望月東也の妻の一人である。彼女は暗殺未遂事件から、東也に救出されて一命を取り留めた。しかし、記憶喪失に陥ったため、東也から「サクラ」という仮の名を与えられた。 後に、彼女の本名はファルネーゼ・フォルネウスであることが明らかになるが、彼女は「サクラ」という名前を使い続けることを決める。実は彼女は、ゼノアスの魔界の後継者として計画されていた人物である。現在、彼女はブルンヒルド公国でトウヤと共に暮らしている。' WHERE character_id = 'CH015510';
UPDATE characters SET description = '神界の女神で、恋愛に関する事柄を司る。' WHERE character_id = 'CH015513';
UPDATE characters SET description = 'セシルは、メイドギルドに所属するメイドで、ブルンヒルド公国に移る前はベルファスト邸で働いていた。' WHERE character_id = 'CH015514';
UPDATE characters SET description = 'ミスメデの妖精族の長であるリーンは、ミスメデ王国の宮廷魔術師を務めており、独自の無効化魔法「プログラム」を使うことができる。 200年にわたり、彼女は「プログラム」を用いて、人間と交流できる自動テディベア「ポーラ」を作り出したが、ポーラにはまだ話す能力は備わっていない。' WHERE character_id = 'CH015519';
UPDATE characters SET description = 'マイカは「シルバー・ムーン」の宿の主人です。' WHERE character_id = 'CH015520';
UPDATE characters SET description = 'アルフレッド・アーネス・オルトリンデ公爵の娘であり、ユミナとはいとこ同士。スシーは友人たちに「スー」と呼ばれることを好む。トウヤの6人目の婚約者。' WHERE character_id = 'CH015523';
UPDATE characters SET description = 'フレドモニカは、レジーナ・バビロン教授からバビロンのハンガーの管理を任された、5000年の歴史を持つターミナル・ギノイドである。彼女の機体番号は28である。' WHERE character_id = 'CH015525';
UPDATE characters SET description = 'かつて「白虎」として知られていたコハクは、東野の旅の仲間であり、契約を結んだ獣である。彼女は「四神獣」の一角であり、同時に「魔獣」たちのリーダーでもある。' WHERE character_id = 'CH015527';
UPDATE characters SET description = '「神」――後に「世界の神」と呼ばれるようになった存在は、全能の神であり、トウヤが現在住んでいる世界だけでなく、彼が以前住んでいた世界でも、そこで起こる出来事をすべて支配している。この神が世界に降りてきた際、トウヤの祖父を装い、「望月真之介」という名を使用している。' WHERE character_id = 'CH015528';
UPDATE characters SET description = 'トウカは漫画『勇者が死んだ！』の主人公だ。彼は幼なじみのユナ・ユニスと同じく、チェザ村の農家である。トウカは太ももフェチで、収穫した野菜にニーソックスを履かせて妄想にふけるのが大好きだ。 トウカの平穏な生活は、悪魔が村を襲ったことで一変する。トウカは悪魔を倒し、村を守るために落とし穴を掘り、その罠に焼いたベーコンを餌として仕掛けた。しかし、その悪魔はベーコンが嫌いだったため、村を破壊し続け、ついに……' WHERE character_id = 'CH015531';
UPDATE characters SET description = 'モンスターから世界を救った有名な英雄。物語の冒頭で、不慮の事故により命を落としてしまう。' WHERE character_id = 'CH015532';
UPDATE characters SET description = 'ユナ・ユーニスはチェザ村の出身で、トウカの幼なじみだ。彼女はヒーローに片思いしており、トウカを「変態」だと思っている。' WHERE character_id = 'CH015533';
UPDATE characters SET description = 'アンリは英雄の仲間の一人である。彼女はネクロマンサーだ。英雄の死後、アンリは東香の意識を英雄の体に移し、東香が英雄の使命を引き継げるようにした。' WHERE character_id = 'CH015534';
UPDATE characters SET description = 'エセルが初めて登場するのは、第1章の「ヘルズ・ゲート」の前だ。彼女は悪名高い山賊であり、罠作りの達人である。29歳だ。' WHERE character_id = 'CH015538';
UPDATE characters SET description = 'モアランの市長。市長としてのキャリアの初めは富を追い求めていたが、やがて町の人々を愛するようになる……そしてニーソックスも。' WHERE character_id = 'CH015539';
UPDATE characters SET description = 'カイルは主人公の仲間の一人である。主人公の死後、彼は主人公の座を引き継ごうとする。' WHERE character_id = 'CH015543';
UPDATE characters SET description = '王国で最も強い4人の戦士の一人。' WHERE character_id = 'CH015544';
UPDATE characters SET description = '王都にある孤児院の院長。' WHERE character_id = 'CH015547';
UPDATE characters SET description = 'ユナとミリーの父親。女性の胸に異常な執着があり、トウカを嫌っている。' WHERE character_id = 'CH015548';
UPDATE characters SET description = 'ボッセ王国の長男である王子。ボッジは、生まれつき異常に小柄で、虚弱体質、そして耳が聞こえない。彼は、伝説的な父であるボッセ王の影の下で生きてきた、力のない王子である。 父の足跡をたどり、世界一の王になりたいと願っている。ボッジは極めて勤勉で誠実であり、その人柄ゆえに、たとえ彼のことを常に理解できなくても、人々は自然と彼に惹きつけられる。' WHERE character_id = 'CH015550';
UPDATE characters SET description = 'カゲは、文字通りの「影」であり、ボッジにとって初めての友達となる。' WHERE character_id = 'CH015551';
UPDATE characters SET description = 'デシャの兄と' WHERE character_id = 'CH015555';
UPDATE characters SET description = '太古の神であり、かつて冥界の王であった。デシャ、デスパ、そして' WHERE character_id = 'CH015556';
UPDATE characters SET description = 'デスパの馬。' WHERE character_id = 'CH015562';
UPDATE characters SET description = '元女王であり、ボッジの実の母親。' WHERE character_id = 'CH015564';
UPDATE characters SET description = 'ボッセ王の2番目の妻であり、現女王。ダイダの実の母親であり、ボッジの継母である。もともとは近隣の領地／王国出身の巫女だった。' WHERE character_id = 'CH015566';
UPDATE characters SET description = '病気の母親のために薬を買おうとしている少女。' WHERE character_id = 'CH015570';
UPDATE characters SET description = '彼はボッセ王国の第二王子であり、第二代国王である。ボッセとヒリングの息子であり、ボッジの弟である。' WHERE character_id = 'CH015571';
UPDATE characters SET description = 'ボッセ王国の王であり、ボッジーとダイダの父。王のランキングで7位となった。' WHERE character_id = 'CH015574';
UPDATE characters SET description = 'ヒリングのボディーガード。' WHERE character_id = 'CH015576';
UPDATE characters SET description = '「王たちのランキング」で第2位にランクインする冥界の王。デスパ兄弟の二人ともの実の兄である。' WHERE character_id = 'CH015577';
UPDATE characters SET description = '水星から転入してきた、パイロット学科の2年生。スレッタは内気で、コミュニケーション能力にやや欠ける。彼女は、水星で開発された「ガンダム・エアリアル」のパイロットである。' WHERE character_id = 'CH015597';
UPDATE characters SET description = '経営戦略学科の2年生で、容姿端麗かつ学業成績も優秀な学生。ミオリーネは、ベネリット・グループの社長であり、同校の理事長を務めるデリング・レンブランの一人娘である。彼女は父親に対して強い反抗心を抱いている。  ミオリーネは余暇にガーデニングに興味を示しており、特にトマト栽培に力を入れているようだ。（出典：『機動戦士ガンダム マーキュリーの魔女』公式サイト）' WHERE character_id = 'CH015598';
UPDATE characters SET description = '彼はアース寮の2年目の整備士だ。ソフトウェアに精通したオタクで、オヘロとは「悪友」として行動を共にしている。' WHERE character_id = 'CH015599';
UPDATE characters SET description = 'アース寮に所属する3年生の整備士。自分のペースで物事を進める、分別のある人物だ。占いが大好きで、故郷から連れてきた家畜（ヤク、ヤギ、ニワトリ）を大切にしている。' WHERE character_id = 'CH015600';
UPDATE characters SET description = 'グラスリー・ハウスに所属するパイロット学科2年生の女子学生。シャディックを支える女子学生の一人である。一見親しみやすい人物に見えるが、男子学生と女子学生では態度を変える、心根の悪い人物である。' WHERE character_id = 'CH015601';
UPDATE characters SET description = '密輸業者・馮俊と共に行動する宇宙船のパイロット。' WHERE character_id = 'CH015602';
UPDATE characters SET description = 'ベネリット・グループの3つの事業部門のうちの一つであるペイル・テクノロジーズを、議会制を通じて統括する4人の共同CEOのうちの1人。' WHERE character_id = 'CH015603';
UPDATE characters SET description = 'ベネリット・グループの3つの事業部門のうちの一つであるペイル・テクノロジーズを、議会制を通じて統括する4人の共同CEOのうちの1人。' WHERE character_id = 'CH015604';
UPDATE characters SET description = 'グラスリー寮に住むパイロット科3年生の女子学生。シャディックを支える女子学生の一人である。静かに第六感を使う、謎めいたタイプだ。' WHERE character_id = 'CH015605';
UPDATE characters SET description = '彼女はジェトゥルク・ハウスに所属する2年目のパイロットだ。無鉄砲で頑固なパイロットというタイプである。パイロットとしてのゲルを尊敬している。' WHERE character_id = 'CH015606';
UPDATE characters SET description = 'ペイル・テクノロジーズの研究員として、彼女はガンダム・ファラクトの開発に携わっている。' WHERE character_id = 'CH015607';
UPDATE characters SET description = 'ベネリット・グループの3つの事業部門のうちの一つであるペイル・テクノロジーズを、議会制を通じて統括する4人の共同CEOのうちの1人。' WHERE character_id = 'CH015608';
UPDATE characters SET description = '同グループの3つの部門の一つであるジェトゥルク重機械の御曹司であり、操縦学科の3年生。ゲルは気性が荒く、怒りっぽい。ジェトゥルク家のエースパイロットとして、自身の腕前には絶対の自信を持っている。（出典：公式サイト）' WHERE character_id = 'CH015609';
UPDATE characters SET description = '彼女はビジネス戦略学科の1年生で、アース寮に住んでいる。明るく人懐っこい性格だ。恋愛の話をするのが大好きで、男子学生の間で人気がある。' WHERE character_id = 'CH015610';
UPDATE characters SET description = '彼女はグラスリー・ハウスの3年目のパイロットです。彼女は才能あふれる女性で、シャディックの右腕として、学校内外での彼の仕事を支えています。' WHERE character_id = 'CH015611';
UPDATE characters SET description = 'ブリオン・ハウスに所属する1年生の整備士。決闘委員会のメンバーである。移動型クラフトやその他のメカに精通しており、常に自分で改造したハローを持ち歩いている。' WHERE character_id = 'CH015612';
UPDATE characters SET description = '地球で活動する反スペース派組織「ドーン・オブ・フォールド」のリーダー。地球住民の地位向上を掲げ、ゲリラ活動を展開している。' WHERE character_id = 'CH015613';
UPDATE characters SET description = '同グループの3つの部門のうちの一つであるペイル・テクノロジーズが支援するトップパイロット。パイロット学科の3年生。エランは寡黙で孤独を好む性格で、学校では誰に対しても心を開こうとしない。スレッタに興味を抱いている。（出典：公式サイト）' WHERE character_id = 'CH015615';
UPDATE characters SET description = 'ソフィーはサディスティックで攻撃的な少女だ。興奮しやすく衝動的であり、敵と戦ったり脅したりすることを楽しんでいるようだ。  戦闘ではすぐに興奮してしまうソフィーは、スレッタやエアリアルといった仲間の魔女やガンダムにも興味を持っており、彼女たちの決闘の映像を視聴していた。そして、両者と戦うことに陶酔し、両者に対して執着心を抱くようになった。' WHERE character_id = 'CH015616';
UPDATE characters SET description = 'マーキュリーに本社を置く「新星開発株式会社」のCEO。ガンダム・エアリアルの開発を担当し、スレッタの母親でもある。身体機能を補助するための特殊なヘッドギアを常に着用している。' WHERE character_id = 'CH015617';
UPDATE characters SET description = '地球の指定復興計画区域に住む少女。「ドーン・オブ・フォールド」に加わり、最前線へ向かった父親の安否を案じている。' WHERE character_id = 'CH015618';
UPDATE characters SET description = '彼女はヴァナディス研究所を代表する研究者だった。「GUND FORMAT」理論の主要な提唱者として、彼女は同僚の研究者たちから尊敬を集めていた。' WHERE character_id = 'CH015619';
UPDATE characters SET description = 'チュチュは問題を抱えた少女で、地球人として、地球人を下っ端と見下すスペース人の多くから差別を受けている。多くのスペース人と同じ学校に通っているため、彼女は地球人の友人たちと共に、日常的に虐待や嫌がらせの標的となってきた。 この状況に加え、自国民がスペース人による抑圧や搾取を受けていることも相まって、チュチュはすべてのスペース人に対して極めて否定的な印象を抱くようになり、しばしば彼らを「クソスペース人」と嘲り、激しく非難している。' WHERE character_id = 'CH015620';
UPDATE characters SET description = 'ベネリット・グループの社長であり、監査機関「カテドラ」の監督責任者。' WHERE character_id = 'CH015621';
UPDATE characters SET description = '彼女はジェトゥルク・ハウスに通う、整備科の2年生だ。クールで頭が良く、優等生タイプの女の子だ。フェルシと同じように、彼女もゲルを慕っている。' WHERE character_id = 'CH015622';
UPDATE characters SET description = 'ラウダ・ニールは、パイロットプログラムの3年目を迎えている。彼はジェトゥルク・ハウスの副寮長を務めている。ゲルの異母弟であり、同じ学年ではあるが、彼の方が年下である。兄とは異なり、彼は冷静で理性的だ。' WHERE character_id = 'CH015623';
UPDATE characters SET description = 'ドミニクス特殊部隊の指揮官。21年前、ケナンジはヴァナディス事件の際、ベギル・ベウのパイロットを務めていた。' WHERE character_id = 'CH015624';
UPDATE characters SET description = 'サマヤ家の父。' WHERE character_id = 'CH015625';
UPDATE characters SET description = '機械学科の2年生で、「アースハウス」に所属している。メカが大好きで、スレッタの「ガンダム・エアリアル」にとても興味津々だ。ニカは整備の腕が抜群で、チュチュの「デミ・トレーナー」をカスタマイズしたことを誇りに思っている。' WHERE character_id = 'CH015626';
UPDATE characters SET description = '彼はアース寮に通う整備科の2年生だ。陽気な性格で、いつも場を盛り上げる存在だ。寮の生活費を賭け事に使い果たしてしまうギャンブラーでもある。' WHERE character_id = 'CH015627';
UPDATE characters SET description = '彼は「アース寮」の寮長であり、ビジネス戦略学科の3年生だ。優柔不断で、やや頼りないリーダーである。個性の強い寮生たちとの付き合いに苦労している。' WHERE character_id = 'CH015628';
UPDATE characters SET description = 'フォルクヴァングルで家族と暮らす4歳の女の子。エルノラとナディムの娘である。エリクトは純真無垢な子供で、好奇心旺盛すぎて、両親も時々どう扱っていいか困ってしまうほどだ。' WHERE character_id = 'CH015629';
UPDATE characters SET description = '反スペース派組織「ドーン・オブ・フォールド」のモビルスーツ小隊長。部隊から厚い信頼を寄せられているベテランの戦士である。' WHERE character_id = 'CH015630';
UPDATE characters SET description = '同グループの3つの部門の一つであるグラスリー・ディフェンス・システムズのCEOの養子。パイロット学科の3年生で、グラスリー・ハウスのリーダーを務めている。まだ学生ながら、シャディクはビジネス面でもその手腕を発揮しており、次世代の経営幹部候補と目されている。（出典：公式サイト）' WHERE character_id = 'CH015632';
UPDATE characters SET description = 'グラスリー・ハウスに暮らすパイロット養成課程の2年生。彼女はとてつもなく前向きな考え方で、周囲の人々に笑顔を振りまいている。' WHERE character_id = 'CH015633';
UPDATE characters SET description = 'グラスリー・ハウスに住むパイロット科2年生の女子学生。シャディックを支える女子学生の一人。内気で自信がなく、心配性だ。メイジーとは仲が良い。' WHERE character_id = 'CH015634';
UPDATE characters SET description = 'ミオリネから、彼女を地球へ運ぶよう依頼を受けた宇宙密輸業者。' WHERE character_id = 'CH015635';
UPDATE characters SET description = '地球の指定復興計画区域に住む少年。セドは年齢相応に臆病だが、シーティアを気遣って彼女に付き添っている。' WHERE character_id = 'CH015636';
UPDATE characters SET description = 'ベネリット・グループの3つの事業部門のうちの一つであるペイル・テクノロジーズを、議会制を通じて統括する4人の共同CEOのうちの1人。' WHERE character_id = 'CH015637';
UPDATE characters SET description = 'ノレアは、反スペース人テロ組織「ドーン・オブ・フォールド」に関与した地球人である。彼女はソフィーと共にガンダムパイロットとしての訓練を受けた。ノレアは冷静沈着な人物を装っており、会話の際も往々にして淡々とした態度を保っている。 彼女は、特にソフィーに対して、主要な目標に集中するよう頻繁に注意を促す。しかし、地球を見捨てたスペース人に対して、そして地球を離れた他の地球人に対しても、非常に根深い憎しみを抱いている。彼女は……' WHERE character_id = 'CH015638';
UPDATE characters SET description = '彼はアース寮の3年生の整備士だ。口数が少なく、物静かな性格だ。寮の最も重要なメンバーの一人であり、他の寮生たちにとって頼りになる存在である。' WHERE character_id = 'CH015639';
UPDATE characters SET description = '彼女はブリオン・ハウスのビジネス戦略学科の2年生だ。決闘委員会のメンバーでもある。セセリアは皮肉屋で、口が悪く、皮肉を言うことに関しては彼女に勝る者はいない。' WHERE character_id = 'CH015640';
UPDATE characters SET description = 'ベネリット・グループの3つの事業部門のうちの一つであるグラスリー・ディフェンス・システムズのCEO。' WHERE character_id = 'CH015642';
UPDATE characters SET description = '先端に「アナーキー」のシンボルが刻まれた杖を振るう、気難しい魔法少女。彼女は様々な物体を生成したり破壊したりすることができる。アナーキーは、SSCを倒して、また普通の少女に戻りたいと願っている。' WHERE character_id = 'CH015644';
UPDATE characters SET description = 'スールストロミングが大好きな、とてつもなくエッチな魔法少女。ほとんど何でも切り裂くことができる、奇妙な形の鎌を操る。彼女の願いは、SSCがいなくなった後に、あるロックバンドのライブを観ることだ。' WHERE character_id = 'CH015645';
UPDATE characters SET description = 'ガスマスクを被り、ブルーにしか理解できないような口癖で話す魔法少女。巨大な魔法の注射器を操り、様々な種類の薬を作るのが得意だ。彼女の願いは、いつかメイドカフェで働くことである。' WHERE character_id = 'CH015646';
UPDATE characters SET description = 'メイドカフェの店員。' WHERE character_id = 'CH015655';
UPDATE characters SET description = 'クリモニアの町に住む10歳の少女。母親と妹と一緒に暮らしている。フィナの父親は彼女がまだ幼い頃に亡くなり、母親は重い病気にかかって寝たきりになっている。 家族を養うため、フィナは幼い頃から働かざるを得ず、母親の薬や家族の食費を稼ぐために働いている。まだ10歳という年齢ゆえにできることは限られており、時折ギルドの手伝いとしてモンスターの解体作業を行うことで、わずかな賃金を稼いでいる。フィナは優しく、' WHERE character_id = 'CH015708';
UPDATE characters SET description = '一人暮らしの15歳の少女。12歳の時、できるだけ『ワールド・ファンタジー・オンライン』をプレイしたかったため、自らの意思で人付き合いを避けるようになった。 両親に1億円を渡した後、両親は彼女を放任するようになり、お金が尽きてしまう時だけ家に帰ってくるようになったため、ユナは両親から身を隠すためにこっそりと高級マンションに引っ越した。そこで彼女は、ほぼ一日中『ワールド・ファンタジー・オンライン』をプレイし、残りの時間は食事と睡眠に費やしている。' WHERE character_id = 'CH015709';
UPDATE characters SET description = 'フローラの母であり、エルファニカの女王。' WHERE character_id = 'CH015718';
UPDATE characters SET description = 'ミサーナの母親。' WHERE character_id = 'CH015723';
UPDATE characters SET description = 'クマキュウは、クマユルと共にユナの召喚獣である。クマキュウはシロクマの姿をしている。通常の成体の姿では大きなクマほどの大きさだが、子グマの姿になって体を小さくすることもできる。大きかろうと小さかろうと、クマキュウはかわいいテディベアのように見える。  （出典：クマ・クマ・クマ・ベア Wiki）' WHERE character_id = 'CH015724';
UPDATE characters SET description = 'フィナとシュリの母親。' WHERE character_id = 'CH015725';
UPDATE characters SET description = 'リズは孤児院のボランティア兼職員です。また、孤児たちの指導員も務めています。ボーと同じように、彼女は子供たちをとても大切に思い、教えることを生業としています。' WHERE character_id = 'CH015728';
UPDATE characters SET description = 'モリンの姪であり、カリンのいとこ。' WHERE character_id = 'CH015730';
UPDATE characters SET description = 'ミサーナの父親。' WHERE character_id = 'CH015731';
UPDATE characters SET description = 'クリモニアの町に住む貴族の令嬢。父親はクリモニアの領主であり、二人はその町にある大邸宅で暮らしている。一方、ノワールの母親と妹は首都で一緒に暮らしている。  ノワールは少し甘やかされて育ったところがあり、誇り高いところもあるが、それが不快に感じられるほどではなく、むしろ可愛らしく子供っぽい。彼女は、ある程度までは自分の身分とは異なる人々と付き合うことを気にしないようで、身分が異なるにもかかわらずフィナと友達になった。' WHERE character_id = 'CH015732';
UPDATE characters SET description = 'ギルドのスタッフであり、クリモニアの住民である。' WHERE character_id = 'CH015735';
UPDATE characters SET description = '王都に住む高貴な少女。シャイアはノワールの姉であり、クリフとエレノア・フォクロゼの娘である。現在は母親と一緒に暮らし、王立アカデミーに通っているが、妹と父親はクリモニアで暮らしている。  シアはユナと出会う前は、非常に高慢で傲慢な性格だった。当初、彼女は自分が学校で最も強い生徒の一人であり、自分より強い少女はいないと信じていたが、ユナに完敗を喫した後、' WHERE character_id = 'CH015739';
UPDATE characters SET description = 'クリモニアのギルド受付係の女性。' WHERE character_id = 'CH015740';
UPDATE characters SET description = 'ボウはクリモニアにある孤児院の院長です。彼女は預かっている子供たちを心から愛していますが、資金が不足していたため、子供たちのために十分な支援をすることができませんでした。しかし、資金管理を担当していたローランドが、孤児院への資金配分を怠っていたところをクリフに捕まえられるまでは、そうでした。' WHERE character_id = 'CH015742';
UPDATE characters SET description = 'クマユルは、クマキュウと並んでユナの召喚獣である。クマユルはクロクマの姿をしており、通常の成獣の姿では大きなクマほどの大きさだが、子グマの姿になると体を小さくすることもできる。大きかろうと小さかろうと、クマユルはかわいいテディベアのように見える。  （出典：クマ・クマ・クマ・ベア Wiki）' WHERE character_id = 'CH015747';
UPDATE characters SET description = 'ネルトはドワーフの鍛冶屋の店主です。' WHERE character_id = 'CH015758';
UPDATE characters SET description = 'ハッピーは、エクシード星出身の機械猫であり、レベッカ・ブルーガーデンの相棒であり、『エデンズ・ゼロ』のクルーの一員である。彼の能力「ハッピー・ブラスターズ」により、エーテル弾を発射する一対の銃へと変身することができる。この弾は、標的を無力化できるほどの威力を持つが、殺すことはできない。' WHERE character_id = 'CH015768';
UPDATE characters SET description = '物語の主人公であるシキは、人懐っこいものの社交が苦手な少年で、ロボットたちが暮らす惑星グランベルにあるファンタジーテーマパーク「グランベル王国」で、唯一の人間として暮らしている。 彼は、パークのアニマトロニクス製魔王から受け継いだ「エーテルギア」という能力を持っており、これにより機械のような力を発揮することができる。シキは「サタン・グラビティ」と呼ばれるその派生能力を使い、自身の重力を変化させたり方向を変えたりすることができる。人工の家族に励まされながら……' WHERE character_id = 'CH015769';
UPDATE characters SET description = 'ヒロインのレベッカ・ブルーガーデンは、惑星ブルーガーデン出身の親切で元気な少女。チャンネル登録者数100万人を目標に、さまざまな惑星を旅して動画を撮影し、動画共有サイト「アオネコ」の自身のチャンネルにアップロードしている。彼女は「アクア・ウィング」という宇宙船を操縦しており、この宇宙船は海上船としても機能する。  レベッカの能力「リーパー」は、ジャンプ能力を強化するエーテルギアであり、彼女に驚異的なスピードと敏捷性を与えてくれる。' WHERE character_id = 'CH015770';
UPDATE characters SET description = 'ホムラ・コウゲツは、『エデンズ・ゼロ』に登場する魔王の一味の一員であり、自らを「プラネット・ブルーガーデン出身の騎士」と称している。彼女の能力「ソウルブレード」は、エーテルギアの一種であり、エーテルでできた刃物を作り出すことができる。' WHERE character_id = 'CH015771';
UPDATE characters SET description = 'レベッカ・ブルーガーデンと共に拉致されたB-Cubeのユーザー。B-Cubeで「モグモグチャンネル」という食をテーマにしたチャンネルを運営しており、そのコンテンツは主に食事に関するものだ。' WHERE character_id = 'CH015772';
UPDATE characters SET description = '彼は機械であり、魔王の「四つの闇の星」の一人である。' WHERE character_id = 'CH015773';
UPDATE characters SET description = 'シスター・アイヴリーは「四つの輝く星」の一員である。彼女の能力「ヒール・アトマイザー」は、ヒーリング・エーテル系の能力であり、傷を癒やし、負の状態異常を解除し、生体機械を修復することができる。 シスターは短気で、からかうのが好きで、のんびりとした性格だが、責任感が強く、味方に対しては親しみやすい一面もある。サディスティックな一面もあり、拷問を楽しむ。治癒できないものを嫌う。シスターは、機械にとって死が最終的な結末であることを受け入れられない人物であることが示されている。' WHERE character_id = 'CH015774';
UPDATE characters SET description = 'ラビリア・クリスティは、ギルド「シューティング・スターライト」に所属する冒険者であり、B-キューバーでもある。' WHERE character_id = 'CH015775';
UPDATE characters SET description = '彼は「マシン」であり、魔王の「四つの闇の星」の一人である。' WHERE character_id = 'CH015776';
UPDATE characters SET description = 'シャオメイは、予知能力を持つことから、冷静で真面目な性格であると同時に、知識も豊富であることが描かれている。彼女の予知能力では特定の結果を予測できないため、シャオメイは人々の戦いを観戦することに興味を持っており、その興味は、彼女が明らかに興奮し、高揚するほどに高まっていることが示されている。' WHERE character_id = 'CH015777';
UPDATE characters SET description = 'ジンは、かつて「ローグ・アウト」というチームに所属していたサイボーグである。彼の能力「ウィンド・レイジ」は、台風のように風を操るエーテルギアの一種だ。ジンは妹のクリーネを大切に思っており、彼女に近づこうとする男を誰であれ嫌っている。' WHERE character_id = 'CH015778';
UPDATE characters SET description = '彼は機械であり、魔王の「四つの闇の星」の一人である。' WHERE character_id = 'CH015779';
UPDATE characters SET description = 'ピノは、「エデンズ・ゼロ」のクルーに加わった小型のアンチボットマシンだ。彼女はEMP（電磁パルス）を放出することができ、これにより電子機器を数秒間ショートさせたり、使用中のエーテルギアの効果を無効化したりすることができる。  彼女のデジタルアバターは、ウサギのような耳をした人間の少女に似ている。首には、大きなハートが一つあしらわれたネクタイを締めている。' WHERE character_id = 'CH015780';
UPDATE characters SET description = '彼は「オラシオン・セイス・ガラクティカ」の一員であり、「ベリアル・ゴア」の元所有者、そしてサクラ・コスモスの裏社会で最も悪名高い人物である。エレメント4は彼の配下にある。' WHERE character_id = 'CH015781';
UPDATE characters SET description = 'ラグナ・ハサートは、ドラッケン・ジョー率いる「エレメント4」の水の要素を担うメンバーである。また、俳優としても活動している。ラグナの能力は「ティアーズ・ラヴァー」というエーテルギアの一種で、涙を流した者を水に変えることができる。彼はファッションが好きで、乾燥した環境が嫌いだ。' WHERE character_id = 'CH015782';
UPDATE characters SET description = '彼は機械であり、魔王の「四つの闇の星」の一人である。' WHERE character_id = 'CH015783';
UPDATE characters SET description = 'ハーミット・ミオは、「フォー・シャイニング・スターズ」のメンバーであるアンドロイドだ。彼女の能力「マスターコード」は、プログラムハッキングの一種である。ハーミットは服やビデオゲームが好きで、以前は人間が嫌いだったが、今はもうそうではない。' WHERE character_id = 'CH015784';
UPDATE characters SET description = 'ドラッケン・ジョーのチームの一員として活動していた、ロボットの体に宿った知性を持つコンピュータプログラム。' WHERE character_id = 'CH015785';
UPDATE characters SET description = '彼は、ドラッケン・ジョー率いる「エレメント4」の「土」の要素を担う存在である。' WHERE character_id = 'CH015786';
UPDATE characters SET description = '彼は、エルシー・クリムゾンやドラッケン・ジョーと同様に、「オラシオン・セイス・ガラクティカ」の一員である。彼は「アオイ・コスモス」を統治している。' WHERE character_id = 'CH015787';
UPDATE characters SET description = 'ウィッチ・リグレットは「四つの輝く星」の一員である。彼女はエデンズ・ゼロの防衛を担っている。彼女の能力「シールド・エーテル」により、エーテルでできたバリアを生み出すことができる。   ウィッチは非常に忠実で、ジギーとその養孫であるシキに対して深い敬意を抱いている。普段は感情を表に出さないが、ウィッチも感情を示すことはできる。ただ、他人に自分の顔を見せることを恥ずかしく思っている。' WHERE character_id = 'CH015788';
UPDATE characters SET description = '彼は、ドラッケン・ジョー率いる「エレメント4」の「火の要素」を担う存在である。' WHERE character_id = 'CH015789';
UPDATE characters SET description = 'ディエゴ・レイエスはアンドロイドであり、かつてドラッケン・ジョーのチームの一員だった。' WHERE character_id = 'CH015790';
UPDATE characters SET description = 'シュラは、皇帝の息子であるという立場を盾に、アオイ・コスモスにあるあらゆるもの――人間さえも――を自分のものだと主張する、残酷でサディスティックな青年である。彼は、自分の気に入らない相手なら誰であれ殺してしまう。父親の前では、本性を隠し、敬意を払う息子という役を演じている。また、彼は重力エーテルギアも操る。' WHERE character_id = 'CH015791';
UPDATE characters SET description = 'モスコは、『エデンズ・ゼロ』号の船内での雑用を担当する機械であり、かつては「ローグ・アウト」というチームに所属していた傭兵である。彼は相撲の達人であり、相撲の技を駆使して戦う。シスターや小動物が好きだが、幽霊は嫌いだ。' WHERE character_id = 'CH015792';
UPDATE characters SET description = '彼は「エデンズ・ワン」の船長であり、ジギーの命令に従っている。' WHERE character_id = 'CH015793';
UPDATE characters SET description = '彼は、X442年に惑星ノルマで活動していた犯罪組織のリーダーである。その後、老いた姿や、X442年のシビルより年を重ねた姿として登場する。彼はドラッケン・ジョーの下で、借金で縛られた奴隷として働いている。' WHERE character_id = 'CH015794';
UPDATE characters SET description = 'ジギーのかつての師匠。' WHERE character_id = 'CH015795';
UPDATE characters SET description = 'ヴァイスは『エデンズ・ゼロ』のメンバーであり、惑星ノルマ出身の元泥棒である。彼の能力は、機械を操るエーテルギア「マキナ・メイカー」だ。ヴァイスは自己中心的で頑固、虚栄心が強く、変態的な一面も持つ男だ。しかし、友人に対しては思いやりがあり、彼なりのやり方で他者を気遣う面もある。 ワイズはお金とバニーガールが好きで、勉強が嫌いだ。' WHERE character_id = 'CH015796';
UPDATE characters SET description = '彼女は、ドラッケン・ジョーの指揮下にある「エレメント4」の「風」の要素を担うキャラクターである。彼女の能力「ウィンド・スナッチ」は、エーテルギアの一種であり、風を操って周囲にあるあらゆるものを奪い取ることができる。ジンは彼女の兄である。クリーネは兄やかわいいものが好きで、スパムメッセージが嫌いである。' WHERE character_id = 'CH015797';
UPDATE characters SET description = '彼はサクラ・コスモスの銀河情報局の局長である。現在は「シューティング・スターライト」のギルドマスターとして潜入活動を行っている。彼のエーテルギアは「神の眼」と呼ばれ、それを使って人々の居場所を把握することができる。' WHERE character_id = 'CH015798';
UPDATE characters SET description = '茜は小学5年生の女の子で、内向的で少しおとなしい性格だ。クラスではみんなから「死神」と呼ばれ、からかわれている。事情もわからないまま何度も戻ってくる高田くんのことを、彼女は気にしてしまっている。' WHERE character_id = 'CH015799';
UPDATE characters SET description = '高見宮の第15代巫女' WHERE character_id = 'CH015809';
UPDATE characters SET description = '江戸時代からエルダの家庭医を務めている、現在の女性医師。' WHERE character_id = 'CH015810';
UPDATE characters SET description = '小糸の妹で、小学生。彼女はプロ並みの料理の腕前を持っている。' WHERE character_id = 'CH015813';
UPDATE characters SET description = '近くのもんじゃ焼き店で働いており、小糸さんのことをよく知っている女性。' WHERE character_id = 'CH015818';
UPDATE characters SET description = '高校1年生。対人恐怖症で、人の感情を理解するのが苦手な真面目な少女。サロンの品位を大切にしている。カフェでは優しい先輩役を務め、ヒメにとって頼りになる「お姉さん」的存在だ。' WHERE character_id = 'CH015821';
UPDATE characters SET description = '高校1年生。 「誰からも愛されている」という嘘つきで、出会うほぼすべての人に対して親しみやすいふりを続けている。彼女の素顔を知っている相手に対しても、めったに警戒を解くことはない。金持ちと結婚することを望んでいる。カフェでは、無邪気な後輩やミツキの「妹」という役を演じている。' WHERE character_id = 'CH015822';
UPDATE characters SET description = '高校3年生。仕事以外の時はギャル風の格好をしている。職場の和をとても大切にしていて、恋愛が原因で同僚が傷つくのを嫌う。カフェでは、メガネをかけたクールな先輩という役柄を演じており、カノコにとっては「お姉さん」的存在である。' WHERE character_id = 'CH015823';
UPDATE characters SET description = 'カフェの厨房スタッフ。' WHERE character_id = 'CH015824';
UPDATE characters SET description = '腕に怪我を負った「リーベ」の店長。後輩キャラであり、カフェのマスコットも兼ねている。子供っぽい外見とは裏腹に、大人としての落ち着きを持ってスタッフを見守っている。' WHERE character_id = 'CH015825';
UPDATE characters SET description = '高校1年生で、ヒメの親友。ヒメを激しく守ろうとする一方で、彼女に恋心を抱いているが、その想いが報われることを望んでいない。物腰は穏やかに見えるが、実は非常に率直な性格だ。   カフェでは、内気な後輩やスミカの「妹」役を演じている。リーベのキャラクターを演じている時以外は、普段は眼鏡をかけている。' WHERE character_id = 'CH015826';
UPDATE characters SET description = '宝探しが大好きな、明るく元気な少年。生まれつき冒険心旺盛なロイは、祖父から聞いた伝説の古代の冒険者のように、まだ見たことのないポケモンに会い、伝説のポケモンとバトルするために旅に出ようとしている。彼は、祖父から譲り受けた謎めいた古代のポケモンボールを所持している。' WHERE character_id = 'CH015844';
UPDATE characters SET description = 'リコは『ポケモン・ホライズンズ』の主人公の一人です。彼女は祖母から贈られた謎めいたペンダントを持っています。リコは「ライジング・ボルトタッカーズ」の一員として彼らと共に旅をしているため、インディゴ・アカデミーには遠隔で通っています。  彼女は親切で礼儀正しい少女だが、プレッシャーのかかる状況ではうまく対応できない。内気な性格ながらも、リコはすぐに友達を作ることができる。' WHERE character_id = 'CH015845';
UPDATE characters SET description = 'フリーデはポケモンの教授であり、「ライジング・ボルトタッカーズ」のリーダーである。  フリーデは若く有能なトレーナーのように見えますが、少々うっかり屋で物忘れが激しく、時には友人たちに伝えるべきことを忘れてしまうこともあります。それでも、フリーデは自分のチームを非常に大切にしており、船を守るために自ら危険を冒したり、敵からチームメイト、特に年下のメンバーを守ったりします。' WHERE character_id = 'CH015846';
UPDATE characters SET description = 'ウルトは『ポケットモンスター ホライズンズ』の主要な脇役であり、「メガボルテージ」編で初登場した。 彼はロイのライバルであり、「ライジング・ボルトタッカーズ」のメンバーである。ルミオーズシティで生まれ育ったウルートは、幼少期のある時期に父親から、中身が何であるか一度も明かされなかった謎の「ダスクボール」を受け取った。' WHERE character_id = 'CH015848';
UPDATE characters SET description = '「ブレイブ・アサギ」の技術システムを担当する熟練のプログラマーであり、「ライジング・ボルテッカーズ」のメンバー。ネット上では「グルミン」として知られ、ポケモン世界の様々なテーマについて動画を配信する人気ストリーマーである。  ドットは人付き合いを好まず、ほとんどの時間を部屋にこもって動画制作に費やしているため、他のライジング・ボルテッカーズのメンバーにはめったに姿を見せない。一方、グルミンとしては、元気いっぱいで、大げさな指導法を用い、トレーナー向けの初心者ガイドを配信している。' WHERE character_id = 'CH015849';
UPDATE characters SET description = 'アメティオは、謎の組織「エクスプローラーズ」の幹部であり、コニアやジルと共にリコのペンダントを取り戻すために派遣された。ライジング・ボルテッカーたちがリコを守る姿を見たアメティオは、いかなる手段を用いてもリコのペンダントに隠された秘密を暴くことを決意した。 彼は多くの場面で感情をあまり表に出さない、礼儀正しい人物だ。しかし、その礼儀正しさは、他人を操って自分の望むものを手に入れるための仮面である。彼は「スーブレード」を操って戦う。' WHERE character_id = 'CH015854';
UPDATE characters SET description = '謎の組織「エクスプローラーズ」の幹部。' WHERE character_id = 'CH015856';
UPDATE characters SET description = 'カブはモトストークのジムのジムリーダーだ。彼は炎タイプのポケモンを専門としている。彼に勝利したトレーナーには、「炎のバッジ」を授与する。' WHERE character_id = 'CH015857';
UPDATE characters SET description = 'チリは『ポケットモンスター スカーレット』および『ポケットモンスター バイオレット』に登場するキャラクターです。彼女はパルデア地方の四天王の一人で、地面タイプのポケモンを専門としています。' WHERE character_id = 'CH015858';
UPDATE characters SET description = 'パルデアン地方のチャンピオン。' WHERE character_id = 'CH015859';
UPDATE characters SET description = 'カスカラファジムのジムリーダー。水タイプのポケモンを専門としている。' WHERE character_id = 'CH015860';
UPDATE characters SET description = '歴史家ヘザーの子孫であり、エリア・ゼロにまつわる真実の歴史について自身の発見を綴った本を執筆中だ。ブライアーは気さくで陽気な性格で、出会う人々に親しみやすく親切に接する。 ブライアーは好奇心旺盛で、テラパゴスとの遭遇など、先祖の研究に関連する事柄にすぐに興奮し、エリア・ゼロの歴史などについてもっと知りたいと願っている。（出典：Bulbapedia）' WHERE character_id = 'CH015861';
UPDATE characters SET description = 'マティエールは、ハンサムのアシスタントになった孤児の少女だ。' WHERE character_id = 'CH015862';
UPDATE characters SET description = 'コニアは、謎の組織「エクスプローラーズ」のエージェントであり、リコのペンダントを取り戻すために派遣された。' WHERE character_id = 'CH015863';
UPDATE characters SET description = 'スーブラデスは二足歩行の人型ポケモンだ。体は主に黒色で、頭や腕、脚には青色の模様がある。頭の両側からは鋭い淡い青色の「耳」が突き出ており、頭上には騎士の兜の羽飾りのような炎が燃え上がっている。 目はピンク色の虹彩を持ち、白い瞳孔からは煙のようなものが立ち上っている。スーブレードの体のほぼ全体は、恨みに満ちた古びた濃い紫がかった青色の鎧で覆われている。中央に3つのピンクのくぼみがあるプレートがスーブレードを覆っている。' WHERE character_id = 'CH015864';
UPDATE characters SET description = 'リコの母親。' WHERE character_id = 'CH015865';
