UPDATE characters SET description = 'パルデア地方のポケモンリーグに所属する実業家。メダリジム（正式名称：メダリジム）のジムリーダーを務めるとともに、パルデアのエリートフォーのメンバーでもある。ジムリーダーとしてはノーマルタイプのポケモン、エリートフォーのメンバーとしてはフライングタイプのポケモンを専門としている。' WHERE character_id = 'CH015875';
UPDATE characters SET description = '彼はナランハ・アカデミー／ウヴァ・アカデミーの生物教師を務めるほか、一般課程の担任も担当している。また、「世界ポケモン生態学会」と共に、生態学的に類似したポケモンに関する研究で知られている。' WHERE character_id = 'CH015876';
UPDATE characters SET description = 'セイルは、最初は故郷以外の人に対して警戒心を抱きがちだが、次第に打ち解けていく。気性が激しく、競争心も強い性格で、負けることを嫌い、勝つために常に他の人を様々な勝負に誘おうとしている。（出典：Bulbapedia）' WHERE character_id = 'CH015878';
UPDATE characters SET description = '機械愛好家であり、「ライジング・ボルテッカーズ」のメンバー。オリオは人当たりが良く、非常に勤勉で真面目な人物であり、「ブレイブ・アサギ」に生じた可能性のある損傷を観察し、報告する役割を担っている。仕事に関しては熟練しているが、仕事以外では少々不器用な面があるようだ。' WHERE character_id = 'CH015880';
UPDATE characters SET description = '『ポケットモンスター スカーレット・バイオレット』に登場するキャラクター。プレイヤーキャラクターの友人であり、彼・彼女と互角のライバル関係を築きたいと願っている。ネモナは学園の生徒会長を務めている。' WHERE character_id = 'CH015881';
UPDATE characters SET description = 'パルデア地方の「エリート4」の一員であり、ナランハ・アカデミー／ウヴァ・アカデミーの美術教師。ドラゴンタイプのポケモンを専門としている。' WHERE character_id = 'CH015883';
UPDATE characters SET description = '彼女はナランジャ・アカデミー／ウヴァ・アカデミーでバトル研究の講師を務めている。格闘タイプのポケモンを専門としている。' WHERE character_id = 'CH015884';
UPDATE characters SET description = 'ヒーリングのスペシャリストであり、「ライジング・ボルテッカーズ」のメンバー。モリーは比較的感情を表に出さない人物で、めったに露骨な感情を見せない。しかし、病気や怪我をしたポケモンの世話をし、治療を行うなど、思いやりのある一面も持っている。' WHERE character_id = 'CH015888';
UPDATE characters SET description = 'アンはインディゴ・アカデミーの生徒で、リコの寮のルームメイトです。彼女のパートナーポケモンはミジュマルです。' WHERE character_id = 'CH015889';
UPDATE characters SET description = 'ナンジャモはパルデア地方、具体的にはハッコウ市のジムリーダーの一人で、電気タイプを専門としている。 ジムの代表として活動していない時（時には活動中でも）、彼女はパートナーポケモンのハラバリと共に、自身の番組『ドンナ・モンジャTV』で、大衆に人気のアイドルストリーマーとして活躍している。   (出典: PocketMonsters.Net)' WHERE character_id = 'CH015890';
UPDATE characters SET description = '漁師であり、「ライジング・ボルテッカーズ」のメンバーの一人。ランダウは、他のメンバーとはほとんど交流せず、その代わりに釣りに出かけることを好むため、一人でいることを好んでいるようだ。' WHERE character_id = 'CH015896';
UPDATE characters SET description = '謎の組織「エクスプローラーズ」の幹部。' WHERE character_id = 'CH015898';
UPDATE characters SET description = 'パルデア地方のコルトンドジムのジムリーダー。虫タイプのポケモンを専門としている。パティスリー・ソープベリーというベーカリーを経営している。彼女は、お菓子も虫タイプのポケモンも、その小さな体からは想像できないほどの大きな力を持っていると信じている。かつてはコフのもとで製菓の技術を学んだ。' WHERE character_id = 'CH015900';
UPDATE characters SET description = 'カヌチャンは、小柄でピンク色のヒト型ポケモンで、体全体に比べて頭と腕が比較的大きく、つま先のないずんぐりした足を持っています。両腕にはそれぞれ3本の指があり、胴体にはピラミッド型の菱形をした鋼鉄のプレートのようなものが付いています。 頬には淡いピンクの丸い模様があり、目は銀色で、口の下唇には四角い歯のような突起がある。目の上には細い眉毛かまつげがあり、それが常に心配そうな表情を浮かべているように見える。頭頂部には' WHERE character_id = 'CH015902';
UPDATE characters SET description = 'サイアーノは、ブルーベリー・アカデミーの創設者兼ディレクターです。' WHERE character_id = 'CH015903';
UPDATE characters SET description = '腕利きのシェフであり、「ライジング・ボルテッカーズ」のメンバー。マードックは思いやりのある人物だ。自分のポケモンに愛情を注ぎ、褒めてあげることを好み、チームメイトのことも気遣っている。' WHERE character_id = 'CH015904';
UPDATE characters SET description = '謎の組織「エクスプローラーズ」の幹部。' WHERE character_id = 'CH015905';
UPDATE characters SET description = 'テペンは第28話に登場した「その日のキャラクター」です。彼はダイアナの知人です。  はるか昔、ダイアナがまだ若かった頃、テペンは彼女と同じ冒険者であり、古代遺跡の探検家として、かつては彼女の友人だった。しかし、時が経つにつれ、テペンは探検に次第に幻滅し、危険への恐怖に打ち勝てなくなり、ついには欺瞞的な骨董商となってしまった。' WHERE character_id = 'CH015906';
UPDATE characters SET description = 'グラセアドジムのジムリーダー。氷タイプのポケモンを専門としている。' WHERE character_id = 'CH015907';
UPDATE characters SET description = 'パウミは、小型の四足歩行でげっ歯類に似たポケモンです。体はほぼ全体がオレンジ色で、前脚の下部、鼻先、しっぽはクリーム色、耳の内側は緑色をしています。茶色の小さな目と、ちっぽけな鼻を持っています。 前足はかなり大きく、頭頂部には毛の房があります。パウミは後ろ足で立つことができますが、かろうじてという程度です。また、頬には黄色い未発達な電気嚢があり、前足には電気を放出できる黄色いパッド状の器官があります。' WHERE character_id = 'CH015908';
UPDATE characters SET description = 'ミブリムは、丸いピンクの体と小さな足を一対持つ小さなポケモンです。体の大部分は青いウィッグのようなもので覆われており、ピンク色の帽子のような直立した尾を持っています。この尾には白い斑点があり、先端には青い球状の突起があります。 頭の側面にあるひだは、手足のように機能するようです。ミブリムはメスしか存在せず、オスの個体は存在しません。ミブリムの頭にある尾のような突起は、常に他の生き物の感情を感知し、捉えています。そのため、ミブリムは人目を避ける性質を持っています。' WHERE character_id = 'CH015909';
UPDATE characters SET description = 'タロウはブルーベリー・アカデミーの2年生で、ユニバ地方のジムリーダーであるヤコンの娘であり、BBリーグのエリートフォーのメンバーでもある。彼女はフェアリータイプのポケモンを使いこなす。' WHERE character_id = 'CH015910';
UPDATE characters SET description = 'リコの父親。' WHERE character_id = 'CH015912';
UPDATE characters SET description = '謎の組織「エクスプローラーズ」の幹部。' WHERE character_id = 'CH015913';
UPDATE characters SET description = 'ルシウスは、「古代の冒険者」と呼ばれた、過去に実在したポケモントレーナーです。 彼は、ブラックレイクウザ、オリヴァ、ガラルファイア、ラプラス、バサギリ、エンテイ――これらを総称して「六英雄ポケモン」と呼ばれる――と共に世界を旅したことが記録されています。相棒のテラパゴスと共に、彼らは「ラクア」と呼ばれる楽園にたどり着きました。' WHERE character_id = 'CH015914';
UPDATE characters SET description = 'アルフォルナダジムのジムリーダー。エスパータイプのポケモンを専門としている。' WHERE character_id = 'CH015916';
UPDATE characters SET description = 'シンノ地方出身の腕利きの写真家。サザレは全体的に前向きで陽気、冒険心にあふれた性格で、初めて会う人に対しても気さくで親しみやすい。 サザレはスポーツマンシップと名誉を重んじる人物であり、ドットにポケモンバトルで敗れた後も、ルシウスのバサギリに関する情報を提供するという約束を守った。プロの写真家として、彼女は常にポケモンの写真を撮ることに熱心で、何かが彼女の目を引き、好奇心をそそると、必ずその写真を撮影しようと決意する。' WHERE character_id = 'CH015917';
UPDATE characters SET description = 'カキツバタはブルーベリー・アカデミーの2年生で、BBリーグの「エリート4」の一員である。彼はドラゴンタイプのポケモンを使いこなす。' WHERE character_id = 'CH015919';
UPDATE characters SET description = 'ヒマワリ・ランナは、木刀を振るう「すけばん」として悪名高い少女で、その圧倒的な力と残忍さから、しばしば「怪物」と称される。彼女は、六道に魅了されて恋に落ちた最初のメインヒロインである。 通常、ランナは六道がそばにいない限り、感情をほとんど表に出さず、冷淡な態度をとっているが、彼の友人たちには寛容である。六道の前では、非常に陽気で笑顔を見せる。彼が危険にさらされた時には、躊躇なく立ち止まって彼を守ろうとするが、一方で……' WHERE character_id = 'CH015920';
UPDATE characters SET description = '六道透介は体が弱く臆病で、不良だらけの学校に通っている。彼と2人の友人は常に恐怖に怯え、日常的にいじめを受けており、その鬱憤を学校のトイレでこっそり晴らしている。 祖父から巻物を受け取った六道は、額に特別な五芒星の印が現れる。六道の先祖たちはこの呪文を使って鬼を祓っていたが、現代では、この呪文によって「不良女子」なら誰でも即座に彼に恋をしてしまうようになってしまう。' WHERE character_id = 'CH015921';
UPDATE characters SET description = 'エリカは、女子だけのギャング「チーム・リュウグ」のリーダーだ。かつて「チーム・リュウグ」は、ライバルギャングと絶えず抗争を繰り返していたストリートギャングだった。ある乱闘の最中にランナが加わり、非公式メンバーとしてチームを支えたことで、チームは街のギャング界の頂点へと上り詰めた。 しかし、大島同盟が彼女のグループを攻撃し始めたことを受け、彼女はメンバーの安全を守るためにグループを解散させることを決めた。ランナに木刀を渡したのは彼女である。現在、彼女のグループは法律を遵守する市民となっているが、かつてのギャングらしい服装は今も続けている。' WHERE character_id = 'CH015922';
UPDATE characters SET description = '「すみれ三つ子」（天野、風野、雨野すみれ）の末っ子であり、唯一の女の子。 ライノは男装をしており、イケメンのような外見と性格を装い、メイクの腕も確かだ。そのメイク技術は極めて精巧で、六道さえも難なく可愛い女の子に変身させることができる。鬼島同盟では、カゼノと共にランク5に位置づけられている。' WHERE character_id = 'CH015923';
UPDATE characters SET description = 'おそらくそのきちんとした服装とビジネスライクな物腰から「マネージャー」というあだ名がついたと思われる彼は、物語の序盤において六道の友人の一人である。「大佐」や六道と同様、彼もまた、安森高校で平穏な生活を送りたいと願っているが、不良の同級生たちから絶えずいじめられている。 「大佐」と同様、彼は六道が「不良女子」たちに人気があることに気づき、六道が不良グループと対立する際には、六道とその仲間たちに付き添うことになる。' WHERE character_id = 'CH015924';
UPDATE characters SET description = '小学生のような外見と物腰のため、青森高校の生徒であるさゆりは、よく小学生と間違えられる。小柄な見た目とは裏腹に、さゆりは学校一の格闘家という評判を築き上げ、同校の番長を務めている。 彼女は当初、青森高校の女子生徒たちからなぜか人気を集める六道を狙っていたが、彼への攻撃を始めた途端、その「呪文」の力に魅了されてしまった。こうして六道は、彼女にとって初めての恋の相手となった。' WHERE character_id = 'CH015925';
UPDATE characters SET description = '警察の仕事とバイクに情熱を注ぐ日名見アザミは、六道に想いを寄せる3人目の主要な女性キャラクターである。一見、甘く女性らしい印象を与えるが、実はバイクに乗ることが大好きだ。彼女はバイカーギャングに恨みを抱いており、バイクにまたがったまま彼らを激しく殴りつける。 彼女は自警団のような振る舞いをし、市民に交通安全を呼びかけ、道路上で悪質な不良と見なした者たちを排除している。[4] 主要な女性キャラクターの中で、アモリ・ハイに通っていないのは彼女だけである。' WHERE character_id = 'CH015926';
UPDATE characters SET description = '鬼島同盟でランク1に位置し、同同盟ではドウジに次ぐ最強のメンバーである。彼女は強い男に興味を持っているが、その感情をサディズム的な行為を通じて表現し、相手の精神を打ち砕くことに快感を覚える。 六道の力の影響下で、彼女は彼を「とてつもなく強い男」と見なし、戦いが続くにつれてその印象はますます強まっていく。六道は、窓から転落しそうになった彼女を救った後、彼女を「打ち負かす」。その際、六道の力が彼の姿を極端に誇張したため、彼女は至福のあまり気を失ってしまう。その後、' WHERE character_id = 'CH015927';
UPDATE characters SET description = '鬼島同盟のリーダー。礼儀正しいが、時に非常に威圧的な一面も見せる。六道と同様、かつては臆病で他人を極度に恐れており、自分を守るために強い者たちに賄賂を贈って頼っていた。やがて、強い者たちに囲まれるために鬼島同盟に加わった。 ランナがたった一人で同盟をあっさりと打ち負かした後、彼は彼女の強さに魅了され、強者たちを集めて同盟の戦力を再強化し、彼女を同盟に迎え入れたいと願うようになった。' WHERE character_id = 'CH015928';
UPDATE characters SET description = 'おそらく、軍用のベレー帽と迷彩柄の服装にちなんで「大佐」というあだ名がついたと思われる彼は、シリーズ序盤から六道と親しい友人の一人である。彼は、不良のいじめっ子たちから解放され、平穏な学校生活を送りたいという六道の夢を共有している。 六道や友人の「マネージャー」と共に、授業時間中にトイレの個室に身を寄せ合い、阿森高校での生活に対する不満をぶちまけている。彼は、六道が巻物から得た能力が「彼をポ' WHERE character_id = 'CH015929';
UPDATE characters SET description = 'アオイはオンジマ同盟の一員であり、そのバイク部隊を率いていた。普段は温厚で人当たりの良い性格だが、バイクのハンドルを握ると暴力的になり、並外れた競争心を見せることもある。 あるバイクの警察官によって徐々に更生しつつあったが、その警察官が事故で重傷を負ってしまった。彼はヒメノの親しい仲間であり、彼女やロクドウとレースを繰り広げたが、敗れた。彼は gang を離れ、アザミに gang の指揮を任せた。彼女とは今も親しい関係を保っているが、しばしば競争心が' WHERE character_id = 'CH015930';
UPDATE characters SET description = '飯沼は六道とその仲間たちをいじめる主犯格であり、彼らを犠牲にして残酷ないたずらを繰り返していた。六道が能力を目覚めさせ、うっかり恋人の椿に影響を与えてしまった後、飯沼は六道に決闘を挑んだ。 圧倒的な力の差があったにもかかわらず、六道は逃げ出すことを拒み、激しい殴打に耐えた末、ランナに戦いに介入するよう頼んだ。その粘り強さに感銘を受けた飯沼は六道と親しくなり、彼の最も親しい仲間の一人となった。やがて二人は、互いの' WHERE character_id = 'CH015931';
UPDATE characters SET description = 'もともと六道をいじめていた一人だった椿は、飯沼の彼女である。六道の力の影響を受けた後、彼女は六道に対する自分の振る舞いを悔い、トイレで彼に謝罪する。 彼に気を配る彼女の態度に、当初は飯沼は憤りを覚えたが、二人が友人になってからは、椿は定期的に六道とその仲間たちと過ごすようになった。彼女はもはや六道の力には反応しなくなった。' WHERE character_id = 'CH015933';
UPDATE characters SET description = 'カオルの猫。' WHERE character_id = 'CH015941';
UPDATE characters SET description = '竜之介の犬。' WHERE character_id = 'CH015957';
UPDATE characters SET description = 'イヴは『BIRDIE WING: ゴルフ・ガールズ・ストーリー』シリーズの主人公です。彼女はゴルフの賭けで生計を立てていたサバイバーです。苦難に満ちた過去が、荒削りでありながらも力強いプレースタイルを生み出しました。' WHERE character_id = 'CH015960';
UPDATE characters SET description = '天羽葵は、世界有数の大企業である天羽グループの令嬢であり、ゴルフ界の逸材である。 名門・雷神女子学園ゴルフ部のエースである葵は、ゴルフを楽しみながら、甘く無邪気な笑顔を浮かべて対戦相手を打ち負かすことから、「無邪気な暴君」として知られるようになった。' WHERE character_id = 'CH015961';
UPDATE characters SET description = 'アムロ・レイヤは、雷神女子学園のゴルフ部のヘッドコーチである。かつてプロゴルファーとして活躍していたが、そのキャリアは短命に終わった。現在はゴルフ部を率いるとともに、プロとしての道を歩み始めた葵のメンターも務めている。また、イヴをチームに迎え入れ、ある程度の指導も行っている。' WHERE character_id = 'CH015964';
UPDATE characters SET description = 'レオ・ミラフォデンはアンダーグラウンドのゴルファーであり、イヴの幼少期の大部分において彼女のゴルフコーチを務めていた。イヴはレオを通じて、「バレット」と呼ばれる高エネルギーのゴルフスイングのやり方を学ぶことができた。やがて、レオはイヴを独り立ちさせた。' WHERE character_id = 'CH015967';
