UPDATE characters SET description = 'パワーレベル：78　帝国の四天王の一人。短気なところがあるが、根は心優しい。 グループの中で一番真面目な彼女だが、普段はヘルクやピウィの悪ふざけに巻き込まれてしまうことが多い。火属性魔法と召喚魔法を使いこなし、複数の敵を同時に相手にする戦闘に長けている。' WHERE character_id = 'CH016682';
UPDATE characters SET description = 'パワーレベル：99　本作の主人公である人間のヒーロー、ヘルク。ヒーローのクレスの実の兄である。並外れた強さと信頼性、そして実力を兼ね備えたヘルクは、悪魔のチャンピオンとなり、人間を滅ぼすことを目指している。' WHERE character_id = 'CH016683';
UPDATE characters SET description = 'ピウィは、丸くて真っ緑でふわふわした、鳥のような生き物だ。ピウィは騒がしく、とても無知だ。それでも、その性格は「かわいい」と評されている。彼はとても気楽で、時には周囲で起きている暴力にさえ気づかないこともある。' WHERE character_id = 'CH016684';
UPDATE characters SET description = 'アリシアはヘルクの親しい友人である。彼女は、ヘルクがエディルの家へ向かう旅の途中で出会った傭兵だ。彼女は代々続く傭兵の一族の出身である。彼女の先祖の一人は、現在の人類帝国が建国される前に、悪魔と戦った英雄だったと伝えられている。  （出典：helck.fandom.com）' WHERE character_id = 'CH016685';
UPDATE characters SET description = 'レベル43のスパイ' WHERE character_id = 'CH016688';
UPDATE characters SET description = 'アイリスの兄。' WHERE character_id = 'CH016691';
UPDATE characters SET description = 'エディルは常に人々や仲間を最優先に考えています。困難な状況にあっても、友人たちの前ではとても陽気な姿を見せています。彼は当初、悪魔に対して不信感を抱いており、プロパガンダの影響で、人間帝国の苦難の原因を悪魔のせいにしています。ヘルクのたくましい体格と優しい笑顔から、彼はしばしばヘルクに自分の兄たちの姿を重ねて見ているようです。 特定のタイプの女性を好むわけではないが、彼が率直に話すことを気にせず、かつ力強い女性を好む。' WHERE character_id = 'CH016692';
UPDATE characters SET description = 'ミカロスは傲慢で利己的な人物であり、現在の世界秩序を破壊しようとしている。成功のためなら手段を選ばない。彼は優れた戦略家であり、人を巧みに操る手腕を持ち、自らの計画を見事に実行に移す。彼は死を恐れ、自分にはどう頑張っても敵わないほど強い存在がいるという考えに、恐怖と苛立ちを覚える。' WHERE character_id = 'CH016693';
UPDATE characters SET description = 'クレスは人間界の英雄であり、ヘルクの弟である。（出典：helck.fandom.com）' WHERE character_id = 'CH016696';
UPDATE characters SET description = '人間界の現君主。' WHERE character_id = 'CH016698';
UPDATE characters SET description = 'アズドラは、魔界の四天王の一人である。' WHERE character_id = 'CH016700';
UPDATE characters SET description = 'アスタは好奇心旺盛なので、さまざまなことに興味を持ちます。周囲の状況には非常に慎重で、成功を確実にするために、本来持っている能力だけで済むことでも道具を使うなど、常に念入りに備えています。何かが危険になり得ると判断すれば、すぐに結論を出してしまう傾向があります。' WHERE character_id = 'CH016704';
UPDATE characters SET description = 'ヒュラは、現在、トオル城の第1旅団長を務めている。彼女は、トオルの後継となる次期魔王を決める選抜戦で、最終4名に残った一人だった。（出典：helck.fandom.com）' WHERE character_id = 'CH016705';
UPDATE characters SET description = 'イスタは姉のことをとても気遣い、姉の安否を深く案じています。姉を心から愛しています。イスタは血を見るのが苦手で、特に幼い頃はそうでした。彼女はとても不器用で、泣き虫で、臆病者で、心配性な女の子です。 しかし、こうした性格にもかかわらず、彼女は努力家で、その意志の強さはヒュラさえも凌ぐほどだ。彼女は何よりも姉を愛している。  彼女の夢は、深く尊敬している「赤の天王」ヴァミリオに仕えることだ。' WHERE character_id = 'CH016706';
UPDATE characters SET description = 'ロココはとても陽気な性格だ。戦争以外のことは、すべて完璧にこなすのが好きだ。彼女は人間との共存を望む平和主義者である。アズドラを深く敬愛しており、アズドラのためなら喜んで命を捧げるだろう。' WHERE character_id = 'CH016707';
UPDATE characters SET description = 'ケンロスは気さくで気取らない人物だ。彼は徹底した平和主義者である。自分のペースで物事を進めることを好み、自ら「帝国一の速さ」と称することを誇りにしている。ヘルクを親しみを込めて慕っている。彼は非常にカリスマ性があり、相手が誰であろうと誰に対しても親しみやすい。' WHERE character_id = 'CH016710';
UPDATE characters SET description = 'ドーシェは、トオルに代わる次期魔王の候補者の一人だった。' WHERE character_id = 'CH016713';
UPDATE characters SET description = 'オーギスの妹。' WHERE character_id = 'CH016714';
UPDATE characters SET description = '非常に有能なツンデレ猫。子猫の頃、路上で凍え死にかけたところをサクに拾われ、彼女のペットになった。 当初はごく普通の猫だったが、サクの生活スキルがあまりにも乏しかったため、彼が何とかしなければならず、その結果、非常に有能な猫へと成長した。サクを「役立たず」と呼ぶものの、彼の言動のすべてには、飼い主への感謝と愛情が溢れている。' WHERE character_id = 'CH016718';
UPDATE characters SET description = 'ユキチの飼い主は、28歳のOLだ。ユキチによれば、彼女は働きすぎて、仕事以外では自分の身の回りのことさえまともにできない「ダメ人間」だという。彼女はいつも自分のケアを後回しにし、倒れるまで自分を追い込んでしまう。 ユキチを引き取るまでは、ゴミだらけの家（！）の玄関先で寝落ちすることが常だった。ほんの少しの幸運とビールさえあれば、彼女は幸せに暮らせる。' WHERE character_id = 'CH016719';
UPDATE characters SET description = '娘のことを大切に思っている一方で、口が悪く、よくサクを「バカな娘」と呼ぶ。サクのことを心配して、頻繁に電話をかけている。' WHERE character_id = 'CH016723';
UPDATE characters SET description = '彼女はほとんど目が見えず、車椅子が必要だ。かつては黒猫を飼っていた。' WHERE character_id = 'CH016725';
UPDATE characters SET description = 'サクの同僚の一人で、ユリとも親しい友人だ。彼女はよく独身者の交流会に参加しているが、なかなか良い結果にはつながらない。他の同僚たちはよく、彼女にサクを紹介してほしいと頼んでくる。' WHERE character_id = 'CH016727';
UPDATE characters SET description = '魔王の秘書。' WHERE character_id = 'CH016749';
UPDATE characters SET description = 'かつてスリだったヒューゴは、今では真っ当な道を歩み、サーカスでザインやカフと一緒に働いている。' WHERE character_id = 'CH016767';
UPDATE characters SET description = '「普通」であることこそが唯一の特徴である、ごく普通の少女。リザは、正義感が強く、奔放でおてんばな性格の持ち主だ。自分の信念については頑固な面もあるが、心根は優しい。ある非凡な出会いをきっかけに、彼女の世界は一変してしまう……' WHERE character_id = 'CH016771';
UPDATE characters SET description = 'クラウディアは、裕福な行商人の娘です。彼女は上品な雰囲気と優しい人柄の持ち主です。音楽に興味があり、フルートの練習をしていますが、それを父親には隠しています。 クルケン島を訪れた際、彼女はリザ、レント、タオと親しくなり、秘密の隠れ家のメンバーの一人となる。彼らは夏の間、共に数々の冒険を繰り広げる。' WHERE character_id = 'CH016772';
UPDATE characters SET description = '冥界で滅びたオーレン族の一員として、彼女は、滅亡したクリント王国が残した未解決の問題を解消し、エンペル・ヴォルマーと共に、フィルスクハの侵略から故郷の仇を討つことを目標に奮闘している。' WHERE character_id = 'CH016773';
UPDATE characters SET description = 'レントはリザとタオの幼なじみで、3人は共に故郷を離れ、本土へと旅立ち、世界を探検することを目指している。 さらに、冒険者を目指す彼は、誰も足を踏み入れたことのない禁断の地や未知の場所を旅する名高い人物となり、その実力を認められ、現在酒に溺れ、暴力を振るう父親の影を覆い隠したいと願っている。' WHERE character_id = 'CH016774';
UPDATE characters SET description = 'タオはリザやレントと幼なじみで、3人は故郷を離れ、本土へと旅立ち、世界を探検することを目指している。ただし、実際に旅に出ることに関しては、3人の中でタオが最も躊躇している。彼の家族は古代語が記された古書を所有しており、旅の途中でその言語を解読し、学びたいと考えている。' WHERE character_id = 'CH016775';
UPDATE characters SET description = 'エンペルは、リラ・デサイラスと共にクリント王国の遺跡を調査している放浪の錬金術師だ。怪我のため高度な技法は使えないが、才能のあるリザに錬金術の世界を教えている。どうやら甘いものが大好きで、あらゆる種類のスイーツを好んでおり、よく数十個もまとめて買うらしい。' WHERE character_id = 'CH016776';
UPDATE characters SET description = '年齢：18～22歳　性別：男性　ボスはリザ、タオ、レントの幼なじみだったが、ある事件をきっかけに彼らに対して敵対的な態度をとるようになった。それでも、最終的には彼らと和解し、過去の過ちを償おうと懸命に努力する姿が描かれている。' WHERE character_id = 'CH016786';
UPDATE characters SET description = '長崎ソヨの母親（名前は不明）。ソヨの父親（登場しない）と離婚して以来、シングルマザーとして働きながら子育てをしており、仕事に追われることが多く、ソヨには家事を任せて料理もさせている。そのため、彼女は娘に強く依存するようになっており、それがソヨの情緒不安定の一因となっている。' WHERE character_id = 'CH016809';
UPDATE characters SET description = 'ライブハウス「SPACE」の従業員。' WHERE character_id = 'CH016810';
UPDATE characters SET description = 'いつも不運に見舞われる1年生。そのため、自分は「堕天使」だと思っているが、そのことをむしろ誇りに思っている。本名の「ヨシコ」ではなく、「ヨハネ」と呼ばれることを頑なに望んでいる。' WHERE character_id = 'CH016818';
UPDATE characters SET description = 'イタリア系アメリカ人の父親がイタリア風ホテルのチェーンを経営している、日系ハーフの3年生の女子生徒。明るく朗らかな性格で、自分のペースで物事に取り組んでいる。' WHERE character_id = 'CH016819';
UPDATE characters SET description = 'ハナマルが飼っているイノシシのような獣。' WHERE character_id = 'CH016820';
UPDATE characters SET description = 'ディアは3年生で、生徒会の会長を務めており、黒沢ルビーの姉である。  ディアは、非常に上品で礼儀正しく、大人びた若い女性であり、丁寧な日本語を使い、友人全員を「～さん」と呼んで礼儀正しく接し、文末にはたいてい「～ですわ」と付け加える。 非常に勤勉で、少し完璧主義なところがあり、物事が雑にやられたり、間違って行われたりすることを嫌う。また、些細な細部に対しても非常に几帳面である。' WHERE character_id = 'CH016821';
UPDATE characters SET description = '津島良子の母親' WHERE character_id = 'CH016822';
UPDATE characters SET description = '3人姉妹の末っ子で、μ''sのファンであり、学校のアイドルユニットのリーダーを務めている。家族は旅館を経営しており、海が見渡せる露天風呂が自慢だ。高校2年生。' WHERE character_id = 'CH016824';
UPDATE characters SET description = '彼女は高見千佳の姉であり、3姉妹の中で一番年上です。' WHERE character_id = 'CH016825';
UPDATE characters SET description = 'リコは、内向的で礼儀正しく、謙虚な女の子で、室内での活動が好きであり、より活発な友人であるチカやヨウとは対照的な存在だ。しかし、普段は落ち着いていて大人びているものの、プレッシャーがかかるとしばしばパニックに陥り、早合点してミスを犯してしまう。 このこと、そして以前、観客の前でピアノの演奏に失敗してしまった出来事のため、彼女は自分には特別な才能はないと考えており、スクールアイドルになることを望んでいない。しかし、友人のチカに無理やり巻き込まれ、' WHERE character_id = 'CH016827';
UPDATE characters SET description = '渡辺ツキは渡辺ユーのいとこであり、沼津高校の2年生で、生徒会会長代理を務めている。 イタリアで育ったツキは、イタリア語を驚くほど流暢に話す。頼りになる友人であり、制服好きという面でも、スクールアイドルである従姉妹と多くの共通点を持っている。全校生徒の中で、転校生が新しい学校に馴染めるよう手を差し伸べたのは、彼女だけだった。（出典：ラブライブ！Wiki）' WHERE character_id = 'CH016828';
UPDATE characters SET description = 'ヨハネと一緒に暮らしている大きな狼の獣。性格は穏やかで、ヨハネにとって良き相棒である。' WHERE character_id = 'CH016829';
UPDATE characters SET description = '松浦カナンさんは、近くの島でダイビングショップを営む祖父と二人きりで暮らす高校3年生だ。気さくで大人びており、細かいことにこだわることはめったになく、普段は穏やかでクールな態度を保っている。' WHERE character_id = 'CH016830';
UPDATE characters SET description = '彼女は娘のチカに非常によく似ており、タカミ家の中で一番背が低いため、一番年下のように見える。' WHERE character_id = 'CH016831';
UPDATE characters SET description = '学年：2年生　2年生で、代表チームに選ばれるほどの実力を持つハイダイバー。ビジネススーツが好き。将来は自分のフェリーの船長になることを夢見ている。「ユー」はチカの幼なじみで、チカの夢を応援するためにスクールアイドルになった。' WHERE character_id = 'CH016832';
UPDATE characters SET description = 'チカの姉であり、タカミ姉妹の次女。' WHERE character_id = 'CH016833';
UPDATE characters SET description = '花丸は、気が散りやすい小学1年生で、彼女の家族は地元の寺を営んでいるが、そこにはパソコンやハンドドライヤーといった現代的な設備がほとんどない。そのため、彼女はそうした設備を目にするたびに夢中になり、周囲を驚かせている。 彼女は自分を「オラ」か「マル」と呼び、静岡弁の影響で多くの文の最後に「～ずら」と付け加える。また、歌の才能があるため、地元の合唱団にも所属している。Aqoursに加入する前は、学校の' WHERE character_id = 'CH016834';
UPDATE characters SET description = '泣き虫で、男性恐怖症の1年生。ディアの妹。裁縫だけが唯一の得意分野だ。' WHERE character_id = 'CH016836';
UPDATE characters SET description = 'タカミ家の飼い犬。' WHERE character_id = 'CH016837';
UPDATE characters SET description = '第3話の脇役' WHERE character_id = 'CH016842';
UPDATE characters SET description = '第6話の脇役' WHERE character_id = 'CH016851';
UPDATE characters SET description = '春原春子は、マベースの最新住民であり、銀河宇宙警察ブラザーフッドに所属する宇宙人捜査官である。春子は、淡いピンクがかった髪をした、元気で直感的な少女だ。彼女は19歳だと主張しているが、それが本当かどうかは定かではない。 第1話では、彼女はベスパで直太を轢き、ギターで彼の頭を殴ってしまう。その直後、彼女はナンダバ家のメイドとなりながら、銀河で最も強力な宇宙海賊であるアトムスクの行方を追うことになる。' WHERE character_id = 'CH016852';
UPDATE characters SET description = 'アマラオ司令官は、星間移民局に勤務している。この機関は、とりわけ政府とメディカル・メカニカとの交渉における仲介役を務めている。 そのため、通信を妨害して攻撃を誘発しようと執念を燃やすハルコ／ラハルは、彼らにとって大きな問題となっている。アマラオは海苔で作った偽の眉毛をつけており、それが男らしく見えることと、N.O.から身を守るという二つの目的を果たしていると信じている。アマラオはハルコと過去に何らかの関係があったようだ。' WHERE character_id = 'CH016856';
UPDATE characters SET description = 'ジンキの兄。天才的な頭脳を持つエンジニアであり、CIAのサイバー対策部門の外部講師を務めていた。AI「グイ」の開発者だったが、完成直前に交通事故で亡くなった。' WHERE character_id = 'CH016857';
UPDATE characters SET description = '英雄パーティーが訪れた町で、二人の村人の娘を食べてしまった若い悪魔の少女。ヒメルが彼女を殺そうとした際、彼女は「お母さん」と呼びかけ、村長は彼女を自分の家族として迎え入れ、贖罪の機会を与えようとしている。' WHERE character_id = 'CH016871';
UPDATE characters SET description = '第一級魔術師試験の第4組に所属する二級魔術師。幻術を専門としている。' WHERE character_id = 'CH016872';
UPDATE characters SET description = 'セインの幼なじみで、冒険に出かけ、伝説の英雄になることを夢見ていた。昔、彼はセインに「一緒に冒険に出よう」と誘ったが、セインはそれを断り、それ以来ずっと後悔し続けている。' WHERE character_id = 'CH016873';
UPDATE characters SET description = 'フリーレンの古くからの友人である、年老いたドワーフの戦士。クラール地方の村に住んでいる。' WHERE character_id = 'CH016874';
UPDATE characters SET description = '一級魔導士試験の第2試験の監督を務めている一級魔導士。口数が少なく、物静かな人物である。' WHERE character_id = 'CH016875';
UPDATE characters SET description = '一級魔術師の資格試験の受験者。人を信用せず、自信に満ちた魔術師。' WHERE character_id = 'CH016876';
UPDATE characters SET description = '彼は、フリーレンの一行が山中の小屋で出会ったエルフである。僧侶であり、フリーレンと出会うまでは、生き残っている最後のエルフだと考えられていた。' WHERE character_id = 'CH016877';
UPDATE characters SET description = '三級の魔術師。高速移動を可能にする魔法を専門としている。デンケンを祖父のように慕っている。' WHERE character_id = 'CH016878';
UPDATE characters SET description = '一級魔術師の資格試験の受験者。' WHERE character_id = 'CH016879';
UPDATE characters SET description = 'オーラは、魔王に直属する「七人の破壊の賢者」の一人である。' WHERE character_id = 'CH016880';
UPDATE characters SET description = 'スタークの兄。村で最強の戦士と言われている。' WHERE character_id = 'CH016881';
UPDATE characters SET description = '一流の魔術師。魔法試験の監視役を務める。' WHERE character_id = 'CH016882';
UPDATE characters SET description = 'ヴォリグ要塞都市を統治する貴族であり、北方諸国三大騎士家の一つであるオルデン家の現当主。' WHERE character_id = 'CH016883';
UPDATE characters SET description = '第一級魔術師試験の受験者。' WHERE character_id = 'CH016884';
UPDATE characters SET description = 'リュグナーは、ギロチンのオーラに仕えていた悪魔だった。' WHERE character_id = 'CH016885';
UPDATE characters SET description = '「剣の村」の現首長。その地位は世襲によるものである。この役職としては若く、背の低さを補おうと姿勢に気を使っているが、危険に直面したり、「英雄の剣」に関する事柄に直面したりした際には、冷静沈着な態度を見せる。' WHERE character_id = 'CH016886';
UPDATE characters SET description = '一級魔術師の資格試験の受験者。少しぼんやりした女の子。本を読んだり、新しい呪文を覚えたりするのが好き。' WHERE character_id = 'CH016887';
UPDATE characters SET description = 'オーデン卿の従者。' WHERE character_id = 'CH016888';
UPDATE characters SET description = 'リーニエは、アウラに仕える悪魔である。アウラの指示により、ドラートと共にリュグナーを補佐し、グラファ・グラナートとの交渉にあたるよう派遣された。' WHERE character_id = 'CH016889';
UPDATE characters SET description = 'セインは、アルトの森にある小さな村出身の司祭だ。フリーレンにその才能を見出されて以来、幼なじみのゴリラと再会することを目標に、しばらくの間彼女のパーティーに加わっていた。' WHERE character_id = 'CH016890';
UPDATE characters SET description = 'フリーレンやファーンと同じ時期に「一級魔導士試験」を受験した二級魔導士。アウスターストで魔法道具店を営んでおり、壊れた杖の修理を専門としている。' WHERE character_id = 'CH016891';
UPDATE characters SET description = '彼女はこの物語の1000年も前に生きており、フリーレンの師だった。' WHERE character_id = 'CH016892';
UPDATE characters SET description = 'ドラートは、ギロチンのオーラに仕えていた悪魔だった。' WHERE character_id = 'CH016893';
UPDATE characters SET description = 'ユーベルは三級魔術師である。かつて、一級魔術師を殺害したため、試験で失格となった。共感できる相手の呪文を模倣できる魔法を専門としている。主に直感に頼っており、論理的な推論には縛られない。' WHERE character_id = 'CH016894';
UPDATE characters SET description = '魔王に仕えた、恐れられ、強大な力を持つ悪魔。' WHERE character_id = 'CH016895';
UPDATE characters SET description = 'オーラと絶えず戦いを繰り広げている北方諸国にある要塞都市、グラフ・グラナートの領地の統治者。' WHERE character_id = 'CH016896';
UPDATE characters SET description = 'カンネは、魔法アカデミーを卒業した三級魔術師である。彼女はラウィネの幼なじみであり同級生でもあり、二人は共に一級魔術師試験に臨んだ。試験の第1段階では、彼女はラウィネとフリーレンと同じ組になった。' WHERE character_id = 'CH016897';
UPDATE characters SET description = 'ラウィネは、第1級魔術師試験の第2組に所属する3級魔術師である。彼女は氷を操る術を専門としている。' WHERE character_id = 'CH016898';
UPDATE characters SET description = '中位の側室であり、遥か彼方の国の王女。彼女は本意に反して、皇帝の中位の側室となった。' WHERE character_id = 'CH016901';
UPDATE characters SET description = 'フェンシェンはかつて、ヴェルディグリス・ホールの高位の遊女だった。冷徹で強靭な性格の持ち主であり、戦略ボードゲームでは右に出る者はいなかった。彼女は、そのゲームで自分に匹敵する相手である男性に恋をしたが、関係を持った後、彼に見捨てられてしまった。' WHERE character_id = 'CH016902';
UPDATE characters SET description = 'ベルリント市役所の事業開発チームに所属する職員。' WHERE character_id = 'CH016903';
UPDATE characters SET description = 'ベルリント市役所の事業開発チームに所属する職員。' WHERE character_id = 'CH016904';
UPDATE characters SET description = 'ウェスタリスで出版された、オスタニアを中傷する数冊の著書や記事を執筆した著者。その目的は、自身と高齢の父親のために金銭を得ることだった。過去には、前政権下で新聞記者を務めていたが、反政府過激派を支援したとして逮捕された。' WHERE character_id = 'CH016905';
UPDATE characters SET description = '「ガーデン」のメンバーであり、ベルリント市役所の政策担当局長。' WHERE character_id = 'CH016908';
UPDATE characters SET description = 'レオナルド・ハプーンがオルカ・グレッチャーとその息子を殺害するために雇った暗殺者の一人。' WHERE character_id = 'CH016909';
UPDATE characters SET description = 'オルカ・グレッチャーを狙う暗殺者の一人。彼は他の暗殺者たちとの協力を拒み、懸賞金を分け合うことも拒否して、単独でオルカを襲おうとした。' WHERE character_id = 'CH016912';
UPDATE characters SET description = 'オルカ・グレッチャーの友人であり、グレッチャー家の忠実な支持者。彼は「ファーシール・グレイ」という偽名を使い、オルカ（当時は「シャティ・グレイ」という名で活動していた）の夫を装っていた。' WHERE character_id = 'CH016913';
UPDATE characters SET description = 'レオナルド・ハプーンがオルカ・グレッチャーを殺害するために雇った暗殺者の一人。彼は他の雇われた暗殺者たちの調整役を務め、彼らに命令を伝達するとともに、スヌープスの主な連絡役も担っていた。' WHERE character_id = 'CH016914';
UPDATE characters SET description = 'オルカ・グレッチャーの唯一の息子であり、グレッチャー家の現存する2人のメンバーのうちの1人である。' WHERE character_id = 'CH016915';
UPDATE characters SET description = '種族：エルフ　アルファはシャドウ・ガーデンの副司令官である。シド・カゲノウによって悪魔憑きから解放された後、彼女は彼の大義に生涯を捧げることを決意し、彼の組織「シャドウ・ガーデン」に最初に迎え入れられたメンバーとなった。' WHERE character_id = 'CH016916';
UPDATE characters SET description = '種族：人間　「シャドウ」という通称で知られるシド・カゲノウは、秘密組織「シャドウ・ガーデン」の創設者であり、リーダーである。彼は「影の権力者」になるという自身の幻想を実現するために、この組織を設立した。 しかし、彼自身は気づいていないが、彼の作り話は現実ではしばしば真実であることが明らかになる。シドは、カゲノウ・ミノルの転生である。  （出典：『影の権威』ウィキ）' WHERE character_id = 'CH016917';
UPDATE characters SET description = '種族：エルフ　ベータは「シャドウ・ガーデン」の2人目のメンバーであり、主であるシャドウを補佐し、ディアボロス教団と戦っている。' WHERE character_id = 'CH016918';
UPDATE characters SET description = '種族：ビーストキン　デルタは「シャドウ・ガーデン」の一員であり、師であるシャドウによって「悪魔憑き」が治癒された後、初代「シャドウ・セブン」のメンバーとして4人目として組織に加わった。セブンの中で最も身体能力に恵まれている一方で、分別や自制心に欠けるため、グループの中で最も破壊的で残忍な行動をとることが多い。  （出典：To Be a Power in the Shadows! Wiki）' WHERE character_id = 'CH016919';
UPDATE characters SET description = 'シャドウ・ガーデンのメンバーであり、「ナンバーズ」（No. 24）の一人。エプシロンに配下として仕えている。オメガは普段は冷静沈着だが、つまらない冗談でも笑ってしまう自分の傾向に悩んでいる。' WHERE character_id = 'CH016920';
UPDATE characters SET description = '種族：人間　アレクシア・ミッドガルは、ミッドガル王国の第二王女であり、アイリス・ミッドガルの妹である。また、ミッドガル王立呪剣学院の生徒でもある。  （出典：『影の力となるために！』Wiki）' WHERE character_id = 'CH016921';
UPDATE characters SET description = '「魔法剣士協会」のエリートスタッフの一人で、同協会の特別任務部隊のリーダーとなる人物。' WHERE character_id = 'CH016922';
UPDATE characters SET description = '種族：人間　クレアはシド・カゲノウの姉であり、カゲノウ家の後継者である。（出典：『To Be a Power in the Shadows!』Wiki）' WHERE character_id = 'CH016923';
UPDATE characters SET description = '種族：エルフ　665はシャドウ・ガーデンの「ナンバーズ」の一員であり、664や666と同じ分隊に所属している。穏やかな性格で、サポート役をこなすのが得意だ。' WHERE character_id = 'CH016924';
UPDATE characters SET description = '「武神祭」に何度も参加してきた、猛々しい剣士。' WHERE character_id = 'CH016925';
UPDATE characters SET description = 'ユキメの最も親しい側近の一人で、ナツとは姉妹関係にある。' WHERE character_id = 'CH016926';
UPDATE characters SET description = 'ガーターに雇われた「メジャー・コーポレート・アライアンス」の社員であり、最も活躍した傭兵「クローバーズ」を指揮していた上司である。' WHERE character_id = 'CH016927';
UPDATE characters SET description = '深紅の騎士団の騎士' WHERE character_id = 'CH016928';
UPDATE characters SET description = 'ディアブロス教団の「名付けられた子供たち」の一人。' WHERE character_id = 'CH016929';
UPDATE characters SET description = '種族：エルフ　エタは「シャドウ・ガーデン」の7人目のメンバーであり、創設時の「セブン・シャドウズ」の一人である。彼女は「シャドウ・ガーデン」の研究部門を専門とし、その責任者を務めており、そのため専用の研究所を構えている。彼女は「天才建築家」エタ・ロイド・ライトとして知られており、その作品は「年間最優秀建築賞」で満場一致の1位を獲得した。' WHERE character_id = 'CH016930';
UPDATE characters SET description = '種族：人間　ローザ・オリアナは、オリアナ王国の貴族の王女である。彼女は王国内で芸術の天才として知られている。しかし、剣術を学ぶためにミッドガル王立魔法剣士学院へやって来た。' WHERE character_id = 'CH016931';
UPDATE characters SET description = '種族：人間　アイリス・ミッドガルは、ミッドガル王国の第一王女であり、アレクシア・ミッドガルの姉である。また、クリムゾン・オーダーのリーダーでもある。  （出典：『The Eminence in Shadow』ウィキ）' WHERE character_id = 'CH016932';
UPDATE characters SET description = 'ガーター・コーポレーションの社長であり、ゲッタンの最も信頼する側近である。' WHERE character_id = 'CH016933';
UPDATE characters SET description = '種族：獣人（狐）　彼女は「精霊狐」として知られる獣人であり、ホワイトタワーの支配者である。 スピリットフォックス一族の中でも、彼女は並外れた才能と戦闘能力を持ち、鉄製の扇子を武器として、戦場でも優雅に舞い踊る。無法都市の歓楽街を統括する一方で、スノーフォックス・コーポレーションという商社を経営する、手腕の優れた実業家でもある。' WHERE character_id = 'CH016935';
UPDATE characters SET description = '種族：エルフ　エプシロンはシャドウ・ガーデンの5人目のメンバーである。 胸が平らであることにコンプレックスを抱いていたため、彼女は毎年スライムのボディスーツを操作して胸のボリュームを少しずつ増やし、最終的には偽物の巨乳を作り上げた。その結果、彼女は極めて高い魔法制御能力を身につけ、「ザ・プレシジョン」という称号を得た。' WHERE character_id = 'CH016936';
UPDATE characters SET description = 'シャドウ・ガーデンの一員であり、コードネーム「ナンバー559」として「ザ・ナンバーズ」の一人を務めている。その能力は「セブン・シャドウズ」に匹敵すると言われている。彼女は、「セブン・シャドウズ」を除けば、シャドウ本人から直接力を授かったたった2人のうちの1人である。 ヴィクトリアは、任務を遂行できる限り、自らの行動がもたらす結果や巻き添え被害などには一切関心を示さない。' WHERE character_id = 'CH016937';
UPDATE characters SET description = 'シド・カゲノウが、背景のキャラクターとして溶け込むのを助けるために選んだ「友人」の一人' WHERE character_id = 'CH016938';
UPDATE characters SET description = 'デルタの兄であり、ガーター・コーポレーション傘下の小規模な精鋭組織「クローバーズ」のメンバー。' WHERE character_id = 'CH016939';
UPDATE characters SET description = '種族：人間　「ジャガーノート・タイラント」は、ローレス・シティの3人の君主の一人である。彼は主に本能と肉体を頼りに敵を打ちのめす。技を使うと動きが鈍ってしまうためだ    （出典：『To Be a Power in the Shadows!』Wiki）' WHERE character_id = 'CH016941';
UPDATE characters SET description = '種族：ビーストキン　ゼータは「シャドウ・ガーデン」の6人目のメンバーであり、初代「セブン・シャドウズ」の一人である。普段は一人で世界中を旅し、情報を収集している。' WHERE character_id = 'CH016942';
UPDATE characters SET description = '種族：人間　ヌーはシャドウ・ガーデンの13人目のメンバーであり、ミツゴシ社の社員である。  （出典：『To Be a Power in the Shadows!』Wiki）' WHERE character_id = 'CH016943';
UPDATE characters SET description = 'シャドウ・ガーデンのメンバーであり、「ナンバーズ」（No.22）の一人。エプシロンに配下として仕えている。真面目で厳格な物腰だが、意外にも恥ずかしがり屋で、よく顔を赤らめる。' WHERE character_id = 'CH016944';
UPDATE characters SET description = 'オリアナ王家に仕えるメイドであり、かつてはローズの専属世話役を務めていた。以前はローズを慕っていたが、ミッドガル王国での事件をきっかけに、その気持ちはすぐに不信感へと変わった。シドのピアニストとしての腕前に感服しており、パトロン探しを手伝いたいと執拗に申し出ている。' WHERE character_id = 'CH016945';
UPDATE characters SET description = '種族：ヴァンパイア　エリザベスは「無法の都」の三人の君主の一人であり、ヴァンパイアの女王である。（出典：『To Be a Power in the Shadows!』Wiki）' WHERE character_id = 'CH016946';
UPDATE characters SET description = '種族：エルフ　ガンマは「シャドウ・ガーデン」の一員であり、初代「セブン・シャドウズ」の3人目のメンバーであると同時に、ミツゴシ社の社長も務めている。不器用な面はあるものの、ガンマはその豊富な知識を活かし、師であるシャドウが語った数々のアイテムを再現し、ミツゴシ社の限定商品として販売している。  （出典：To Be a Power in the Shadows! Wiki）' WHERE character_id = 'CH016947';
UPDATE characters SET description = '「神々の戦い」トーナメントに参加した剣士。' WHERE character_id = 'CH016948';
UPDATE characters SET description = '無法の街にあるクリムゾン・タワーの見張り役。彼の任務は、誰もタワーに入らないようにすることである。' WHERE character_id = 'CH016949';
UPDATE characters SET description = 'オリアナ王国の王宮の衛兵。ケビンはマーガレットに片思いをしているが、その想いは報われていると確信している。彼はマーガレットに対して執着心を抱いており、二人が親しげに話しているのを見かけた際には、シドに詰め寄り、脅しをかけた。' WHERE character_id = 'CH016950';
UPDATE characters SET description = '種族：ヴァンパイア　メアリーはヴァンパイアハンターであり、ヴァンパイアの女王エリザベスを倒すことに全力を注いでいる。（出典：『To Be a Power in the Shadows!』Wiki）' WHERE character_id = 'CH016951';
UPDATE characters SET description = 'シャドウ・ガーデンのメンバーであり、「ザ・ナンバーズ」の一人（No. 11）。新入メンバーの訓練を担当している。' WHERE character_id = 'CH016952';
UPDATE characters SET description = '種族：人間　かつて世界に混沌と破壊をもたらした、「災厄の魔女」として知られる女性。 聖地で行われた「女神の試練」において、シドの出現を感知して召喚され、影の姿となって彼と戦いを繰り広げる。その肉体は聖域に封印されており、シドの脱出を手助けした後、聖域の崩壊と共に姿を消した。' WHERE character_id = 'CH016953';
UPDATE characters SET description = 'ローレス・シティにある酒場のオーナーであり、そこでバーテンダーとしても働いている。彼女はもともと、13歳の時に売春を強要される形でこの街に連れてこられた。' WHERE character_id = 'CH016954';
UPDATE characters SET description = 'オリアナ王国の女王であり、ローズの母親。' WHERE character_id = 'CH016955';
UPDATE characters SET description = '種族：ヴァンパイア' WHERE character_id = 'CH016956';
UPDATE characters SET description = '664はシャドウ・ガーデンの「ナンバーズ」の一員であり、665と666が所属する小隊の隊長を務めている。真面目な性格だが、心根は優しい。' WHERE character_id = 'CH016957';
UPDATE characters SET description = 'シド・カゲノが、背景のキャラクターに紛れ込むために利用している「友人」の一人' WHERE character_id = 'CH016958';
UPDATE characters SET description = 'ユキメの最も親しい側近の一人。カナの姉。' WHERE character_id = 'CH016959';
UPDATE characters SET description = '種族：人間　西野茜は、西野コングロマリットのCEOの娘であり、シドの前世である影野実の同級生だった。' WHERE character_id = 'CH016960';
UPDATE characters SET description = 'アンディは円卓の9番目のメンバーである。彼は「アンデッド」という別名を持つネゲーターだ。本来の人格はヴィクターである。アンディは、出雲風子と並んで物語の第二の主人公である。アンディは常軌を逸したほど無鉄砲で、死ぬことを楽しみ、常に新しい死に方を模索している。 また、彼は風子に特別な思い入れを持っており、彼女を強く守ろうとする。彼女が傷つけられると激怒し、そのあまりに、自ら頭の中のカードを取り外してヴィクターを解き放つことさえ厭わないほどだ。  アンディは背が高く筋肉質な男で、' WHERE character_id = 'CH016963';
UPDATE characters SET description = 'リップ・トリスタンは「アンダー」のメンバーです。' WHERE character_id = 'CH016964';
UPDATE characters SET description = '円卓の「ネゲーター」第4号。物静かで、のんびりとした性格の持ち主である。' WHERE character_id = 'CH016965';
UPDATE characters SET description = '「ムーブ」は、動きそのものを体現したUMAである。ユニオンに捕獲・調教され、ジュイズの指揮下にあった。' WHERE character_id = 'CH016966';
UPDATE characters SET description = '「スポイル」は、腐敗や朽ち果てを象徴するUMAです。' WHERE character_id = 'CH016967';
UPDATE characters SET description = 'ニコ・ヴォルゲイルの助手の一人で、ミコに次ぐ第3位の科学者。ミコに多少の関心を抱いているが、彼女が第2位であることに対する嫉妬の方が、より強い感情となっている。' WHERE character_id = 'CH016968';
UPDATE characters SET description = 'ユサイは、かつてアンディの修行を指導した日本の侍である。その後、彼女は「アンダー」の一員となる。' WHERE character_id = 'CH016969';
UPDATE characters SET description = 'ヴォイドはネゲーターであり、ユニオンの一員だった。彼はシェンと共に、アンディを捕らえ、フウコを殺害するという任務に就いていた。' WHERE character_id = 'CH016970';
UPDATE characters SET description = '「服」を体現するUMA。このUMAは、接触したあらゆる衣服の姿に変身することができる。気性が荒く、すぐに怒り出し、非常に自己中心的なUMAだ。「服」はアンディによって飼い慣らされたが、それでもなお、すぐにイライラしてしまうという本来の性質は変わっていない。' WHERE character_id = 'CH016971';
UPDATE characters SET description = '「オータム」は、秋という季節を体現したコンセプトタイプのUMAです。' WHERE character_id = 'CH016972';
UPDATE characters SET description = 'ユニオンのリーダー。ジュイスは「円卓」の創設者であり、その筆頭メンバーである。彼女は「アポカリプス」の向こう側にいる存在を倒すことを決意し、それを打ち倒すのに十分な力を得るために数人のネゲーターを集め、こうして「ユニオン」を結成した。' WHERE character_id = 'CH016973';
UPDATE characters SET description = '性別：   円卓会議の第6番目のメンバー。' WHERE character_id = 'CH016974';
UPDATE characters SET description = 'バーンは、「燃焼」を象徴する現象タイプのUMAである。' WHERE character_id = 'CH016975';
UPDATE characters SET description = '円卓会議の第2号メンバー。' WHERE character_id = 'CH016976';
UPDATE characters SET description = 'クリードは、顔に十字形の傷跡がある、大柄で筋肉質の男だ。' WHERE character_id = 'CH016978';
UPDATE characters SET description = '円卓の騎士団の第5番目の騎士。騎士団に加わる前はロシアに住んでいた。彼女が身に着けている鎧は、その能力を抑えるための拘束具としての役割を果たしている。' WHERE character_id = 'CH016980';
UPDATE characters SET description = '『黙示録』（『啓示の書』とも呼ばれる）は、この世界で最初に発見されたアーティファクトである。  『黙示録』は中くらいの大きさの本の形をしている。ユニオンの円卓の周りに規定数のネゲーターが集まると、その背表紙と表紙に、鋭い牙と長い舌を持つ怪物の顔が浮かび上がる。' WHERE character_id = 'CH016981';
UPDATE characters SET description = 'チカラはネゲーターだ。彼は日本語しか話せないため、世界中の言語が統一された後、マフィアに発見されてしまった。' WHERE character_id = 'CH016982';
UPDATE characters SET description = 'ラウンドテーブルのメンバー第3番。彼はクールで気ままな性格で、危険にさらされても気にしていないようだし、そもそも自分が危険な状況にあることさえ気づいていないようだ。銃に詳しいことが示されており、自他共に認める甘党である。' WHERE character_id = 'CH016984';
UPDATE characters SET description = 'ラトラはネゲーターであり、リップの幼なじみである。' WHERE character_id = 'CH016985';
UPDATE characters SET description = 'フェンは、遺物を収集することを目的とする「アンダー」の一員である。彼は中国武術の衣装を身にまとい、フードを被って顔を隠している。' WHERE character_id = 'CH016986';
UPDATE characters SET description = 'フウコのお気に入りの漫画『To You, From Me』の、人目を避けて暮らす作者。' WHERE character_id = 'CH016987';
UPDATE characters SET description = '円卓会議のメンバー第8番。彼は「ザ・ユニオン」の中で最も聡明なメンバーである。ニコは眠一子と結婚しており、彼女との間に娘のミコ・ヴォルゲイルがいる。' WHERE character_id = 'CH016989';
UPDATE characters SET description = 'ムイは中国系の小柄な少女だ。髪は濃い紫色で、後ろには白い髪結いカバーを付けている。 シェンの部下であるため、彼女も彼と同じ服装をしている。その服装は、白い襟付きのノースリーブシャツに赤いネクタイを合わせたものだ。また、腰のラインが透けて見える黒いルーズなパンツと、腕まで覆う黒い手袋を身につけている。' WHERE character_id = 'CH016990';
UPDATE characters SET description = 'ショーン・ダッツは「アンダー」のメンバーである。彼は「ネゲーター」だ。' WHERE character_id = 'CH016992';
UPDATE characters SET description = 'バックス（通称バニー）は「アンダー」のメンバーで、常に大きなウサギのコスチュームを着ている幼い子供のようだ。' WHERE character_id = 'CH016993';
UPDATE characters SET description = 'ジーナは、50年以上前にアンディと出会ったネゲーターである。' WHERE character_id = 'CH016994';
UPDATE characters SET description = '円卓会議の第7番目のメンバー。' WHERE character_id = 'CH016995';
UPDATE characters SET description = 'ユニオンに所属する科学者で、ニコ・ヴォルゲイルの助手の一人として働いている。また、ニコの娘でもあり、彼に次ぐ実力を持つ科学者である。' WHERE character_id = 'CH016997';
UPDATE characters SET description = 'チカラの同級生であり友人。' WHERE character_id = 'CH016998';
UPDATE characters SET description = '中学卒業まで、レンタロウの友人だった。' WHERE character_id = 'CH017000';
UPDATE characters SET description = '静香のお母さん' WHERE character_id = 'CH017002';
UPDATE characters SET description = 'このシリーズの主人公は、ゴブリン狩りにのみ専念する、経験豊富なシルバーランクの冒険者である。彼が引き受ける仕事はゴブリンに関わるものだけであり、それ以外には一切興味を示さない。 彼の外見は、そのランクの冒険者としては物足りなく見える装備を身に着けているため、華やかさや優雅さには欠けている。彼は、汚れた灰色の革製鎧を身にまとい、その下には鎖帷子を着用し、左前腕には縁が研ぎ澄まされた小さなバックラーを装着している。彼の武器は、奇妙な形状の剣である。' WHERE character_id = 'CH017004';
UPDATE characters SET description = '種族：人間　ランク：オブシディアン（過去）、ポーセリン（過去）、スチール（現在のランク）　本作のヒロイン。冒険者としてのランクはポーセリンで、入団したばかりのため最下位ランクである。 性格は若く、親切で、誰に対しても積極的に手助けをするタイプだ。回復魔法や防御魔法を高い熟練度で使いこなすことができる。初めてのゴブリン狩りが瞬く間に大失敗に終わり、ゴブリンスレイヤーに救われたことをきっかけに、彼と共に新たなパーティーを結成する。その後も……' WHERE character_id = 'CH017005';
UPDATE characters SET description = 'ハイエルフの冒険者。彼女はドワーフのシャーマンとリザードのプリーストと共に、ゴブリンスレイヤーを探し出し、協力を仰ぐためにやって来た。彼らは当初、「ゴブリンスレイヤー」という名前を正しく発音できず、彼を見つけるまで別の呼び名で呼んでいたため、少々手間取っていた。 一行は目的を明かす。他の悪魔系モンスターの増加により、ゴブリンに対処する人員が不足している上、エルフ軍がゴブリン討伐に動けば、軍がゴブリン討伐のみに注力していることが疑念やパニックを招く恐れがあるため、動員できないというのだ。' WHERE character_id = 'CH017006';
UPDATE characters SET description = 'スピアマンは、辺境を拠点とするシルバーランクの冒険者だ。彼はウィッチのパートナーである。シルバーランクは取得可能なランクの中で3番目に高いランクであり、彼は仲間の冒険者たち、特に新人たちから尊敬を集め、憧れの的となっている。  茶色のトゲトゲした髪に、瞳の色に合わせた薄赤色のイヤリングを身につけている。鮮やかな青色の鎧を身にまとい、代名詞とも言える武器である槍を携えている。自身の能力に絶大な自信を持っており、人々に印象を残そうと熱心である。' WHERE character_id = 'CH017007';
UPDATE characters SET description = '大正は、10年前に魔王を倒したことで名高い、ゴールドランクの冒険者6人のリーダーである。' WHERE character_id = 'CH017008';
UPDATE characters SET description = 'かつてはゴールドランクの冒険者であり、現在は「法の神殿」の至高神の大司教を務めている。' WHERE character_id = 'CH017009';
UPDATE characters SET description = '年齢：20歳以上　種族：レア　職業：冒険者　ランク：ブロンズ　所属：冒険者ギルド - ヘビー・ウォリアーズ・パーティ　ドルイドの少女は気立てが優しく、誰に対しても親しみやすい。機会があれば、新人冒険者たちにアドバイスをしようと努めている。' WHERE character_id = 'CH017010';
UPDATE characters SET description = 'ノーブル・フェンサーは、家族から独立するために冒険の道を選んだ。彼女は誇り高く、短期間のうちにゴールドランク、さらにはプラチナランクにまで上り詰めることを期待しており、ゴブリンを見下していた。 しかし、ゴブリンたちとのトラウマとなるような苦難の末、彼女は打ちのめされ、ゴブリンのパラディンを殺し、盗まれた家宝の剣を取り戻すことだけに執着する陰鬱な女性となってしまった。ゴブリンスレイヤーのパーティの助けを借りてそれらの目標を達成した後、彼女は怒りを乗り越え、前へ進むことができた。現在は「フェマル」として知られている。' WHERE character_id = 'CH017011';
UPDATE characters SET description = 'ハイエルフのアーチャーやドワーフのシャーマンとパーティーを組むリザードマンの冒険者。後にゴブリンスレイヤーやプリーステスとも協力関係になる。ランクはシルバーで、3番目に高いランクである。冷静沈着で、人に対しては礼儀正しく、敬意を込めて接する。 パーティの中で最も物腰が柔らかく、気性が穏やかで、社交的なメンバーのようだ。リザード・プリーストは緑色の肌をしていて、頭には角が生えている。その威圧的な風貌と堂々とした体格は、友人たちでさえも不安にさせるほどだ。' WHERE character_id = 'CH017012';
UPDATE characters SET description = '種族：人間　職業：冒険者　ランク：シルバー　所属：冒険者ギルド　シルバーランクの冒険者。現在は、新人冒険者に基礎的な戦闘技術を教える指導員を務めている。' WHERE character_id = 'CH017013';
UPDATE characters SET description = '王の妹。' WHERE character_id = 'CH017014';
UPDATE characters SET description = 'ドワーフで、リザードプリーストやハイエルフのアーチャーらとパーティーを組んでいる。ゴブリンに占拠された遺跡に潜入するため、ゴブリンスレイヤーやプリーステスと協力することになる。シルバー冒険者として、経験豊富な呪文使いである。 小柄ながらもがっしりとした体格のドワーフのシャーマンは、真っ白な長い髪をポニーテールに結い、よく撫でる髭は精巧に編み込まれている。耳たぶは伸ばされており、ピアスが通されている。彼の司祭' WHERE character_id = 'CH017015';
UPDATE characters SET description = '「ポーセリン」ランクの冒険者で、新人戦士と2人パーティーを組んでいる' WHERE character_id = 'CH017016';
UPDATE characters SET description = '目につくものは何でも破壊し、奪い去るモンスターたち。彼らは皆、「言葉を持つ者」を憎む傾向がある。' WHERE character_id = 'CH017017';
UPDATE characters SET description = 'この国の現統治者。妹を大切にする。' WHERE character_id = 'CH017018';
UPDATE characters SET description = '彼女は辺境にある冒険者ギルドで受付を務める、至高神の司祭である。ギルドガールの同僚でもある。' WHERE character_id = 'CH017019';
UPDATE characters SET description = '彼女は10年前に魔王を倒したことで名高い、ゴールドランクの冒険者6人のうちの1人であり、タイショウの従兄弟にあたる。' WHERE character_id = 'CH017020';
UPDATE characters SET description = 'カウガールはゴブリンスレイヤーの幼なじみで、叔父の農場で農作業を手伝っている。' WHERE character_id = 'CH017022';
UPDATE characters SET description = '種族：人間　職業：冒険者　称号：パラディン＋　所属：冒険者ギルド　彼女は長い金髪の若い女性で、体にぴったりとフィットした白い鎧とマントを身にまとっているが、アニメ版では鎧は灰色で、所々に金色の装飾が施されている。' WHERE character_id = 'CH017023';
UPDATE characters SET description = '彼女は、10年前に魔王を倒したことで名高い、ゴールドランクの冒険者6人のうちの1人である。' WHERE character_id = 'CH017024';
UPDATE characters SET description = 'ギルドの受付として事務を担当し、冒険者たちに契約書を渡している若い女性。ゴブリンからの襲撃に苦しむ村々からの助けを求める声に心を痛めており、そのような仕事を引き受ける経験豊富な冒険者がほとんどいないことに頭を抱えている。 この問題のせいで、経験の浅い新人がゴブリンに殺されたり、それ以上の悲惨な目に遭ったりすることになりかねない。彼女は、他の者が手を出そうとしない多くのゴブリン討伐依頼を引き受けてくれるゴブリンスレイヤーを、深く尊敬している。' WHERE character_id = 'CH017025';
UPDATE characters SET description = '彼は、10年前に魔王を倒したことで名高い、ゴールドランクの冒険者6人のうちの1人である。' WHERE character_id = 'CH017026';
UPDATE characters SET description = 'ウィッチは、スピアマンと同じパーティを組んでいるシルバーランクの冒険者だ。彼女は、紫色の長い髪を持ち、金色の縁取りが施された濃い色の露出度の高いローブを身にまとった美しい魔法使いである。 彼女は通常、かなり魅惑的な姿で描かれ、愛嬌たっぷりの振る舞いをし、一見普通の会話の中でもしばしば性的なニュアンスをほのめかすため、相手は動揺したり恥ずかしがったりしてしまう。そんなからかいぶりとは裏腹に、彼女は周囲の人々を気遣う一面も持ち合わせており、' WHERE character_id = 'CH017027';
UPDATE characters SET description = '彼は「ポーセリン」ランクの冒険者で、見習いクレリックと2人パーティーを組んでいる。' WHERE character_id = 'CH017028';
UPDATE characters SET description = '彼は、10年前に魔王を倒したことで名高い、ゴールドランクの冒険者6人のうちの1人である。' WHERE character_id = 'CH017029';
UPDATE characters SET description = 'クリムゾンは、かつてドラゴンたちを裏切り、ドラゴン神を殺そうとした元「翼の君主」である。クリムゾンはラグナと手を組み、自身を含むすべてのドラゴンを滅ぼそうとした。' WHERE character_id = 'CH017030';
UPDATE characters SET description = 'クリムゾンと手を組み、すべてのドラゴンを倒そうとしたドラゴンハンター。' WHERE character_id = 'CH017031';
UPDATE characters SET description = '「翼の血筋」の第7位。未来のタイムラインにおける第4位。' WHERE character_id = 'CH017033';
UPDATE characters SET description = '「翼の血統」の第三位。' WHERE character_id = 'CH017041';
UPDATE characters SET description = 'カーラは「太陽教」に属するドラゴンスレイヤーのモンクだった。彼女の極めて有用な時間魔法のため、彼女が死亡すると、急速に増殖できるクローンの軍団が彼女の代わりとなった。ただし、一部の例外を除き、それらのクローンの力は本物のほんの一部に過ぎない。' WHERE character_id = 'CH017044';
UPDATE characters SET description = 'レオニカは若き天才ドラゴンハンターだ。彼女はラグナを手助けし、ラグナは彼女と一緒に旅をするようになった。' WHERE character_id = 'CH017045';
UPDATE characters SET description = '「翼の血筋」の第八席。彼の名前は、日本語でも英語でも「fat gourmet」を逆から読んだものになっている。' WHERE character_id = 'CH017050';
UPDATE characters SET description = '「爪を持つ君主」。' WHERE character_id = 'CH017054';
UPDATE characters SET description = '翼の血統の第10席。' WHERE character_id = 'CH017055';
UPDATE characters SET description = '「翼の血筋」の第二位。' WHERE character_id = 'CH017060';
UPDATE characters SET description = 'フェイトは黒髪に茶色の瞳を持つ青年だ。しかし、「大食」のスキルが発動すると、瞳の色は赤くなる。父親が亡くなった後、村人たちは彼を村から追い出した。村人たちは、父親が亡くなった後、彼を役立たずだと思っているのだ。そこでフェイトは、生計を立てるために仕事を探し始めた。' WHERE character_id = 'CH017068';
UPDATE characters SET description = '彼は「運命の剣」だ。' WHERE character_id = 'CH017073';
UPDATE characters SET description = '学校で最も美しい女子の一人とされる白川は、気さくで誰とでも親しくなるため、さらに人気を集めている。人気が高い分、彼女については「せいぜい2、3ヶ月しか付き合わない」「ちょっとしたきっかけで簡単に彼氏を次から次へと変える」といった悪質な噂が流されがちだ。 しかし、それらの噂はすべて事実無根だ。ギャルっぽい外見とは裏腹に、白川は交際相手に対して誠実に尽くしており（そのあまりに「ヘビー」や「うざい」と呼ばれるほどだ）。彼女は……' WHERE character_id = 'CH017093';
UPDATE characters SET description = '鹿島は1年生の頃から白川を憧れの存在として見ていたが、2年生になって彼女と同じクラスになるという幸運に恵まれ、単なる憧れが片思いへと変わった。鹿島はそれ以上の関係を望むことはなく、現状のままでも満足していた。' WHERE character_id = 'CH017094';
UPDATE characters SET description = 'アドニスは、クロエという名の魔女に育てられた人間である。' WHERE character_id = 'CH017101';
UPDATE characters SET description = 'リディア帝国の捕虜収容所に囚われていた少女。心優しく、気高い精神の持ち主である。' WHERE character_id = 'CH017102';
UPDATE characters SET description = 'マジックサークルランク：ティア3（分析魔法）　デジール・ハーマンは、『転生者の魔法は特別であるべき』の主人公である。シャドウワールドの攻略に失敗し、過去へと戻った彼は、未来が繰り返されないよう、仲間たちを強化することを決意する。 ヘブリオン学園では、平民は嫌われ、ベータクラスに配属される一方、貴族はアルファクラスに指定されている。デジールは、この階級制度を憎み、現状を変えたいと願う平民の一人である。その結果、' WHERE character_id = 'CH017122';
UPDATE characters SET description = 'サークルティアレベル：3（風の魔術師）　デシール・アーマンが「影の迷宮」から戻った後、初めてロマンティカと出会った際、彼女は貴族という立場ゆえに優越感を抱いていたが、物語が進むにつれてデシール・アーマンと親しくなるにつれ、その優越感は徐々に薄れていく。' WHERE character_id = 'CH017123';
UPDATE characters SET description = 'サークル・ティア・レベル：3（ソードメイジ）　プラムは、デシール・アーマンが率いる庶民で構成されたアルファパーティの一員である。' WHERE character_id = 'CH017124';
UPDATE characters SET description = 'サークルレベル：4（ソードメイジ）  アゼスト・ジェドガー・F・ローグパレスは、ヘブリオン帝国の現皇帝であるギルティアン・ジェドガー・F・ローグパレスの長男であり、したがってヘブリオン帝国の皇位継承者である。 当初、アゼストは冷淡な性格で、デシール・グループの親しい友人たち以外の人々にはあまり関心を示さない傾向があった。' WHERE character_id = 'CH017126';
UPDATE characters SET description = 'アルファクラスおよびブルームーン党のメンバー。庶民を軽蔑し、見下している。' WHERE character_id = 'CH017130';
UPDATE characters SET description = 'アルファ・クラスおよびブルームーン・パーティーのメンバー。' WHERE character_id = 'CH017131';
UPDATE characters SET description = 'サークル・ティア・レベル：7（セージ）　「知恵の賢者」ゾッド・エクサリオンは、魔法の塔の主であり、現存する唯一無二の第七サークル魔術師である。彼は世界最高の魔術師として知られ、独力で魔法への関心を再び呼び起こした人物として名高い。 また、彼はブロミエ・ナポリタンと戦った100人のうちの1人であり、その戦いを生き延びた6人のうちの1人でもあった。' WHERE character_id = 'CH017132';
UPDATE characters SET description = 'クレア・フランソワは誇り高き貴族であり、原作『レボリューション』ではヒロインをいじめる悪役として登場します。クレアは高慢で、自身の価値と家名を証明しようとする競争心も持っています。その威圧的な振る舞いの裏には、幼少期の経験に起因する脆い心が隠されています。 大切な人たちが自分から離れていくかもしれないという不安から、嫉妬深くなりがちだ。彼女の傲慢な性格は、何よりも幼少期に父親が彼女を過度に溺愛したことが大きな影響を与えている。' WHERE character_id = 'CH017134';
UPDATE characters SET description = 'ある平凡なOLが、お気に入りの乙女ゲーム『レボリューション』の主人公の体に取り込まれてしまう。彼女は、お気に入りのキャラクターであるクレア・フランソワとカップルになることを目指している。レイは、クレアの愛情を勝ち取ることに夢中な、おバカで楽天的な女の子という姿をわざと演じている。 しかし、実際には、これは彼女が幼い頃に経験した性への探求から生じた、一種の対処法に過ぎない。彼女は実のところ、本音をあまり表に出さず、しばしば……' WHERE character_id = 'CH017135';
UPDATE characters SET description = 'バウアー王国の王族の中で3番目の後継者。カリスマ性があり魅力的な「王子様タイプ」で、その魅力の裏には狡猾な頭脳を隠している。ユウは、ゲーム内で2番目に人気のある「攻略対象」である。' WHERE character_id = 'CH017136';
UPDATE characters SET description = 'ミーシャは、レイの親友であり、アカデミーでのルームメイトでもある。彼女は、かつての栄華を失い、貧困に陥った貴族の家系の出身だ。 ジュール家は経済的に苦しい状況にあるものの、依然として一定の評判を保っている。彼女は自分の立場をありのままに受け入れており、貴族としての地位に固執するのではなく、庶民の仲間として対等な姿勢で振る舞っている。こうした姿勢があったからこそ、レイとミシャは長きにわたる友情を築くことができたのだ。' WHERE character_id = 'CH017137';
UPDATE characters SET description = 'レイに引き取られたベビースライム。' WHERE character_id = 'CH017138';
UPDATE characters SET description = 'マナリア・スースは、スース王国の初代王女である。彼女はクレアの遠縁にあたる。また、あらゆる属性において最高レベルの適性を備えた、世界で初めて確認されたクアッドキャスターでもある。' WHERE character_id = 'CH017139';
UPDATE characters SET description = 'レネは、裕福な商人一家であるオーロソー家の長女である。彼女はクレール・フランソワの専属メイドとして忠実に仕えている。レネは大変忍耐強く、おとなしく従順な印象を与えるが、実際には、長年にわたってクレールに仕えてきた経験から、彼女をうまく扱う術を心得ているだけなのである。' WHERE character_id = 'CH017140';
UPDATE characters SET description = 'ロレッタは、軍務に長けた家系として知られるクグレット家の出身である。' WHERE character_id = 'CH017141';
UPDATE characters SET description = 'ドール・フランソワは、バウアー王国の財務大臣であり、クレール・フランソワの父親である。' WHERE character_id = 'CH017142';
UPDATE characters SET description = 'ピピは、バウアーのビジネス界に深い人脈を持つバルリエ家の娘である。彼女はクレア・フランソワやロレッタ・クグレと幼なじみである。' WHERE character_id = 'CH017143';
UPDATE characters SET description = 'バウアー王国の王族の中で最年長の後継者であり、王位継承順位第1位である。彼はエネルギッシュな若者で、レイに好意を抱くようになるが、レイはそれを快く思っていない。ロッドは、このゲーム内で最も人気のある攻略対象である。' WHERE character_id = 'CH017144';
UPDATE characters SET description = 'バウアー王国の王族の中で2番目の後継者。セインは普段、無表情で、自分の能力が兄弟たちに劣っていると感じており、そのことでコンプレックスを抱いている。セインは、ゲーム内で最も人気のない攻略対象と見なされている。' WHERE character_id = 'CH017145';
UPDATE characters SET description = 'エメ・エメリッヒは、探偵養成アカデミー「BLUE」の校長であり、ロン・カモノハシの両親の旧知の友人である。' WHERE character_id = 'CH017146';
UPDATE characters SET description = 'BLUEの密室講座講師であり、密室研究の世界的権威。  彼女は、Sランクの探偵免許を保持する世界でも数少ない人物の一人である。「フェニックスの手」という能力を駆使し、これまでに5,000の隠し部屋、3,000の違法建築、そして10,000の物理的仕掛けを発見してきた。' WHERE character_id = 'CH017152';
UPDATE characters SET description = '「クリムゾン・ロード」の7人のうちの1人であり、第7部隊の指揮官である。' WHERE character_id = 'CH017178';
UPDATE characters SET description = 'コマリの専属メイド。クリムゾン・ロードとしての地位の一環として配属された。' WHERE character_id = 'CH017179';
UPDATE characters SET description = 'ムルナイト帝国の女帝。気難しく、奔放な性格の持ち主である彼女は、世を避けて暮らすコマリを「クリムゾン・ロード」に任命した。' WHERE character_id = 'CH017180';
UPDATE characters SET description = '「クリムゾン・ロード」の7人のうちの1人であり、第6部隊の指揮官を務めている。' WHERE character_id = 'CH017193';
UPDATE characters SET description = 'テロ組織「インバーテッド・ムーン」の構成員。' WHERE character_id = 'CH017196';
UPDATE characters SET description = '「シックス・カントリーズ」紙の記者。同紙は一部の人々から信頼できないと見なされている。' WHERE character_id = 'CH017199';
UPDATE characters SET description = '彼は「死者の都」出身の孤独な人間であり、前世の漠然とした記憶を宿して生まれ、成人するまでアンデッドの一団に育てられた。その後、グレースフィールに誓いを立て、守護神の信仰を回復させつつ、冒険と文明を求めて都を後にした。  彼は幼少の頃、大王に課せられた封印を解くための生贄として、悪魔たちによって「死者の都」へ連れ去られたが、そこでアンデッドの一団に見出され、引き取られた。' WHERE character_id = 'CH017201';
UPDATE characters SET description = 'メネルドールは、追放されたハーフエルフであり、ウィリアムの最も忠実な友人である。以前は冒険者兼狩人だった。彼は人間とエルフの混血であるハーフエルフだ。髪は銀色でポニーテールに結んでおり、瞳はヒスイのような色をしている。  メネルドールは、エルフが暮らすエリンの大森林にある、北方の草原で生まれた。エルフと人間の血が混ざっているため、彼は追放者となり、住民たちとは誰ともうまくやっていけなかった。その後、彼は家を出て、' WHERE character_id = 'CH017204';
UPDATE characters SET description = '彼女は、ウィリアムを支援するためにバグリー司教から派遣された司祭であり、トーチポートの街で日常業務を統括する主要人物の一人である。' WHERE character_id = 'CH017206';
UPDATE characters SET description = 'スタグネートは、アンデッドと結びついた悪意の女神である。彼女はウィリアムの敵であり、彼に特別な関心を寄せるようになる。敵同士であるにもかかわらず、彼の旅路を見守り、彼を助ける。   彼女はいたずら好きで狡猾だ。人間をこよなく愛し、他者の道しるべとなる英雄たちを永遠の存在にしたいと願っている。また、彼の最期の瞬間に自身の「エコー」がとった行動について、後悔と恥じらいを感じている。' WHERE character_id = 'CH017210';
UPDATE characters SET description = '彼は、ホワイトセイルズの神殿を統括する首席司教である。' WHERE character_id = 'CH017212';
UPDATE characters SET description = 'ヴィンダルファーはドワーフで、ウィリアムの従者であり友人である。後に、彼がアイアン・マウンテンズの生き残った後継者であることが明らかになった。' WHERE character_id = 'CH017213';
UPDATE characters SET description = 'レイストフは、卓越した腕前の冒険者であり、ウィリアムの仲間でもあった。彼は冒険者としての活動を引退し、新婚の妻アンナと共に落ち着いて暮らすことを決めた。' WHERE character_id = 'CH017214';
UPDATE characters SET description = 'グレースフィールは、炎と永遠の流動に関連付けられた神秘的な女神である。彼女はウィリアムの守護神である。彼女は長い黒髪と金色の瞳を持つ人型の女神だ。穏やかな顔立ちをしており、その際立った特徴を覆うフード付きのローブを身にまとっている。右手には、通常は長い柄のついたランタンを握っている。 彼女の現れ形は、温かな炎の姿をとっている。グレースフィールは炎と流動の女神である。彼女はユニオン時代、多くの信者を擁する名高い神であった。' WHERE character_id = 'CH017216';
UPDATE characters SET description = 'アウグストゥスは亡霊である。彼はグレースフィールの使者のような存在となり、ハイキングの封印を守っている。' WHERE character_id = 'CH017217';
UPDATE characters SET description = 'エテバルドはオーウェン王の弟である。' WHERE character_id = 'CH017219';
UPDATE characters SET description = '日暮クオンは、「ソーンズ・オブ・ザ・スティクス」の元リーダーであり、「サバラモンドのバスタード・チルドレン」と「アガクラ」の両組織に所属している。' WHERE character_id = 'CH017221';
UPDATE characters SET description = 'ルルは、シビルとアラハバキの仲間である。生まれつきの能力か、あるいは「邪眼」を理論上は持っているためか、彼女はエレメンタルたちの声を聞くことができる。' WHERE character_id = 'CH017222';
UPDATE characters SET description = 'シビルは、異世界出身の元素魔術師であり、「サバラモンドの私生児たち」において指導的な立場にある。' WHERE character_id = 'CH017225';
UPDATE characters SET description = '彼女は第3材料編集グループのメンバーです。' WHERE character_id = 'CH017226';
UPDATE characters SET description = '「シラヌイの天空塔」ことアリウス・サバラモンド卿は、バイアンディ帝国の元首席宮廷魔術師である。' WHERE character_id = 'CH017228';
UPDATE characters SET description = 'フラムロディア・ビャンディラズはビャンディ帝国の最後の皇帝であり、彼の治世と帝国は、帝国の魔術師の中で第四位の地位にあり、かつ彼の最も親しい友人でもあった「死体の神」による暗殺によって、同時にその幕を閉じた。 彼と数名の宮廷人は、死後もネクロマンシーによって「死体の神」に縛られた魂として、死後もなお「死体の神」の友であり続けている。' WHERE character_id = 'CH017229';
UPDATE characters SET description = 'ウルドウィギアは雷のドラゴンであり、シャオユー・レイの右腕となった。' WHERE character_id = 'CH017230';
UPDATE characters SET description = '彼女は、傭兵や殺し屋を輩出する危険な一族、日本の阿賀倉一族の長女である。' WHERE character_id = 'CH017232';
UPDATE characters SET description = '職業：殺し屋、ボディガード　日暮に雇われ、「味方」として行動している阿賀倉一族の一員。' WHERE character_id = 'CH017233';
UPDATE characters SET description = 'ルフ・ヴェリゼはバイアンディ帝国の最後の宰相であり、フラムロディア・バイアンディラズ皇帝に仕えていたが、帝国の崩壊に近い時期に在職中に殺害された。彼女は死後もエレメンタルを感知する能力を保っており、そのためエレメンタルとは意思疎通ができるが、その姿を見ることはできない。' WHERE character_id = 'CH017235';
UPDATE characters SET description = '池内は、本部所属の警官で、「強盗犯」（西田）の捜索を「拷問棟」で指揮している。' WHERE character_id = 'CH017237';
UPDATE characters SET description = 'ウツロジュザ（本名：シュラ・ズーゾロゾ・クランプランプ・ランプトン）は、ビアンディ帝国の元第三位宮廷魔術師であり、かつては「世界の敵」とされていた人物である。 帝国の崩壊から1世紀が経過した今、彼は錬金術師パニ・グルドマルグと手を組んでいる。' WHERE character_id = 'CH017238';
UPDATE characters SET description = '西田は「遊童楼」のバーテンダーで、桃屋に殺害される。' WHERE character_id = 'CH017240';
UPDATE characters SET description = '人気小説家。恋愛小説を書こうとしたところ、スランプに陥り、編集者から逃れるために30年間も地下に引きこもってしまった。' WHERE character_id = 'CH017243';
UPDATE characters SET description = 'ドロシアの編集者。彼の表情は決して変わらない。巨大な黒いドラゴンに変身することができる。' WHERE character_id = 'CH017244';
UPDATE characters SET description = 'シャーロットの妹。' WHERE character_id = 'CH017252';
UPDATE characters SET description = '正体不明の魔女団に所属する魔女。' WHERE character_id = 'CH017270';
UPDATE characters SET description = 'アリエルと、チセの知り合い。' WHERE character_id = 'CH017271';
UPDATE characters SET description = '高梨セイは、聖者召喚の儀式によって召喚された20代のOLである。 聖人の力により能力が50％向上するが、その外見のせいで当初は聖人に認定されなかった。研究中にうっかり騒ぎを起こしてしまい、聖人であることがバレそうになったが、その実力を認められ、ついに聖人として正式に認定された。余暇には料理や手作りコスメ作りを楽しんでいる。' WHERE character_id = 'CH017275';
UPDATE characters SET description = '彼は第三騎士団の団長である。その冷徹な物腰から、「氷の騎士」という異名を持つ。致命傷を負ったところを高梨セイに救われたことをきっかけに、彼女の味方となった。' WHERE character_id = 'CH017276';
UPDATE characters SET description = '彼は薬用植物研究所の所長であり、ヴァルデック伯爵の次男である。' WHERE character_id = 'CH017277';
UPDATE characters SET description = '彼は王立魔術師会議の大魔導師である。彼の関心は、魔法や魔力に関する研究にのみ向けられている。外見は陽気で情熱的に見えるが、内面は全く別人のようだ。' WHERE character_id = 'CH017278';
UPDATE characters SET description = '彼はヨハン・ヴァルデックと同じ薬用植物研究所の研究員であり、高梨セイの指導を担当している。' WHERE character_id = 'CH017279';
UPDATE characters SET description = 'クラウスナー領のポーション調合を担当する、非常に経験豊富な錬金術師。セイが「聖者の魔法」を解き放ち、使いこなせるようになるよう、かつての聖人が残した唯一の日記を見せて教える。孫のレオに対しては、その率直すぎる物言いや配慮の欠如を頻繁に叱る。' WHERE character_id = 'CH017283';
UPDATE characters SET description = '彼は騎士の一人だ。ある遠征で片腕を失ったが、セイがそれを治してくれた。' WHERE character_id = 'CH017284';
UPDATE characters SET description = '彼女もまた、聖女召喚の儀式によって召喚されたもう一人の少女だ。' WHERE character_id = 'CH017285';
UPDATE characters SET description = '彼は王だ。' WHERE character_id = 'CH017286';
UPDATE characters SET description = '彼は副首席魔術師だ。また、アルバートの兄でもある。' WHERE character_id = 'CH017287';
UPDATE characters SET description = 'レインはスラントニアの第二王子であり、カイルの弟である。' WHERE character_id = 'CH017288';
UPDATE characters SET description = '彼女はアシュリー侯爵の娘であり、第一王子の婚約者である。' WHERE character_id = 'CH017289';
UPDATE characters SET description = 'かつては冒険者だったが、その夢はとっくに打ち砕かれてしまった。怪我のため故郷に戻らざるを得なかったが、心のどこかで冒険を諦めることはできなかった。その姿に感化され、娘も彼の後を追い、今なお彼は訓練を続けている。娘がつけた「レッド・オーガ」というあだ名には、かなり頭を抱えている。' WHERE character_id = 'CH017290';
UPDATE characters SET description = '「黒髪のヴァルキリー」として知られるSランクの冒険者。赤ん坊の頃に森に置き去りにされたが、ベルグリーヴに拾われ、その娘として育てられた。彼女は父親を深く愛している。' WHERE character_id = 'CH017291';
UPDATE characters SET description = '異端の大魔術師ソロモンを崇拝する異端の教えを広める謎の少女。彼女はウィーンの宗教に対して深い憎悪を抱いているようだ……' WHERE character_id = 'CH017292';
UPDATE characters SET description = 'シャーロットと一緒に働き、彼女を守る少年。いつも不機嫌そうな顔をしている。' WHERE character_id = 'CH017293';
UPDATE characters SET description = 'アンジェリーナのパーティにおける調停役、交渉役、そして弓使い。彼女とミリアムは同じ孤児院の出身である。AAAランクの冒険者。' WHERE character_id = 'CH017294';
UPDATE characters SET description = 'アネッサとミリアムが育った孤児院のシスターです。彼女はよく台所にいることが多く、孤児院の子供たちからとても慕われています。' WHERE character_id = 'CH017295';
UPDATE characters SET description = 'アンジェリーナのパーティーの一員で、魔法を専門とする。彼女とアネッサは同じ孤児院の出身である。AAAランクの冒険者。' WHERE character_id = 'CH017296';
UPDATE characters SET description = '森に残り続けていた悪魔の力の残滓。彼は子供の姿をとって、ベルグリーブの家の住人たちにべったりと寄り添っている。無表情だが、かなり好奇心旺盛だ。' WHERE character_id = 'CH017297';
UPDATE characters SET description = 'ボルドー地方の伯爵夫人で、姉妹の中で長女である。彼女自身も才能に恵まれているが、才能ある人々に囲まれると、つい自分を見失ってしまう傾向がある。' WHERE character_id = 'CH017298';
UPDATE characters SET description = 'かつて絶望と苦悩に囚われていた男。アンジェリーヌのおかげで、彼はかつての冒険仲間であるベルグリーヴと再会することができた。' WHERE character_id = 'CH017299';
UPDATE characters SET description = 'ボルドー家の次女。貴族らしい振る舞いがまったく苦手だ。身分とは裏腹に冒険者として活動しており、AAランクにまで上り詰めている。' WHERE character_id = 'CH017300';
UPDATE characters SET description = 'グラハムの曾姪であり、エルフの森の王の娘でもある。少々荒削りなところはあるものの、とても誠実で率直な性格の持ち主だ。' WHERE character_id = 'CH017301';
UPDATE characters SET description = 'ボルドー家の末娘。まだ若さゆえの無邪気さを残しつつも、統治の才能を発揮して姉たちを支えている。' WHERE character_id = 'CH017302';
UPDATE characters SET description = '年老いたエルフの冒険者であり、「パラディン」として知られる生ける伝説。マルグリットを追ってターナーにたどり着いた。' WHERE character_id = 'CH017303';
UPDATE characters SET description = '彼はボルドー家の執事である一方、剣士でもある。ボルドー家への思いがあまりに強いため、時折、我を忘れてしまうこともある……' WHERE character_id = 'CH017304';
UPDATE characters SET description = '15年前に亡くなり、ペペシャを孤児院に預けたペペシャの亡き母。' WHERE character_id = 'CH017306';
UPDATE characters SET description = '小石川イコの弟。大吾はスーパーヒーローの大ファンで、シャイに2度も助けられたことがある。' WHERE character_id = 'CH017307';
UPDATE characters SET description = 'ゲルム・シュタイン、通称ドクトル・シュヴァルツは、ドイツの英雄であり、ブラック・クロス医療部の部長である。' WHERE character_id = 'CH017308';
UPDATE characters SET description = '出身地：ティアムーン帝国／ルネア（帝都）／ホワイトムーン宮殿　ティアムーン帝国でただ一人の王女。怠惰で、わがままで、根っからの臆病者。明確な目標はなく、自分のことしか考えていない。 彼女が初めてサン・ノエル学園に入学したのは12歳の時だった。  その数年後、帝国は財政危機、飢饉、そして人口の10％が死亡する大疫病に見舞われ、荒廃の一途をたどった。ミアが17歳になった頃、革命軍は彼女が荒廃した' WHERE character_id = 'CH017309';
UPDATE characters SET description = '出身地：ティアムーン帝国　帝国軍随一の剣士。傭兵としての腕前が認められ、帝国軍に正式に編入され、100名の兵を率いる中隊長に就任した。  以前のタイムラインでは、ミアが宝石箱を欲しがったという身勝手な欲望が、シーレンスの森での紛争を引き起こし、その結果、ディオンの部下全員が命を落とすという悲劇が起きた。革命が勃発して間もなく、ディオンは革命軍に味方し、その打倒において重要な役割を果たした。' WHERE character_id = 'CH017310';
UPDATE characters SET description = '出身地：レムノ王国　ダイヤモンド軍団の司令官。' WHERE character_id = 'CH017311';
UPDATE characters SET description = 'ミアの忠実な家臣の一人。メイドとしての仕事には少々不器用な面があることで知られている。リットシュタイン家の長女。 平民で貧しい家庭の出身である彼女は、皇室への忠誠を誓ってホワイトムーン宮殿に来たのではなく、金に困っていたためにここに来たのである。  前回のタイムラインでは、ミアが投獄された当初の数週間は、数人の人が彼女を訪ねてきたが、彼女が決して王位を主張することはないと悟ると、その面会はすぐに途絶えてしまった。' WHERE character_id = 'CH017313';
UPDATE characters SET description = '誕生日シーズン：春（早春）　出身地：ベルーガ聖公国　サン・ノエル学園が位置するベルーガ聖公国の統治者、オルレアン公爵の娘。 ミアやシオンといった貴族や王族が通うサン・ノエル・アカデミーの生徒会長であり、事実上の実権者である。身分を気にかけず、庶民も貴族も平等に扱い、慈悲深く接する一方で、几帳面な性格の持ち主であり、正義を重んじる真の聖人である。' WHERE character_id = 'CH017314';
UPDATE characters SET description = '出身地：ティアムーン帝国　ミアの忠実な家臣の一人。 商人の家の次男として生まれ、幼い頃から秀でた才能を見せていた。彼は常に官僚になることを夢見ていたが、その目標に向かって勉強を始めた後、ティアムーン帝国がいかに根っから腐敗しているかをすぐに悟った。 そのため、彼は貴族や皇族を心底軽蔑していた。「放浪の賢者」の弟子。　以前のタイムラインでは、彼は' WHERE character_id = 'CH017316';
UPDATE characters SET description = '彼女は内気な少女で、ふさふさとした黒髪と、それ以上に分厚い眼鏡が特徴だ。彼女は、かなり大きな商売を営む商人の家に生まれた。冗談を交わすことよりも本を読むことを好むため、両親とは違って、ずっと控えめな性格をしている。' WHERE character_id = 'CH017317';
UPDATE characters SET description = '出身地：ティアムーン帝国／ルネティア（帝都）　アンの妹であり、リットシュタイン家の次女。生まれつき病弱で、普段は寝たきりである。趣味は小説を書くことで、前回のタイムラインでアンが刑務所でミアに語った物語の作者でもある。  前回のタイムラインでは、ミアの処刑前に、人との交流が乏しかったことや満足のいく食事が得られなかったことも一因となり、彼女は亡くなった。当時、刑務所で暮らしていたミアにとって、エリーゼの物語は彼女の' WHERE character_id = 'CH017318';
UPDATE characters SET description = 'ティアムーン帝国の南辺境に領地を持つアウトランド伯ルドルヴォンの長女。帝国において、アウトランド伯は下級貴族と見なされているが、その逆境を乗り越えるため、彼女は勉学に励むだけでなく剣術にも長けた才気あふれる女性である。 家族は、ルドルヴォン・アウトランド伯家の当主である父と、2歳年下の弟シリル・ルドルヴォンで構成されている。また、侍女のリオラ・ルルとも親しい関係にあり、' WHERE character_id = 'CH017320';
UPDATE characters SET description = '出身地：ティアムーン帝国／アウトランド伯領ルドルヴォン　アウトランド伯ルドルヴォンの長男であり、ティオナの弟。若くして学識豊かで、研究を好む。特に植物学に長けている。  以前のタイムラインでは、彼の研究が実を結び、「耐寒性小麦」の開発によって領内の食糧不足が解消され、革命軍が民衆の支持を得る上で大きな役割を果たした。本編のタイムラインでは、ミアがティオと交流する際、このことを思い出す。' WHERE character_id = 'CH017321';
UPDATE characters SET description = 'ティアムーン帝国に匹敵する誇り高き血統と権力を誇る、サンクランド王国の第一王子。何事にも卓越した才能を発揮する万能の天才であり、「公平」と「正義」を重んじる善良な青年である。  以前のタイムラインでは、彼はミアを「無能な統治者」と断じ、革命軍の指導者を支援し、ミアの処刑に立ち会った敵の一人であった。 <br>_(ライトノベル第2巻のネタバレ)_' WHERE character_id = 'CH017323';
UPDATE characters SET description = '出身地：ティアムーン帝国／ルネア（帝都）／ホワイトムーン宮殿　ティアムーン帝国の現皇帝であり、ミアの父。亡き妻を深く愛しており、彼女の死後も再婚していない。 ミアへの愛情で知られている。ミアに「パパって呼んで」と執拗に言い続けるが、彼女はいつもそれを拒み続けている。以前のタイムラインでは、ミアより先に処刑されていた。' WHERE character_id = 'CH017324';
UPDATE characters SET description = '出身地：ティアムーン帝国／シーレンスの森　ティオナ・ルドルヴォンに仕えるメイド。ルドルヴォン・アウトランド伯領とバーマン子爵領の国境にまたがる森林地帯「シーレンスの森」に暮らす少数民族、ルル族の出身である。 ルル族の多くは大陸の公用語に不慣れだが、彼女も例外ではなく、話し方に吃りがある。弓の達人であり、身体能力も高い。彼女は自分の' WHERE character_id = 'CH017326';
UPDATE characters SET description = '出身地：ティアムーン帝国、バーマン子爵領　ルドルヴォン家と隣接する領地を持つバーマン子爵家の当主。 彼は、アウトランド伯ルドルヴォン家の領地よりも自身の領地が狭いことを懸念しており、ルドルヴォン家からは「伯爵領の貴族」として見下されていると感じている。そこで、両領地の間に位置するシーレンスの森を強引に開拓する計画を立てている。  前回のタイムラインでは、これがルル族の間で内乱の勃発を招き、最終的には' WHERE character_id = 'CH017327';
UPDATE characters SET description = '出身地：レムノ王国／ドニ村　ハンター。' WHERE character_id = 'CH017328';
UPDATE characters SET description = '出身地：レムノ王国／フェドスクード城　レムノ王国の第二王子。女性に対して紳士的に接する、心優しい少年である。 しかし、剣術が重んじられ、男性優位の傾向が強いレムノ王国では、その性格ゆえに「弱虫」と呼ばれることが多かった。 特に、2歳年上の兄である第一王子ゲインとの剣術の稽古ではいつも負かされており、シオンの卓越した剣術を目の当たりにした時には――' WHERE character_id = 'CH017329';
UPDATE characters SET description = '出身地：ティアムーン帝国／アウトランド地方ルドルヴォン伯領　アウトランド地方ルドルヴォン伯家の当主であり、ティオナとシリルの父。' WHERE character_id = 'CH017330';
UPDATE characters SET description = '出身地：サンクランド王国　サンクランド王国の第一王子、シオン・ソル・サンクランドの側近。元々は戦争孤児だったが、現国王のアブラムに引き取られ、実の息子のように育てられた。 そのため、彼とシオンは兄弟のように共に育ち、時には二人の関係の境界線を越えて、まるで実の息子であるかのように率直に接し合うこともある。風変わりで皮肉屋ではあるが、根は忠実で誠実な若者である。  本作のタイムラインにおいて、' WHERE character_id = 'CH017332';
UPDATE characters SET description = '出身地：レムノ王国' WHERE character_id = 'CH017334';
UPDATE characters SET description = '「ヒトリ」という名の少年の身分を装い、彼と弟のミギは、中年の夫婦である園山夫妻に養子として迎え入れられる。彼は論理的で几帳面な性格だ。 ダリは復讐に最も執着している双子の一人で、ミギに「良い子」のようにこっそりと行動するよう指示するが、時折、冷静さを失うこともある。ダリはミギを非常に大切にしており、誰かがミギに手を出そうものなら、ダリは暴力に訴えることもある。' WHERE character_id = 'CH017335';
UPDATE characters SET description = '「ヒトリ」という名の少年のふりをした彼は、兄のダリとともに、中年の夫婦である園山夫妻に養子として迎え入れられる。感情面では、二人のうち彼の方がより繊細で、自分の感情をコントロールするのに苦労している様子が描かれている。' WHERE character_id = 'CH017336';
UPDATE characters SET description = '彼は全く世渡りの術を知らず、他人の気持ちにも無頓着で、友情の意味も理解していない。自分の発言が人を不快にさせる可能性があることに気づかず、しばしば事実だけを淡々と述べる。彼がエリザベスの旅に同行することを決めたのは、正義感からではなく、「七つの大罪」の一員としての義務感からだった。  ゴウサーは感情を理解できないため、それを理解しようと多大な努力を払っている。例えば、メリオダスとバンの友情を観察することなどだ。' WHERE character_id = 'CH017346';
UPDATE characters SET description = 'メラスクラは魔族の戦士であり、「十戒の信仰」として魔王の直属に仕えている。' WHERE character_id = 'CH017347';
UPDATE characters SET description = '彼女は「七つの大罪」の一員である。彼女は「大食」という罪の印を背負っている。ブリタニアで最も偉大な魔術師と見なされており、ヴィヴィアンの師匠であると同時に、キャメロットのアーサー王の師でもあった。 彼女はヘンドリクソンとの戦いで「七つの大罪」を援護したが、王の世話をするためにその場を離れざるを得なかった。正式には「七つの大罪」に復帰してはいないが、他の用事が済んだらすぐに復帰すると述べている。' WHERE character_id = 'CH017348';
UPDATE characters SET description = 'リオネスの第11代王であり、エリザベスの父。七つの大罪が偉大なる聖騎士ザラトラスの殺害の罪を着せられた後、彼は捕らえられた。' WHERE character_id = 'CH017350';
UPDATE characters SET description = 'オルロンディは吸血鬼であり、吸血鬼一族の王族の一員である。彼は12年前、一族がエディンバラ王国を支配していた時期に、吸血鬼王に仕えていた。' WHERE character_id = 'CH017351';
UPDATE characters SET description = 'かつては山賊だったが、現在は商人として活動しており、ヴァイゼルで毎年開催される格闘祭で3度の優勝を果たしている' WHERE character_id = 'CH017352';
UPDATE characters SET description = 'ペリオは、仲間の子供たちと同じように、「七つの大罪」の役を演じたり、村人たちに指図したりするのが大好きな少年だ。' WHERE character_id = 'CH017353';
UPDATE characters SET description = 'ドロレスはジャイアント一族の一員であり、ダイアンの友人である。' WHERE character_id = 'CH017354';
UPDATE characters SET description = 'ジェリコは、「ウィアード・ファングス」に仕えていた聖騎士見習いである。彼女は、七つの大罪の一つである「バン」が投獄されていたバステダンジョンに配属されていた。彼女はほっそりとした体型の若い女性で、明るい色の髪を顔の左側に流し、後ろでポニーテールに結んでいる。 鎧の上には黒いコートを羽織っており、左側には十字架の装飾が施され、背中を覆う大きな十字架が特徴だ。鎧の下には、同様のデザインの黒い服を着ている。腕は金属製のガントレットで覆われており、また' WHERE character_id = 'CH017355';
UPDATE characters SET description = 'ハウザーは聖騎士であり、ギルサンダーの同僚兼パートナーであり、大聖騎士ドレイファスの部下である。聖騎士の鎧を身にまとい、明るい色の短い巻き毛をしている。 ハウザーは強い自信に満ちており、非常に楽観的である。これはギルサンダーの性格とは正反対であり、また、やや世間知らずで間抜けな一面も見せている。' WHERE character_id = 'CH017356';
UPDATE characters SET description = 'スレイダーは幼い頃に誘拐され、人間としての価値を全く顧みない野蛮人たちに育てられた。リオネスの王によって救出された後、彼は忠誠を誓い、王国に害をなした者たちをすべて追い詰めることを決意した。彼は「ドーン・ロア」の一員であり、「七つの大罪」のゴウサーと対立関係にある。' WHERE character_id = 'CH017357';
UPDATE characters SET description = 'ギーラは、死者の都へ入り、そこに潜んでいた「七つの大罪」を討ち取るために、自らを死の淵に追い込んだ聖騎士である。彼女は細身の体型の若い女性で、長い黒髪を持ち、目は閉じているかのように描かれている。' WHERE character_id = 'CH017358';
UPDATE characters SET description = 'ガランドは、魔王自らが厳選した魔族のエリート戦士集団「十戒」の一員である悪魔だ。彼は、ヘンドリクソンによって解放されるまで、他の一族の者たちと共に「永遠の闇の棺」に封印されていた。' WHERE character_id = 'CH017359';
UPDATE characters SET description = '彼女が5歳のとき、両親が相次いで亡くなり、ヤクザの祖父に引き取られた。' WHERE character_id = 'CH017360';
UPDATE characters SET description = '彼は26歳のヤクザの組員だ。' WHERE character_id = 'CH017361';
UPDATE characters SET description = '千枚木の指導者の一人。' WHERE character_id = 'CH017362';
UPDATE characters SET description = 'タヌキグループの後継者。' WHERE character_id = 'CH017363';
UPDATE characters SET description = 'チーム：スピカ　彼女の笑顔は部屋全体を明るく照らす。お祭りが大好きな、まさに「太陽のような存在」。　いつも明るく陽気で、誰よりもお祭りが大好きだ。生まれつきの利他的な性格から、困っている人を放っておくことができず、いつでも誰かの話に耳を傾ける準備ができている。 その底知れぬ優しさは周囲の人々から称賛を集めているが、興奮しすぎると、彼女の言葉にはどこか祭りらしい賑やかさが混じってしまう。太陽のように輝く笑顔を浮かべ、彼女はまばゆいばかりの地平線へと走り続け、願っているのは――' WHERE character_id = 'CH017364';
UPDATE characters SET description = 'チーム：カペラ　ダイヤモンドよりも強靭な意志の持ち主！どんな呪いにも立ち向かえる！  裕福な家に生まれ、幼い頃から愛情をたっぷり注がれて育った。この過保護な育ち方のせいで、彼女は少々世間知らずな面もあるが、その穏やかで誠実な物腰の奥には、ダイヤモンドのように固い決意が隠されている。彼女は、里野家の呪いを打ち破り、一族の名誉を取り戻すことを固く決意し、断固として歩み続けている。' WHERE character_id = 'CH017365';
UPDATE characters SET description = 'ワイルドで予測不能、この金髪のランナーは他の誰とも違う！　生まれつき自由奔放な気質をたっぷり備えた、予測不能な熱血漢だ。彼女の気分ややる気は劇的に変動しがちで、ある瞬間は手の込んだオチを仕込んでいるかと思えば、次の瞬間には彼女を動かすのが一苦労になるほどだ。 誰とでも仲良くしているように見えますが、他者との絆を彼女がどう捉えているのかは定かではありません。まさに、彼女こそがトレーセン随一のいたずらっ子だと言えるでしょう。' WHERE character_id = 'CH017366';
UPDATE characters SET description = 'チーム・スピカのトレーナー。' WHERE character_id = 'CH017368';
UPDATE characters SET description = '彼女の体には、最も力強い血が流れている。名門の血筋を受け継ぐ、将来有望なエリートウマ娘だ。数多くの優秀なアスリートウマ娘を輩出してきた名門の家系に生まれた。 普段は真面目で冷静な性格だが、レースが目前に迫ると闘志が燃え上がり、そのワイルドな一面を見せる。幼い頃からエアグルーヴと親しい友人関係にある。' WHERE character_id = 'CH017369';
UPDATE characters SET description = 'ポジティブな雰囲気だけ！マジで、マジで！冗談じゃないよ！ ☆ パーティーの準備はできてる？このランナーだよ！「私、うるさい？まあ、当たり前でしょ！何かやるなら、楽しくしなきゃ！もしそれを『気まずい』って言うなら、もっと音量を上げちゃうわ！ ♪」これが、明るくおしゃべりなこのランナーの心構え。笑顔が爆発するほど楽しめて、パーティー三昧になる準備をしておいてね。だって彼女は楽しむためにここにいるんだから。ヘリオスは招待を断るようなタイプじゃないし、どんな場面も最高に盛り上げるのが得意なんだ。' WHERE character_id = 'CH017370';
UPDATE characters SET description = 'さあ、出発だ！ 夢に向かってまっすぐ進む、純粋な少女。北海道生まれのスペシャルウィークは、明るく陽気で、努力家のウマ娘だ。生みの母親を亡くした後、スペシャルウィークは母親の友人に育てられた。 今、彼女は「日本一の競走馬になる」という約束を果たし、二人のママを誇りに思ってもらいたいと願っている。その道のりでつまずくこともあるかもしれないが、彼女の不屈の精神が、常に前へ前へと走り続けることを支えている。' WHERE character_id = 'CH017371';
UPDATE characters SET description = 'ターボブースト！このワイルドなチャージャーには限界なんてない！　若々しいエネルギーに満ち溢れ、ただひたすらに走り、走り、狂ったように走り続けたいと願う学生だ！　まだ自分の限界をあまり理解していないため、つい全力を出しすぎてしまう傾向があるが、そのワイルドな生き方を楽しんでいるようだ。 同年代の他のランナーたちに比べると少し未熟で、自己中心的なところもあるけれど、その率直で自由奔放な性格を責めることは難しい。' WHERE character_id = 'CH017372';
UPDATE characters SET description = 'さあ、楽しく過ごしましょう！この「うま娘」は陽気で、いつも友達のそばにいてくれます。名門・目白家の令嬢ですが、その気さくで親しみやすい態度からは、そうは思えないかもしれません。 彼女は社交的で、周囲の人々の些細な変化にも気づくほどですが、才能あふれる親戚たちに囲まれているため、少し劣等感を抱いていました。しかし、やがてその感情と向き合う方法を見つけました。それは、走り、走り、そしてさらに走り続けること。その間ずっと笑顔を絶やさないのです。走り続ける限り、' WHERE character_id = 'CH017373';
UPDATE characters SET description = '彼女は自信に満ちた若い女性で、世界最高の地位である「女王」という称号にふさわしいことを誇りに思っています。3人姉妹の長女として、2人の妹たちにとって良き手本となるよう努めています。裕福な家庭で高度な教育を受け、非常に才能豊かで、多くの実績を積んでいます。 しかし、彼女は「2」という数字に呪われており、勝利を収めるのに苦労している。' WHERE character_id = 'CH017374';
UPDATE characters SET description = '無敵で愛らしい！ 陽気で跳ね回るレーサー。 明るく元気いっぱいの「うま娘」で、レースの才能に恵まれている。 彼女はかねてより生徒会長のシンボリ・ルドルフを憧れの存在としており、この憧れこそが、ナンバーワンのレーサーになるための最大の原動力となっている。 ファンたちは、テイオの尽きることのない自信に魅了され、彼女の陽気な足取りを「テイオ・ステップ」と愛情を込めて呼んでいる。' WHERE character_id = 'CH017375';
UPDATE characters SET description = '率直で前向きなこの模範生は、常に110％の力を出し切っています！しかし、その努力にもかかわらず、彼女の内なるおっちょこちょいぶりが、肝心な場面でつまずいてしまうことがよくあります。 こうした浮き沈みが相殺され、その結果は――彼女自身によれば――ごく平均的なものになっている。時には、周囲の個性豊かな人たちのようにありたいと願うこともあるが、彼女は自分のやり方で突き進み、成功を掴み取ることを決意している！' WHERE character_id = 'CH017376';
UPDATE characters SET description = '不運の使者？　このレーサーは、暗い性格にもかかわらず、夢を追い続けている。内気なウマ娘である彼女は、周囲に降りかかる不運はすべて自分のせいだと思い込んでいるが、実際には単なるタイミングの悪さなだけなのだ。 それでも、彼女は自分についたというこの「不運」を断ち切ろうと決意している。暇なときは絵本を読むのが大好きで、特に『幸運の青いバラ』を好んで読んでいる。' WHERE character_id = 'CH017377';
UPDATE characters SET description = '自分の考え方や自分自身を変えるために、この悲観主義者は全力を尽くしている。彼女の自尊心は、耳と同じくらいまで下がってしまっている。 この不器用な少女にとって、物事はいつもうまくいかないようだ。それでも、彼女はより良い自分になることを決意しており、明るい未来を手に入れるチャンスのために、決して諦めようとはしない。彼女はT.M.オペラ・オーの堂々とした自信に憧れている。' WHERE character_id = 'CH017378';
UPDATE characters SET description = 'ヴィヴロスは、悪魔のように可愛い若い女性です。3人姉妹の末っ子で、裕福な家庭に育ったため、子供の頃から甘やかされて育ちました。休暇でドバイを訪れて以来、その街に魅了され、この豪華な国でセレブのような生活を送ることを夢見ています。 彼女の目標は、生まれ持った才能と抜群のタイミング感覚を武器に、ドバイでのレースに出場することです。' WHERE character_id = 'CH017379';
UPDATE characters SET description = 'わがままで、生き生きとしている！心優しいロードスター。 一番クールな存在になることに情熱を注ぐこの「うま娘」は、不良ぶることに全力を尽くしている。バイク好きの父親に似て、その趣味や態度を忠実に真似している。 目立ちたがり屋な性格ゆえ、どんな挑戦にも果敢に立ち向かい、目の前の困難を恐れることは決してない。ルームメイトの大和スカーレットとは、少し猫と犬のような関係にある。' WHERE character_id = 'CH017380';
UPDATE characters SET description = '完璧主義者。どんな状況にも柔軟に対応できる実力派のウマ娘。  秘書並みの組織力を備えた、堅実なウマ娘。冷静沈着な判断力で自身のコンディションを巧みに管理しているが、その厳しさとは裏腹に、意外にも親しみやすい性格だ。かつて走ることができなかった過去を糧に、可能な限り長く走り続けることを強く決意している――' WHERE character_id = 'CH017381';
UPDATE characters SET description = '冷静沈着な「女帝」。卓越した才能と野心を兼ね備えている。トレーセン・アカデミー生徒会の副会長であり、他の生徒たちからは「女帝」として知られている。 名だたるレーサーを母に持ち、母のレースにおける実力と、人々を導く手腕に追いつこうと常に努力している。そのために、親友であり心許せる相手であるシンボリ・ルドルフと共に生徒会に入会した。多忙なスケジュールの中でも、庭の花の手入れをする時間を必ず作っている。' WHERE character_id = 'CH017382';
UPDATE characters SET description = '幸運が私と共にありますように！この魅力あふれる「ウマ娘」は、占い adores が大好き。占いに夢中な上、超常現象にも興味津々で、レースの結果をはじめ、あらゆることを運任せにすることに何の不満も感じていない。 自分のために占いをしていない時は、誰かのために占っている。彼女は、走り続ける限り、進むべき道が目の前に開かれるという、ある神からの啓示を深く信じている。彼女が持ち歩いている猫型のバッグの名前は「ミス・ニャ」だ。' WHERE character_id = 'CH017383';
UPDATE characters SET description = '伝説を築け！　一風変わった視点から「最強」を目指す。  自主性を発揮して活躍する賢いウマ娘。「最強」のウマ娘となり、人々の心を掴むために、レースだけでなく、ファンにアピールする方法も熱心に研究している。 ファンの前では真面目な姿を見せるが、他人にはその一面を見せない。まさにセルフプロデュースの達人だ。' WHERE character_id = 'CH017385';
UPDATE characters SET description = '音の壁を破ることを目指す、物静かなランナー。比喩的にも文字通りにも、常に群を抜いて先頭を走る天才と見なされている「ウマ娘」だ。走ることに没頭しすぎて、人見知りな印象を与えることもあるが、その献身的な姿勢は周囲にも広く知られている。スペシャルウィークと同室で、その飾らない人柄に惹かれる人も多い。' WHERE character_id = 'CH017386';
UPDATE characters SET description = '彼女にはあまり期待しないほうがいい。このウマ娘は超シニカルだ。 貧しい家庭に育ち、悲観的になりがちなウマ娘だ。 自分を脇役だと思い込みがちで、そのせいで高い期待を避けようとしてしまう。そのため、時折、完璧とは言えないパフォーマンスになってしまうこともある。労働者階級の家庭で育ったため、料理や掃除にはかなりの手腕があり、時間があるときはいつでもそれらを行っている。町の年配者たちにとっては、お馴染みの顔と言える存在だ。' WHERE character_id = 'CH017387';
UPDATE characters SET description = '常に命令に従う！サイボーグのウマ娘。「サイボーグ」の異名を持つウマ娘。彼女はプログラミングやデータベースという視点を通じて世界を見つめ、無表情でロボットのような振る舞いで目標を達成していく。 とはいえ、彼女は感情のない機械というわけではない。幼い頃から絶え間なく訓練を受けてきた結果、人との関わりが少なくなり、現在の性格が形成されただけなのだ。そのロボットのような外見の下には、確かに感情が宿っている。' WHERE character_id = 'CH017388';
UPDATE characters SET description = 'リッキー☆ラッキー☆思いやりのある風水ガール☆  明るく陽気な性格で、一般的に「とても幸運な女の子」と言われています。彼女の風水に関する知識は深く、そのすべてが本物です。 彼女は日常生活だけでなく、トレーニング中やレース中にも風水を取り入れています。その風水の力で、みんなを幸せにしたいと願っています！それだけでなく、幸運を招くための彼女のアドバイスも好評を博しているようです……' WHERE character_id = 'CH017390';
UPDATE characters SET description = 'この学級委員、暴走中！ フルスピード・バクシーン！　どんな状況にも無謀に突っ込んでいく学級委員。一度心に決めたことは、目標に向かってバクシーンと一直線に突き進む――その結果、問題を解決するどころか、かえって大混乱を招いてしまうことも多い。 しかし、彼女は決して独善的に振る舞うことはなく、誰も助けを求めてくれないと落ち込んでしまう傾向がある。その短距離走の才能は圧倒的で、比類なきスピードで誰よりも速く走れると自信を持っている。' WHERE character_id = 'CH017391';
UPDATE characters SET description = '名門目白一族の至宝。気品と落ち着きを兼ね備えた若い令嬢。競馬界の伝説的な一家に生まれた目白マックイーンは、同世代の馬たちからも羨望の的となる長距離ランナーだ。 その名門にふさわしい気品と品格を備え、先人である多くの目白の競走馬たちと同様に、天皇賞での優勝を固く決意している。休日は、目白邸に住む多くの住人たちとアフタヌーンティーを楽しむのが彼女の楽しみだ。' WHERE character_id = 'CH017392';
UPDATE characters SET description = 'ターフ・マジシャン！ 頼りになるエリートお姉さん。香港と日本を拠点に活動する、明るく意志の強いお姉さんだ。また、里野家の才能あふれる一員でもあり、一族からの大きな期待を背負っている。逆境に直面すればするほどその輝きを増す性格の持ち主で、時にはまるで魔法のように見事に問題を解決することもある。' WHERE character_id = 'CH017393';
UPDATE characters SET description = '傲慢というレベルを超えている！この短気な彼女は、負けることを何よりも嫌う。 屈服を知らず、意志が強く、生意気な彼女は、何事においてもナンバーワンになりたいと願っている。普段は完璧で物静かな優等生のふりをしているが、実のところ、彼女は何よりも負けることを嫌っているのだ。 ナンバーワンになれるなら、どんなに過酷なトレーニングでも厭わない。彼女は、派手なルームメイトのウォッカを、自分のモチベーションの源であると同時にライバルでもあると見なしている。' WHERE character_id = 'CH017394';
UPDATE characters SET description = '野心はあるが、心は臆病。偉大なウマ娘になることを目指している。内向的で人見知りが激しく、才能あふれる姉と妹に対して劣等感を抱いている。いつか二人を追い越し、自分の実力を認められるよう、日々懸命に努力している。 姉妹たちとは不仲というわけではないが……二人とも華やかな気質を持っているため、一緒にいると彼女は少し場違いな気分になってしまう。' WHERE character_id = 'CH017395';
UPDATE characters SET description = 'ミホノ・バーボンの調教師。彼女は彼を「マスター」と呼んでいる。' WHERE character_id = 'CH017396';
UPDATE characters SET description = 'ハルカは、無口な高校生であり、「小牧モーターズ」に所属する「F4」レーサーだ。  「誰の助けもいらない」と断言する頑固な性格で、表彰台に立つという夢を叶えるため、ひたむきに走り続けている。普段は小牧家に下宿し、新聞配達としてアルバイトをしている。' WHERE character_id = 'CH017398';
UPDATE characters SET description = '小牧モーターズF4チームのメカニックであり、チームオーナーのフトシの息子。' WHERE character_id = 'CH017402';
UPDATE characters SET description = 'ベルソッリソ・モータースポーツ・チームのドライバー。' WHERE character_id = 'CH017404';
UPDATE characters SET description = 'ベルソッリソ・モータースポーツ・チームのドライバー。' WHERE character_id = 'CH017406';
UPDATE characters SET description = 'コノハはビジュアルノベルや美少女ゲームに並々ならぬ情熱を注いでいる。彼女は古典的な作品も現代の作品も等しく愛している。しかし、勤務先で背景キャラクターのイラスト担当として採用された際、大きな失望を味わった。彼女の最大の夢は、自分だけのゲームを作ることだ。彼女は非常に子供っぽい性格で、すぐに興奮しやすく、泣き虫なところがある。' WHERE character_id = 'CH017410';
UPDATE characters SET description = 'アルコールソフトの専属プログラマーであり、社長の息子。自身のプログラミング能力には絶大な自信を持っており、PC-98に対してほぼ執着に近いほどの愛着を抱いている。美少女ゲームのプログラミングを手がけているものの、そのジャンル自体には特に愛着はない。' WHERE character_id = 'CH017411';
UPDATE characters SET description = 'Alcoholsoftのチーフイラストレーターで、非常に腕が立つ。性格は穏やかだ。アニメでは、Alcoholsoftで最初にコノハを受け入れた人物であり、彼女が姿を消した際には心配している。' WHERE character_id = 'CH017415';
UPDATE characters SET description = 'Alcoholsoftのアーティスト兼プランナーで、トレードマークの猫耳帽子を被っている。穏やかな性格で、美少女ゲームに深い情熱を注いでいる。会社に対しては冷静な見方をしているが、アニメではコノハの状況が気にかかっている。' WHERE character_id = 'CH017416';
UPDATE characters SET description = '「KikiLala」というペンネームで知られる双子の作家の一人' WHERE character_id = 'CH017417';
UPDATE characters SET description = '「KikiLala」というペンネームで活動する双子の作家のうちの一人' WHERE character_id = 'CH017420';
UPDATE characters SET description = '最下層の「下忍（げんいん）」で、ニートのような生活を送っている。雲隠れの氏族の末裔である。' WHERE character_id = 'CH017429';
UPDATE characters SET description = '雲隠れのトイチは、雲隠れの兄弟姉妹の中で唯一の女性である。彼女はジュニロの双子の妹だ。トイチは最強のくノ一（女性忍者）と言われている。彼女は野口家に身を寄せている。' WHERE character_id = 'CH017432';
UPDATE characters SET description = '雲隠のジュロは、NINで最強の男だと言われている。' WHERE character_id = 'CH017436';
UPDATE characters SET description = 'ジュニロ・クモガクレは、NIN少年上級部隊で最強の男だと言われている。' WHERE character_id = 'CH017454';
UPDATE characters SET description = '彼女は藤野美咲高校の1年生で、極度の恐怖心から友達を作ることができず、地球以外の惑星に住む宇宙人なら自分の気持ちを伝えられるだろうと考え、現実から逃避していた。彼女は極度の恐怖を抱えており、他人とうまくコミュニケーションをとることができない。 ユウと出会った後、二人は宇宙の星々へたどり着くためのロケットを作るという目標を掲げた。彼女の特技は水泳だ。' WHERE character_id = 'CH017455';
UPDATE characters SET description = 'ユウはウミカの同級生で、自称「宇宙人」だ。彼女は「オデコパシー」と呼ばれるテレパシー能力を持っており、自分の額を相手の額に当てると、相手の考えを読み取ることができる。 彼女は並外れた楽観主義者で明るい性格の持ち主であり、周囲の不安や緊張を瞬く間に和らげてしまう。  また、地道な努力や勉強は苦手だ。生まれつきの明るさとエネルギーのおかげで、新しいクラスメートともすぐに打ち解けることができる。宇宙船の故障により、彼女は不時着し、' WHERE character_id = 'CH017456';
UPDATE characters SET description = 'ホナミはウミカの妹です。' WHERE character_id = 'CH017461';
UPDATE characters SET description = '江見原先生は、海香とその友達たちの担任の先生です。' WHERE character_id = 'CH017462';
UPDATE characters SET description = '彼はミネット社の企画・営業部の部長であり、仕事では集中力が高く、実績も良好である。一方、仕事以外の場面では、すぐに気が散ってしまい、ミスを犯すことがよくある。' WHERE character_id = 'CH017465';
UPDATE characters SET description = '彼はミネットの企画・営業部門に所属する社員であり、白崎悠星の直属の部下である。' WHERE character_id = 'CH017466';
UPDATE characters SET description = '彼はミネット社の企画・営業部のマネージャーである。光雄は家を購入した直後に妻に逃げられ、担当していた新入社員も1週間で辞めてしまったため、自尊心が低く、孤独を感じている。 彼は仕事に多くの時間を費やす傾向があり、妻と過ごす時間をあまり取らないことが多い。とはいえ、これは妻と一緒に購入した新居の借金や住宅ローンを返済するために、多くの仕事をこなさなければならなかったという事情によるものだ。妻は、彼が' WHERE character_id = 'CH017467';
UPDATE characters SET description = '彼はミネット社の企画・営業部門で働いています。' WHERE character_id = 'CH017468';
UPDATE characters SET description = '白崎悠星の兄。彼より2歳年上で、写真家として働いている。' WHERE character_id = 'CH017471';
UPDATE characters SET description = '次男。冷静沈着。弟のミナトを深く愛し、溺愛している。' WHERE character_id = 'CH017472';
UPDATE characters SET description = '長男。3人の弟たちの世話を他人に任せることに葛藤を抱える学校教師。' WHERE character_id = 'CH017473';
UPDATE characters SET description = '三男。' WHERE character_id = 'CH017474';
UPDATE characters SET description = '四男。' WHERE character_id = 'CH017475';
