UPDATE characters SET description = '4人の月見兄弟姉妹の父親。' WHERE character_id = 'CH017479';
UPDATE characters SET description = '教師であり、ハヤトの同僚。' WHERE character_id = 'CH017481';
UPDATE characters SET description = 'ミナトの親友。柚木家の向かいに住んでいる。' WHERE character_id = 'CH017483';
UPDATE characters SET description = '教師であり、ハヤトの同僚。' WHERE character_id = 'CH017484';
UPDATE characters SET description = 'ウタとワカの母親。警察官として働いている。' WHERE character_id = 'CH017487';
UPDATE characters SET description = 'ある少年がウタにデートを申し込むと、彼女は無邪気で純真なまま、その申し出を快く受け入れた。' WHERE character_id = 'CH017488';
UPDATE characters SET description = 'サキの父親であり、ウタとワカの祖父。柚木家と隣同士で、ガクトとよく将棋を打っている。' WHERE character_id = 'CH017489';
UPDATE characters SET description = 'カオルの馬。' WHERE character_id = 'CH017497';
UPDATE characters SET description = '異世界に転生したオタクが、なぜか豚になってしまう！？ 彼は自分には特別な能力がないと思い込んでいるが、機転と知恵、そして度胸を駆使して問題を解決していく！' WHERE character_id = 'CH017508';
UPDATE characters SET description = '「あの、ジェス。あのブタ、友達なの？　ずっと私の足を見て、変なこと言ってるんだけど。」   ジェスとブタが旅の途中で出会った、イェスウマ出身のイェスマ族の少女。ブタが彼女の足を見つめながら空想にふけり始めたとき、彼女はブタの正体が実は人間だと気づく。' WHERE character_id = 'CH017511';
UPDATE characters SET description = '投獄されていた、無口なイェスマの少女。' WHERE character_id = 'CH017512';
UPDATE characters SET description = 'ノットが連れ歩いている大きな犬。戦闘ではノットと協力して戦う頼もしい相棒だ。狼のような外見だが、人懐っこく、ジェスの素足を嗅ぐのが好きだ。' WHERE character_id = 'CH017513';
UPDATE characters SET description = '彼は母親と妹のミオと共に、貧しい生活を送っている。ある事故により、父親が亡くなり、ミオは歩くことができなくなってしまった。ミオの世話をし、家計を支えるために、彼はオンラインゲームへの情熱を諦め、学校とアルバイトに専念する生活を送らざるを得なくなった。（出典：公式サイト、翻訳）' WHERE character_id = 'CH017514';
UPDATE characters SET description = '新進気鋭の女優。その振る舞いや話し方は荒々しく、期待外れの少女という印象を与える。eスポーツの大会に出場する際は、マスクで正体を隠している。（出典：公式サイト、翻訳）' WHERE character_id = 'CH017515';
UPDATE characters SET description = 'シュンの幼なじみ。eスポーツカフェ「FOX ONE」の店長である稲月ソウタの娘で、放課後はそこでスタッフとして手伝いをしている。シュンの家族、特に妹のミオとは親しい関係にある。' WHERE character_id = 'CH017516';
UPDATE characters SET description = 'AKYRの陽気なリーダー。いつも笑顔を絶やさないが、本心は読み取れない。長い間アンダーグラウンドの世界に身を置いてきたため、善悪の区別に関する常識がやや欠けている。メンバーを家族のように大切にし、彼らのための居場所を作ることだけに心を注いでいる。' WHERE character_id = 'CH017523';
UPDATE characters SET description = 'ナオキラは「ザ・キャッツ・ウィスカーズ」のメンバーである。昼は言語学の教授、夜はバーのオーナーという二面的な生活を送っている。彼は常に冷静沈着だ。誰に対しても差別なく親切に接し、困っている人を放っておくことができない。現在経営しているバーに対して、深い愛着を抱いている。' WHERE character_id = 'CH017524';
UPDATE characters SET description = '何よりもヒップホップを愛する若者。目つきが怖く、人当たりも良くないため、周囲からは話しかけにくいと思われがちだが、実はただ不器用なだけなのだ。 彼は、ピアニストの父とオペラ歌手の母の間に、4分の1がロシア系の血を引くとして生まれた。有名な音楽一家の出身でもあるが、ヒップホップへの情熱を両親が快く思わなかったため、家を出た。' WHERE character_id = 'CH017525';
UPDATE characters SET description = 'ヤトノカミ家の年上の双子の兄。貧しい街で孤児として育ち、自分を虐げてきた大人たちに育てられたため、誰をもほとんど信用しない。 彼は不注意で物事を面倒くさがりがちだが、双子の弟であるナユタのためなら何でもするほど献身的だ。現在、双子は怪しげなアンダーグラウンドの組織でラップをして稼いだ金で生計を立てている。' WHERE character_id = 'CH017526';
UPDATE characters SET description = '韓国でも有数の大手金融コングロマリットの一家に生まれた。 その物腰と容姿から「微笑む若き貴公子」というあだ名で呼ばれていたが、実のところかなりサディスティックな性格である。利害の対立や隠された思惑が渦巻く複雑な環境に生まれたため、彼は人生の半分を激動の中で過ごし、心の中で両親への復讐を誓っていた。' WHERE character_id = 'CH017527';
UPDATE characters SET description = '外見はファッショナブルでモダンな女の子そのものですが、実はBAEの中で最も男らしい存在です。若い頃は、古風で厳格な母親に抑圧されていました。そのため、自分らしく生きることを決意したのです。現在は、その美貌を活かしてホステスとしてアルバイトをしています。' WHERE character_id = 'CH017528';
UPDATE characters SET description = '彼は内向的で控えめな性格だ。以前、家出をした際、サイモンに拾われ、バーで働き始めた。 そうして、彼はホールスタッフとして働くタダ乗り生活者となった。常に緊張しており、自信はまったくないが、一度聴いただけでどんな曲でも思い出せるという特技――彼の隠れた才能――に長けている。' WHERE character_id = 'CH017529';
UPDATE characters SET description = 'ヤトノカミ家の双子の弟。ナユタは幼い頃から病弱だったため、兄のカナタに深く愛され、手厚く世話をされている。そのため、彼の自己中心的な性格がやや際立っている。これまで自分を守ってくれたカナタを、絶対的に信頼している。 普段は周囲に対して無愛想な態度をとっているが、カナタのことになると途端に途方もなく興奮してしまう。また、コズメズの衣装の準備も担当している。' WHERE character_id = 'CH017530';
UPDATE characters SET description = '『Paradox Live』の司会者。' WHERE character_id = 'CH017531';
UPDATE characters SET description = '大柄で筋肉質な体つきを持ち、非常に率直で情熱的な性格の男性。場の空気を読むのが苦手だが、それがAKYRの秩序を保つ上で大きな要因となっている。 ゼンはもともと警察官だったが、イオリと出会った後、ある事情から彼に加わることを決めた。ホストクラブでは、ホストたちのトラブルコンサルタントを務めている。' WHERE character_id = 'CH017532';
UPDATE characters SET description = '子供っぽくも謎めいたラッパーであり、「ザ・キャッツ・ウィスカーズ」のメンバー。リュウは、本作の物語が始まる前にナオアキラに見出された。現在はヨヘイの指導のもと、バーテンダーを目指して修行中だ。また、リュウは「アカン・ヤツラ」のホクサイとも親しい間柄である。 リュウは風変わりでエネルギッシュな人物で、しばしば支離滅裂なことを口にし、周囲を困惑させたり苛立たせたりするような行動をとることがある。' WHERE character_id = 'CH017533';
UPDATE characters SET description = '彼は、自分のメンバー以外なら、文字通り目につく人なら誰とでも喧嘩をする。強がっているように見えるが、実はとても誠実で善良な若者だ。 かつて、彼は親友に裏切られ、辛い時期を過ごした。その頃、彼を拾ってくれたイオリについていった。彼は、自分のMCネームである「ガイア」が女神の名前であることを知らない。' WHERE character_id = 'CH017534';
UPDATE characters SET description = '概して言えば、彼はAKYRの中で最も活発な最年少メンバーだ。感情をすべて顔に出してしまうタイプである。得意技は他人に仕事を押し付けることで、その手口は非常に巧妙だ。 かつては豪邸に住む若旦那だったが、ある事件をきっかけに家族は崩壊してしまった。その際、彼は伊織に拾われた。' WHERE character_id = 'CH017535';
UPDATE characters SET description = '謎めいた雰囲気を持つ青年。父親が刑務所に服役していたため、孤独な幼少期を過ごさざるを得なかった。路上で生活していた頃、周囲に猫が次々と集まってくるようになり、それ以来猫が大好きになった。 ある騒動を経て、伊織に拾われ、AKYRに加入した。北斎は誤解されがちだが、実はとても穏やかで心優しい性格の持ち主だ。' WHERE character_id = 'CH017536';
UPDATE characters SET description = '彼は酒豪なので、すぐに怒りを爆発させてしまう。以前はかなりろくでもない人間だった。 現在は心機一転、以前とは別人のようになった。物言いは率直だが、心根は優しく、真の男の中の男だ。サイモンとは長年の知り合いで、かつては二人組のユニットを組んでいたこともある。彼はヒップホップの精神を大切にしている。' WHERE character_id = 'CH017537';
UPDATE characters SET description = '「ファントム・ライブ」の創設グループ「BURAIKAN」のメンバー。伝説的な楽曲プロデューサー。普段は表情が乏しく無愛想で、コミュニケーション能力が低いためどこか傷ついたような印象を与えるが、彼が手掛ける楽曲は表現力豊かで繊細だ。ラップのスキルは極めて高く、音は彼の思い通りに流れるように滑らかに展開する。 現在は、「ライメンテイ」という中華料理店を経営している。' WHERE character_id = 'CH017538';
UPDATE characters SET description = '「ファントム・ライブ」の創設者である「BURAIKAN」のメンバー。ファントムに対して圧倒的な親和性を持っており、トラウマを経験したことがないにもかかわらず、強力なイリュージョンを生み出すことができる。その卓越した音楽センスで生み出される楽曲は、世界中の聴衆を魅了し、「BURAIKAN」の名を世界的なレベルへと押し上げている。' WHERE character_id = 'CH017539';
UPDATE characters SET description = '口数は少ないが、誰よりも情熱的な男だ。救助のためなら、並々ならぬ自己犠牲の精神を見せる。' WHERE character_id = 'CH017541';
UPDATE characters SET description = 'この物語の主人公は、就職初日から消防活動についてすべてを知っていると思い込んでいる18歳の愚か者である。    -ウィキペディア' WHERE character_id = 'CH017543';
UPDATE characters SET description = 'この地域で最も忙しい消防署の一つであるクジラダイ消防署で、ダイゴの真剣なライバル。' WHERE character_id = 'CH017545';
