UPDATE characters SET description = '山田家の次男であり、「バスター・ブラザーズ!!!」の一員。池袋のボスの一人。格闘の腕は確かだ。皆から愛される一郎を憧れの存在としている。兄の背中を見て育ったため、兄と同じように不良になった。' WHERE character_id = 'CH017637';
UPDATE characters SET description = '所属：渋谷　ソロ曲：3$EVEN、SCRAMBLE GAMBLE　名言：自分の生きる人生を愛せ。愛する人生を生きろ。　ギャンブル依存症で、夢野源太郎、雨村ラムダと共に「フリング・ポッセ」の3人のメンバーの一人。堅実で安定した生活様式を嫌っている。 ギャンブルに没頭しており、金と同じくらい簡単に自分の命さえも賭けてしまう。生まれて以来、極度の幸運に支えられて生き延びてきた。スリルを求めてギャンブルをするが、呪いや不運の予兆については非常に真剣に受け止めている。彼は常に……' WHERE character_id = 'CH017638';
UPDATE characters SET description = 'ごく普通の会社員であり、神宮寺ジャクライ、イザナミ・ヒフミと共に「マテンロウ」の3人のメンバーの一人。医療機器メーカーの社員であり、「マテンロウ」のメンバーでもある。特異な点といえば、まったく特異なところがないという点だ。 サラリーマンとしての仕事にいつも疲れ切っている。独り言をつぶやく癖がある。根っからの皮肉屋で、何事も否定的に捉えがちだ。その悲観的な性格のせいで友人はほとんどおらず、唯一の幼なじみは小学校時代からの日文だけである。彼は' WHERE character_id = 'CH017639';
UPDATE characters SET description = '山田家の三男であり、「バスター・ブラザーズ!!!」の最年少メンバー。何でもこなせる天才タイプ。兄たちとは異なり、不良ではない。' WHERE character_id = 'CH017640';
UPDATE characters SET description = 'かつてササラ・ヌルデとコメディデュオを組んでいた教師で、現在は大阪支部に所属している。極度の舞台恐怖症で、大勢の前では言葉が出ないが、それでも生徒たちからは愛されている。' WHERE character_id = 'CH017641';
UPDATE characters SET description = '「言葉の党」の党首。H時代の元年、ヒプノシス・マイクを用いてクーデターを起こし、政権を掌握した。H法を制定・公布し、軍を廃止して、女性中心の社会を築き上げた。 H時代第3期には、男性たちが「ヒプノシス・マイク」を駆使して領土を巡って競い合う「ディビジョン・ラップバトル」を主催した。' WHERE character_id = 'CH017642';
UPDATE characters SET description = 'アイモノ・ジュウシやハライ・クウコと共に名古屋支部に所属する弁護士。相応の報酬が約束されればどんな事件でも引き受けるが、いじめの被害者の弁護については無償で引き受けることもある。神宮寺ジャクライの旧友である。' WHERE character_id = 'CH017643';
UPDATE characters SET description = '「言葉の党」の新鋭であり、横浜支部の青柩サマトキの妹。  彼女は気骨が強く、そのラップスキルはサマトキに匹敵すると言われるほど素晴らしい。彼女は、ラムダ・アメムラのクローンの一人によって、本物の「ヒプノシス・マイク」を用いて洗脳され、党に加入させられた。' WHERE character_id = 'CH017644';
UPDATE characters SET description = '暴行、収賄、横領、恐喝、その他の凶悪犯罪を捜査する警察官。リオ・メイソン・ブスジマを、自身と青槌サマトキと共に「MAD TRIGGER CREW」に誘うことを提案したのは彼だった。同グループの最年長メンバーである。' WHERE character_id = 'CH017645';
UPDATE characters SET description = 'ホストクラブの従業員であり、神宮寺ジャクライ、観音坂ドッポと共に「マテンロウ」の3人のメンバーの一人。ある事情からホストとなり、「マテンロウ」の一員となった。正直な性格で、口調は軽薄なところがある。その外見と口調のせいで、誤解されやすい。 実は極度の女性恐怖症。女性への恐怖を克服するためにホストになった。スーツを着ると、すっかり女たらしへと変貌する。ドッポとは小学校からの友人。彼は' WHERE character_id = 'CH017646';
UPDATE characters SET description = '「言葉の党」の序列で2番目に位置する人物。同党のあらゆる政治的施策を統括する女性である。党首である乙女トホテンを深く尊敬しており、彼女には多大な恩義を感じている。男性を心の底から軽蔑しており、男性がいなければ世界はもっと良くなると信じている。 自分自身にも他人に対しても非常に厳しいが、青柩ネムに対しては特別な思い入れを持っている。' WHERE character_id = 'CH017647';
UPDATE characters SET description = 'ササラ・ヌルデやツツジモリ・ロショウと共に、大阪支部で活動する詐欺師。責任感が強く、約束を守り、かなり魅力的な人物だが、本音を語っているのかどうかは、なかなか見極めがつかない。' WHERE character_id = 'CH017648';
UPDATE characters SET description = '職業：写真家　年齢：30歳　世界中を旅して、将来有望な若者たちを撮影するストリートフォトグラファー。各国の文化、特に食文化に精通しているが、食べ物（特に大好物のラーメン）のことを考えて仕事に集中できなくなることもある。 強い正義感を持ち、多くの人が紛争に翻弄される姿を目の当たりにしてきたことから、平和を脅かす者たちに対して深い怒りを感じている。' WHERE character_id = 'CH017649';
UPDATE characters SET description = '父方の血は半分アメリカ人、母方は半分日本人だ。彼はまるで今も兵士であるかのように話し、振る舞う。海軍将校だった頃、彼は何よりも階級を重んじていた。 例えば、上官が「白は黒だ」と言えば、白は黒だった。極限の状況下では、敵に対して一切の容赦を見せない。' WHERE character_id = 'CH017650';
UPDATE characters SET description = 'ビジュアル系ミュージシャンだが、実のところ自己愛の強い泣き虫だ。友達はほとんどおらず、「アマンダ」という名前のブタのぬいぐるみに頼りきっている。' WHERE character_id = 'CH017651';
UPDATE characters SET description = '職業：アシスタントカメラマン' WHERE character_id = 'CH017652';
UPDATE characters SET description = '小説家であり、有栖川ダイス、雨村ラムダと共に「フリング・ポッセ」の3人のメンバーの一人。 非常に説得力のある嘘つきで、少々いたずら好きな一面を持ちながらも、物腰が柔らかくおとなしい性格のゲンタロウは、作家であり「フリング・ポッセ」のメンバーである。誰かが彼の嘘を信じてしまうと、彼は「冗談だよ」と告げる。 彼の嘘には、それなりの動機がある。家政夫のような服装を好み、服に対するこだわりがある。趣味は人観察であり、その観察から最高の物語を生み出している。' WHERE character_id = 'CH017653';
UPDATE characters SET description = '職業：ウェブ編集者' WHERE character_id = 'CH017654';
UPDATE characters SET description = '代表チームの背番号：#10　ポジション：ミッドフィールダー　主人公のツバサは、生まれながらのサッカー選手となる運命を背負った少年だ。彼の名前は「大空の翼」という意味を持つ。サッカーに対する彼の愛情と献身は、まさに並外れている。 明るく前向きな性格で、世界クラスのスター選手になるという目標に向かって、数々の困難を乗り越えていく。彼は行く先々で多くの友人を獲得し、気難しい選手たちでさえ、その親しみやすさに魅了されてしまう。彼のシュートはすべて力強く……' WHERE character_id = 'CH017655';
UPDATE characters SET description = 'カール＝ハインツ・シュナイダーは、ドイツ代表のキャプテンであり、エースストライカーであり、同代表のトッププレーヤーの一人である。' WHERE character_id = 'CH017656';
UPDATE characters SET description = '生年月日：6月23日　代表チームの背番号：#14　ポジション：ディフェンダー／兼任コーチ　愛称：フィールドのキコシ（フィールドの王子）、ガラスのエース　得意技：ドライブシュート、オフサイド戦術　三杉純は、間違いなく日本を代表するトッププレイヤーの一人である。 残念ながら、心臓の病気が原因で、ほぼすべての試合で出場時間は短く限られている。アルゼンチン戦中、日本代表監督は心の中で、もしジュンがフル出場できていれば、彼は日本を代表する最高の選手（それ以上に）になっていただろう、と静かに考えていた。' WHERE character_id = 'CH017657';
UPDATE characters SET description = 'ヘルマン・カルツは、ドイツ代表の守備的ミッドフィールダーである。' WHERE character_id = 'CH017658';
UPDATE characters SET description = '木杉 哲平は、日本出身の控えフォワードである。' WHERE character_id = 'CH017659';
UPDATE characters SET description = '岩見健一は、南葛の元ミッドフィールダーで、現在は大学生である。中学生の頃は背番号「5」のユニフォームを着用していた。' WHERE character_id = 'CH017660';
UPDATE characters SET description = 'バローリはディフェンダーです。背番号は6番です。このキャラクターは、イタリアのサッカー選手、フランコ・バレージとレナート・ザッカレッリをモデルにしています。' WHERE character_id = 'CH017661';
UPDATE characters SET description = '「Jボーイズ・チャレンジ」編の期間中、カルボナーラはフランス・ジュニアユースのヘッドコーチを務めていた。' WHERE character_id = 'CH017662';
UPDATE characters SET description = 'フランチェスコはイタリア人MFだ。彼は「Jボーイズ・チャレンジ」において、イタリア・ジュニアユースの選手としてプレーしていた。' WHERE character_id = 'CH017663';
UPDATE characters SET description = 'ゴンゲルスはドイツ出身のディフェンダーである。彼は「Jボーイズ・チャレンジ」において、ハンブルク・ジュニア・ユースの選手としてプレーしていた。' WHERE character_id = 'CH017665';
UPDATE characters SET description = '三崎一郎は日本の画家であり、『キャプテン翼』シリーズの脇役の一人である。彼は『キャプテン翼』編で初登場した。三崎太郎の父親であり、山岡由美子の元夫でもある。' WHERE character_id = 'CH017667';
UPDATE characters SET description = 'タルデッリはフォワードです。出典によって、背番号は2番または3番となっています。イタリアのサッカー選手、マルコ・タルデッリがモデルとなっています。 『新・キャプテン翼』のイタリア語吹き替え版では「マルケージ」という名前で登場しているが、『キャプテン翼：ライズ・オブ・ニューチャンピオンズ』のイタリア語版では、前述の実在の選手との混同を避けるためか、姓が「ナルデッリ」と訳されている。（出典：キャプテン翼Wiki）' WHERE character_id = 'CH017669';
UPDATE characters SET description = '代表チームの背番号：#9　ポジション：フォワード　家族を支えるため、日向浩二郎はプロ選手、そしてエースストライカーを目指している。サッカーへの情熱とゴールを狙い続ける粘り強さは並外れている。彼はツバサとゲンゾーの両者にとって最大のライバルだった。 素晴らしい人物である日向は、強靭であるだけでなく、タフでありながらも思いやりのある性格だ。ただ、時折少し衝動的になることもある。かつてはその荒々しさで知られ、多くの選手が彼を恐れていた。しかし、日向は実は根っからの' WHERE character_id = 'CH017671';
UPDATE characters SET description = 'エル・シド・ピエールはフランス代表チームのキャプテンである' WHERE character_id = 'CH017672';
UPDATE characters SET description = '曽田誠は、審判に気づかれないようにタックルで相手を怪我させる術を知っている、手強いディフェンダーだ。かなり足が速く、パスやシュートには効果を込める傾向がある。日向やナポレオンと少し似ており、衝動的な性格で、誰かと喧嘩になることもある。  南葛と東一の試合では、ツバサを苦しめ、ツバサの足を負傷させることさえあった。しかし、南葛はそれでも勝利を収めた。また、彼は全日本ジュニアユースの代表にも選出され、p' WHERE character_id = 'CH017673';
UPDATE characters SET description = '守は、日本出身のワイドミッドフィールダーである。' WHERE character_id = 'CH017674';
UPDATE characters SET description = '大空光大は、大空ツバサと大空ダイチの父親であり、大空ナツコの夫である。' WHERE character_id = 'CH017675';
UPDATE characters SET description = 'ディエゴ・バルバスは、アルゼンチン・ジュニアユースおよびアルゼンチン・オリンピック代表の監督である。彼の名前は、元アルゼンチン代表サッカー選手のフアン・バルバスに由来している。（出典：キャプテン翼ウィキ）' WHERE character_id = 'CH017676';
UPDATE characters SET description = '彼は『キャプテン翼』第51話「開会式」で初登場した。大空翼の個人語学教師であり、ブラジルへの渡航に備えるため、中学最後の1年間、翼をサポートした。 普段は大空家で姿を見せ、中学サッカー大会の決勝戦でも教え子を応援した。カルロスはとても陽気な性格だが、ツバサを立派な生徒に育て上げようと決意しており、いつも「サッカーばかりを優先している」と教え子をからかっている（時には' WHERE character_id = 'CH017678';
UPDATE characters SET description = 'ミシェル・フェレリはフランスの選手です。『J Boys'' Challenge』では、フランス・ジュニア・ユースの一員としてプレーしました。『Rising Sun』では、オリンピック・フランスの一員として出場しました。' WHERE character_id = 'CH017679';
UPDATE characters SET description = '元日本代表ゴールキーパー、若林元三のコーチ、全日本ジュニアユースの監督。『キャプテン翼』第1話で初登場。元日本代表ゴールキーパー。若林の元コーチである。ロベルトの正体を真っ先に突き止めた人物でもある。 彼は、若林に南葛やツバサとの試合を前に、地獄のようなトレーニングを課した。若林が失点して落ち込んでいると、三上は彼を殴り、「もう指導はしない」と告げた。' WHERE character_id = 'CH017680';
UPDATE characters SET description = 'ツバサのお母さん。' WHERE character_id = 'CH017682';
UPDATE characters SET description = '大川学は、南葛の引退したディフェンダーである。1983年のアニメでは、チアリーダーの男子クラブのメンバーであり、大学生である。中学生の頃は背番号「15」のユニフォームを着ていた。' WHERE character_id = 'CH017683';
UPDATE characters SET description = '浦部漢治は、U-22日本代表やJ1リーグのジュビロ磐田でプレーした守備的ミッドフィールダー兼ディフェンダーである。日本代表では背番号24を着用している。' WHERE character_id = 'CH017684';
UPDATE characters SET description = 'ユゾは日本のゴールキーパーで、日本代表の3番目のゴールキーパーである。' WHERE character_id = 'CH017687';
UPDATE characters SET description = '新田俊は、日向浩二郎に次ぐ日本代表の現第2フォワードであり、チームのレギュラーとして定着している。彼は「黄金世代」のほとんどの選手より1歳年下である。' WHERE character_id = 'CH017689';
UPDATE characters SET description = 'ボッシはフランス・ジュニアユースのフォワードである。背番号は「11」だ。 空中戦 ダイビングヘッド：ボールが低い位置にあるときに使われる。高速で移動しながらも正確にボールを打つには、かなりの技術が必要とされる。 （出典：キャプテン翼ウィキ）' WHERE character_id = 'CH017691';
UPDATE characters SET description = 'タケシは、日本出身のフルバックおよび守備的ミッドフィールダーである。' WHERE character_id = 'CH017697';
UPDATE characters SET description = '沢木昇は、埼玉県にある明和東中学校のフォワードであり、明和FCでもプレーしていた。背番号はそれぞれ11番と9番を着用している。' WHERE character_id = 'CH017699';
UPDATE characters SET description = 'タダシは、南葛SCおよびU-13日本代表の監督を務めている。' WHERE character_id = 'CH017700';
UPDATE characters SET description = 'アモロは、フランス・ジュニアユース代表に所属するフランス人ゴールキーパーです。アモロは原作漫画で初登場しました。背番号は1番です。' WHERE character_id = 'CH017701';
UPDATE characters SET description = 'ゼーマン氏はドイツ出身のコーチです。' WHERE character_id = 'CH017702';
UPDATE characters SET description = 'コンティはミッドフィールダーである。背番号は7番。実在のイタリア人選手、ブルーノ・コンティをモデルにしている。『キャプテン翼：新・チャンピオンズ』のイタリア語版では、実在の選手との混同を避けるためか、彼の姓は「ポンティ」と訳されている。（出典：キャプテン翼Wiki）' WHERE character_id = 'CH017703';
UPDATE characters SET description = 'ディーンはイングランド代表のフォワードです。彼は「Jボーイズ・チャレンジ」でイングランド・ジュニアユースの一員としてプレーしていました。' WHERE character_id = 'CH017704';
UPDATE characters SET description = 'ダニエルはウルグアイ出身のディフェンダーです。彼は「Jボーイズ・チャレンジ」において、ウルグアイ・ジュニア・ユースの一員としてプレーしていました。' WHERE character_id = 'CH017705';
UPDATE characters SET description = 'マルセルはフランスのディフェンダーです。彼は「Jボーイズ・チャレンジ」において、フランス・ジュニア代表の一員としてプレーしました。' WHERE character_id = 'CH017706';
UPDATE characters SET description = 'エル・シド・ピエールの母親。' WHERE character_id = 'CH017707';
UPDATE characters SET description = '藤沢良子は、松山光の恋人であり、後に婚約者となり、かつて富良野中学校のマネージャーを務めていた。  ヨシコは松山光の小学校時代の友人であり、北海道出身である。富良野中学校が南葛に敗れた後、アメリカへ移住したが、後に松山と再会し、日本で学業を修了するために帰国した。  良子は、親切で勤勉、物静かな少女であり、日本の女性像である「大和撫子」の理想にぴったりと合致している。（出典：キャプテン翼ウィキ）' WHERE character_id = 'CH017708';
UPDATE characters SET description = 'ガルトーニはアルゼンチン出身のゴールキーパーである。ガルトーニは「アルゼンチンJr.」およびその後の「オリンピック・アルゼンチン」の正ゴールキーパーを務めている。背番号は「1」である。彼の名前は、アルゼンチンのサッカー選手ダニエル・ベルトーニに由来している。 『ゲット・イン・ザ・トゥモロー』では、彼の名前はホルヘ・ガルトーニと表記されているが、同漫画の完全版特別号のカラー見開きページでは、フリオ・ガルトーニと表記されている。  （出典：キャプテン翼ウィキ）' WHERE character_id = 'CH017710';
UPDATE characters SET description = 'ガルバンはアルゼンチン代表のディフェンダーである。彼は『キャプテン翼』第93話で初登場したキャラクターだ。その体格からパワーに優れており、アルゼンチンのディフェンスラインにおいて頼もしい存在であることを証明した。 背番号は5番。実在の選手、ルイス・ガルバンをモデルにしている。興味深いことに、『キャプテン翼J～明日へ～』では、彼の名前もルイス・ガルバンと表記されている。これが意図的なものなのか、それとも偶然なのかは不明である。漫画の特別完全版カラー見開きページによると、彼の名前は……' WHERE character_id = 'CH017712';
UPDATE characters SET description = 'ミシェル・フィッシャーはフランスの選手である。彼は「Jボーイズ・チャレンジ」において、セーヌ・ジュニア・ユースの一員だった。フィッシャーとチームメイトたちは、三崎太郎がフランスに滞在していた当時、彼とサッカーのパートナーだった。フランスで開催された第1回国際ジュニア・ユース大会では、彼らは地元チームを応援するだけでなく、三崎や日本代表チームも応援した。' WHERE character_id = 'CH017713';
UPDATE characters SET description = 'ジョルジュはフランスのミッドフィールダーです。『Jボーイズ・チャレンジ』では、フランス・ジュニア・ユースの選手として活躍しました。『ライジング・サン』では、フランスオリンピック代表の一員でした。' WHERE character_id = 'CH017714';
UPDATE characters SET description = '国籍：フランス／日本　職業：交換留学生、全日本ジュニアユースのサポーター　早川あずみは、三崎太郎がパリに2年半滞在していた間、彼と同じ学校に通っていたフランス在住の日系人女性である。  あずみは、『キャプテン翼』第90話「パリでの大集結！」で初登場した。' WHERE character_id = 'CH017718';
UPDATE characters SET description = '神田幸司は、中沢早苗をめぐる大空翼の最大のライバルである。初登場は『キャプテン翼』（第56話）だ。背が高く、アスリート体型で、少しふさふさした前髪が特徴のイケメン青年である。 2023年版のシリーズでは、その外見が若干変化している。髪は以前よりふんわり感が減り、肌は少し日焼けしており、瞳は濃い青色になっている。神田は非常に感情的な若者で、衝動的で情熱的だ。残酷な人間ではないが、特に自分が嫌いな相手に対しては、極めて傲慢な態度をとることもある。' WHERE character_id = 'CH017719';
UPDATE characters SET description = 'マイク・ギルドはドイツ・ジュニア代表の監督を務めていた。' WHERE character_id = 'CH017720';
UPDATE characters SET description = '石田哲夫は、南宇和に所属する攻撃的ミッドフィールダーである。初登場は『キャプテン翼』第65話「ふらの、前線へ」である。チームのキャプテンを務めており、攻守のバランスに優れ、ボールコントロールも抜群だ。 準々決勝では、彼とチームメイトたちは、松山市の富良野中学校に善戦を見せた。' WHERE character_id = 'CH017721';
UPDATE characters SET description = 'ヤラはドイツ人フォワードだ。彼は「Jボーイズ・チャレンジ」において、ハンブルク・ジュニア・ユースの選手だった。' WHERE character_id = 'CH017722';
UPDATE characters SET description = '彼は漫画『キャプテン翼』に初登場した。元日本のサッカー選手であり、現在は日本サッカー協会（JFA）の職員として、主にスカウト業務に従事している。『ワールドユースカップ』によると、彼は非常に裕福な家庭の出身だが、家業を継ぐよりもサッカーの道を選んだため、長年にわたり家族との縁を切っていた。  片桐は裏方で糸を引いており、翼、美咲、日向、葵をはじめとする「黄金世代」の多くの才能ある選手たちが、サッカー界の頂点へと登りつめる道を支えている。' WHERE character_id = 'CH017724';
UPDATE characters SET description = '児玉一雄は、西峰のキャプテンであり、フォワードを務める。  児玉一雄は、単発漫画『僕は岬太郎』およびその続編『僕は岬太郎2』に登場する。また、本編の第66話でもフラッシュバックシーンに登場している。西峰では背番号「9」のユニフォームを着用している。' WHERE character_id = 'CH017726';
UPDATE characters SET description = '加藤雅則は、小学生の頃から松山と同じチームでプレーし、ゴール前と守備陣を守ってきた。彼は『キャプテン翼』第15話「今や全国だ！」で初登場した。（出典：キャプテン翼Wiki）' WHERE character_id = 'CH017727';
UPDATE characters SET description = '北爪誠は、「ボーイズ・ファイト」編の期間中、東邦学園中学校のコーチを務めていた。' WHERE character_id = 'CH017728';
UPDATE characters SET description = '町田真知子は、藤沢良子の友人である。『ボーイズ・ファイト』では、富良野中学校のサッカー部のマネージャーを務めていた。『バトル・オブ・ワールド・ユース』では、良子が交通事故に遭った後、病院で彼女のそばに寄り添っていた一人だった。（出典：キャプテン翼ウィキ）' WHERE character_id = 'CH017729';
UPDATE characters SET description = 'ドイツ語版では「Magdt」と表記されるマガトは、ディフェンダーである。背番号は「5」を着用している。タックルの強さと鋭い守備力において、非常に粘り強い選手だ。ドイツを代表するサイドバックの一人である。  彼の名前は、元サッカー選手のフェリックス・マガトに由来している。『コンプリート』特別号ではファーストネームはトーマス、そして『キャプテン翼J：ゲット・イン・ザ・トゥモロー』ではブルーノとなっている。（出典：キャプテン翼Wiki）' WHERE character_id = 'CH017732';
UPDATE characters SET description = 'ディモス／マリニョはディフェンダーです。背番号は3番です。イタリアの選手、ジャンピエロ・マリーニをモデルにしています。 本名は不明である。漫画の中ではチームメイトの一人が彼を「ディモス」と呼んでいるが、『3109 パーフェクト・データ』では「マリニョ」という名前で登場している。おそらく、『キャプテン翼J：ゲット・イン・ザ・トゥモロー』で見られるように、ディモスは別の選手である可能性が高い。（出典：キャプテン翼Wiki）' WHERE character_id = 'CH017734';
UPDATE characters SET description = 'ミツルは西峰の控えMFである。ミツルは短編漫画『僕は岬太郎』（1984年）に登場する。また、本編の第66話でもフラッシュバックシーンに登場している。西峰では背番号「12」のユニフォームを着用している。  （出典：キャプテン翼ウィキ）' WHERE character_id = 'CH017735';
UPDATE characters SET description = 'ドイター・ミュラーはドイツ代表の正ゴールキーパーであり、「ファントム・キーパー」、そして後に「鋼鉄の巨人」として知られている。ミュラーは、フランスで開催されたジュニア・ユース大会でドイツ代表デビューを果たす前から、母国ではすでに伝説的な存在となっていた。 それ以来、彼はドイツ代表の主力選手の一人として活躍し続けている。山岳地帯での過酷なトレーニングのおかげで、ミュラーは並外れた強さとタフさを持ち、その体格の割には驚くほど機敏である。ゴール前に立つ彼の姿そのものが、突破不可能な壁のような印象を与える。' WHERE character_id = 'CH017736';
UPDATE characters SET description = '西本ゆかりは幼稚園の先生です。大空早苗の親友であり、かつては南葛の生徒でした。  『キャプテン翼』では、準レギュラーキャラクターとして登場する。現在は静岡県南葛市に住んでいるが、以前は長崎に住んでいた。親友の大空早苗や石崎亮と共に、南葛の学校に通っていた。（出典：キャプテン翼Wiki）' WHERE character_id = 'CH017738';
UPDATE characters SET description = '西尾浩司は、『キャプテン翼』の脇役の一人で、最初のオリジナル漫画に登場した。西尾は南葛SCおよび大友中学校に所属していた。背番号は3番である。' WHERE character_id = 'CH017740';
UPDATE characters SET description = '小田剛は、南葛の引退したディフェンダーであり、大学生である。彼は漫画『キャプテン翼』に初登場した。中学生の頃は背番号4のユニフォームを着用していた。（出典：キャプテン翼Wiki）' WHERE character_id = 'CH017742';
UPDATE characters SET description = '住友三郎は、日本のコーチである。彼は『キャプテン翼』の第85話で、日本ジュニアの副監督として初登場した。' WHERE character_id = 'CH017745';
UPDATE characters SET description = 'カルロス・サンタナはブラジル出身の選手だ。世界でも指折りの技巧派選手の一人である。彼の過去には、乗り越えなければならない非常に暗い試練があった――彼には家族がいなかったのだ。彼は赤ん坊の頃、サッカー場に置き去りにされていた。' WHERE character_id = 'CH017747';
UPDATE characters SET description = 'ルディ・フランク・シュナイダー。カール・ハインツ・シュナイダーの父であり、数世代にわたるドイツ代表チームの監督を務め、現在はFCバイエルン・ミュンヘンの監督を務めている。  ルディと妻は、フランクがクラブ内で下す決定に対してドイツ国民が反対する状況に妻がうんざりしていたため、意見の相違から離婚を考えていた。このことはカールのパフォーマンスや、次女のマリーにも影響を及ぼした。（出典：キャプテン翼ウィキ）' WHERE character_id = 'CH017750';
UPDATE characters SET description = '山村は、美崎一郎の絵画のファンである。『僕は美崎太郎』の中で、彼はいつか一郎が富士山を描いてくれることを願っていた。一郎は最終的に『ライジング・サン』でその絵を描き、山村は真っ先にそれを見られるようにした。（出典：キャプテン翼ウィキ）' WHERE character_id = 'CH017751';
UPDATE characters SET description = '東邦のフォワード。U-16ワールドカップの際、三上監督によって日本代表に招集されたが、出場したのはフランス戦のみだった。' WHERE character_id = 'CH017752';
UPDATE characters SET description = '彼女は「ボーイズ・ファイト編」において、南葛中学校の第2アシスタントマネージャーを務めている。また、『ホランド・ユース・マンガ・スペシャル』にも登場しており、黄金世代が高校を卒業するまで南葛を応援し続けていた。杉本が初めて登場したのは、『キャプテン翼』（1981年）第51話である。 彼女は南葛の他のメンバーの後輩であり、チームメイトのほぼ全員が中学3年生であるのに対し、彼女は中学1年生である。性格はやや純真で、率直なところがある。I' WHERE character_id = 'CH017753';
UPDATE characters SET description = '彼は『キャプテン翼』（1981年）の第26話で初登場した。武蔵のトリオの一員である。武蔵FCおよび武蔵中学校では、レギュラーのフォワードとしてプレーした。背番号は10番である。 その後、日本ユース代表では控え選手としてプレーした。三杉が欠場する際、本間はチームの攻撃の要の一人となる。武蔵野地区の1000人の選手の中から、トップフォワードに選出されたこともある。' WHERE character_id = 'CH017757';
UPDATE characters SET description = '彼はプロを目指してXシティにやってきたアマチュアのベイブラーだ。故郷では最強だったものの、プロに敗れ、相棒のベイブレードも破壊されてしまった。その後、かつてのチームメイトたちに見捨てられ、絶望していた。 しかし、そんな時、突然「仮面X」が彼の前に現れ、二人は「ペルソナ」という新しいチームを結成した。当初、彼は仮面Xを疑っていた。だが、その比類なき強さと、ベイブレードを心から楽しむ姿を見て、彼はかつてどれほど――' WHERE character_id = 'CH017759';
UPDATE characters SET description = 'マルチ・ナナリオは、パートナーの「ウィザード・アロー」と「ナイト・シールド」と共に活躍する、有名なインフルエンサーであり、実力派のブレイダーだ。彼女は、チーム・ペルソナとのバトルで敗れたことをきっかけに、同チームに加入した。' WHERE character_id = 'CH017760';
UPDATE characters SET description = '彼は、Xタワーのチャンピオンチーム「ペンドラゴン」の元メンバーである。彼のパートナーベイブレードは「ドランソード」だ。「ベイブレードは楽しむためのもの」と公言する、謎めいたキャラクターである。 圧倒的な強さを誇り、無敗の記録を保持しているが、Xタワーの「頂点」に到達するやいなや姿を消した。これは、かつてのチームメイトであり、現チャンピオンであるリュウグウ・クロームと戦うためである。彼はバードやマルチと共にチーム「ペルソナ」を結成し、Xタワーに挑む。' WHERE character_id = 'CH017761';
UPDATE characters SET description = '天花白星は、アニメ・漫画シリーズ『ベイブレードX』において、マルチ・ナナイロと並ぶ2人の三番手キャラクターの一人である。彼女は「セイバーサムライ 2-70L」というベイブレードを使って戦う。' WHERE character_id = 'CH017762';
UPDATE characters SET description = '日本国内では「ユニ・ナンバ」として知られるユニ・ナニワは、アニメ・漫画シリーズ『ベイブレードX』に登場するキャラクターである。彼女はユニコーン・ベイブレードを使って戦う。' WHERE character_id = 'CH017765';
UPDATE characters SET description = '日本では「バーン・フジワラ」として知られるブレイズ・フジワラは、アニメ・漫画シリーズ『ベイブレードX』に登場するキャラクターである。彼はフェニックス・ベイブレードを使って戦う。' WHERE character_id = 'CH017766';
UPDATE characters SET description = 'ギンロは、アニメおよび漫画『ベイブレードX』に登場するキャラクターである。彼はジャクソン・クロス／エクス・クロスの師匠であり、彼にベイブレードの遊び方を教えた人物である。彼は自身のベイブレード「スターリング・ウルフ 3-80FB」を使って戦う。' WHERE character_id = 'CH017769';
UPDATE characters SET description = 'クロース・エクスの妹' WHERE character_id = 'CH017770';
UPDATE characters SET description = 'シグリッド・ナナイロ（日本では「シグル・ナナイロ」として知られる）は、アニメ・漫画シリーズ『ベイブレードX』に登場するキャラクターである。彼女は「パールタイガー3-60U」というベイで戦う。また、マルチ・ナナイロの姉でもある。' WHERE character_id = 'CH017772';
UPDATE characters SET description = 'レックス・ジュラは、アニメ・漫画『ベイブレードX』に登場するキャラクターです。彼は「ビート・ティラノ 4-70Q」というベイで戦います。' WHERE character_id = 'CH017773';
UPDATE characters SET description = 'オメガ・シロボシは、アニメ・漫画シリーズ『ベイブレードX』に登場するキャラクターである。彼女はベイブレード「エアロペガサス 3-70A」を使って戦う。天華・シロボシの母親である。' WHERE character_id = 'CH017778';
UPDATE characters SET description = 'カーラ・コンジキは、アニメ・漫画シリーズ『ベイブレードX』に登場するキャラクターです。彼女は「スカーレット・ガルーダ 4-70TP」というベイブレードを使って戦います。' WHERE character_id = 'CH017779';
UPDATE characters SET description = '岩尾ゴゴは、アニメ・漫画シリーズ『ベイブレードX』に登場するキャラクターである。彼はチーム・ゴルディアスのメンバーであり、カーラ・コンジキの執事でもある。彼は自身のベイブレード「ゴーレムロック 1-60UN」を使って戦う。' WHERE character_id = 'CH017782';
UPDATE characters SET description = 'クイン・マンジュは、アニメ・漫画『ベイブレードX』に登場するキャラクターです。彼女はタイタス・マンジュの祖母です。彼女はベイブレード「シャドウ・シノビ 1-80MN」を使って戦います。' WHERE character_id = 'CH017783';
UPDATE characters SET description = 'ゾナモス・ネコヤマは、アニメ・漫画シリーズ『ベイブレードX』に登場するキャラクターである。彼はスフィンクス・ベイブレードを使って戦う。' WHERE character_id = 'CH017786';
UPDATE characters SET description = 'パクンは、アニメ・漫画シリーズ『ベイブレードX』に登場するキャラクターである。彼はベイチューバーであり、プロブレイダーたちのベイブレードと全く同じものを用いて戦う。' WHERE character_id = 'CH017787';
UPDATE characters SET description = 'ランツ・ロジは、アニメ・漫画シリーズ『ベイブレードX』に登場するキャラクターである。彼は「ダーク・ペルセウス B 6-80W」というベイで戦う。' WHERE character_id = 'CH017791';
UPDATE characters SET description = 'カミナリ・シエルは、アニメ・漫画シリーズ『ベイブレードX』に登場するキャラクターです。彼は「オブシディアン・シェル 4-60D」というベイブレードを使って戦います。' WHERE character_id = 'CH017792';
UPDATE characters SET description = '冷静沈着で、分析力に長けたメイコ・メイデンは、「駒場寿司」の日常業務を統括するのにふさわしい資質を備えている。メイコは元プロブレイダーだが、その実力は今も衰えていない。コーチ兼マネージャーとして、チーム・ペルソナに対して厳しい指導を行う一方で、深い愛情も注いでいる。' WHERE character_id = 'CH017793';
UPDATE characters SET description = 'ドクガ・フショクは、アニメ・漫画シリーズ『ベイブレードX』に登場するキャラクターである。彼は「スコーピオスピア 0-70Z」というベイブレードを使って戦う。' WHERE character_id = 'CH017796';
UPDATE characters SET description = 'ガンダラ・ミュージックのA&R部門に新しく入社した主人公。明るく前向きで、何事にも誠実に、全力を尽くして取り組んでいる。' WHERE character_id = 'CH017797';
UPDATE characters SET description = 'ハルヒの双子の兄。混血である。物静かで、どこか謎めいた雰囲気を漂わせている。その端正な顔立ちを、少し気にしてしまうところがある。' WHERE character_id = 'CH017798';
UPDATE characters SET description = '物腰が柔らかく、心の奥底ではロマンチスト。裕福な家庭で育った、典型的な「王子様」タイプだ。物腰が穏やかで有能だが、常識からは少しかけ離れているところもある。' WHERE character_id = 'CH017799';
UPDATE characters SET description = '真面目で思いやりがあり、心清らかな青年。女性には弱く、他人に対しても内気なところがある。運動神経が良く、特に剣術に長けている。' WHERE character_id = 'CH017800';
UPDATE characters SET description = '並外れた社交性を兼ね備えた筋金入りのオタクで、趣味はコンピューター。中学時代から作曲を続けており、自分の作品に誇りを持っているが、B-taの作曲は別格だ。' WHERE character_id = 'CH017801';
UPDATE characters SET description = '彼は「小悪魔」のような性格で、抜け目がない一方で、甘やかされた魅力ある人物を演じるのも得意だ。その容姿は女性らしく、時には女性と間違えられるほどだ。甘いものが大好きで、いつもチュッパチャップスを手元に置いている。' WHERE character_id = 'CH017802';
UPDATE characters SET description = '勤勉で、完璧主義者です。親切で、物腰が柔らかく、協調性のある模範的な生徒です。グループ内では、しばしば仲介役を務めています。' WHERE character_id = 'CH017803';
UPDATE characters SET description = '幼い頃から音楽に興味を持ち、自身の楽曲を投稿し始めてからは、そのシーンで注目を集める存在となった。A-sukeの歌声に魅了され、グループ「Ultraz」を結成した。' WHERE character_id = 'CH017804';
UPDATE characters SET description = '芸術的な感性が強く、型破りな性格を持つ帰国子女。音楽に深く情熱を注いでいるが、頑固で協調性に欠ける面もある。特技はギター演奏と英語だ。' WHERE character_id = 'CH017805';
UPDATE characters SET description = '頭が良くて有能な人物だが、根っからのオタクで、2Dメディアをこよなく愛している。特に『魔法少女マミリン』に夢中だが、職場ではそのことを隠している。' WHERE character_id = 'CH017806';
UPDATE characters SET description = '都会で育ったクールな少年。感情をほとんど表に出さないため、誤解されることも多いが、約束を忠実に守る真面目な人物だ。第六感を持っており、時折、謎めいた発言をすることもある。' WHERE character_id = 'CH017807';
UPDATE characters SET description = 'アイデアが浮かんだその瞬間にすぐに行動を起こす人物。生まれつき前向きで、周囲の人々を一つにまとめるリーダー。愛らしい外見とは裏腹に、気概に満ちた男らしい性格の持ち主。主の幼なじみである。' WHERE character_id = 'CH017808';
UPDATE characters SET description = '誇り高く、自己愛が強い。  彼は軽薄な性格で、目につく女性なら誰にでも声をかけるのが彼にとってごく自然なことだ。彼はいつも前髪をいじり回している。' WHERE character_id = 'CH017809';
UPDATE characters SET description = '無邪気で気楽。自分のペースで物事に取り組む、穏やかで心を落ち着かせてくれる存在。社交的で、誰とでも仲良くできる。道に迷うのが大の苦手で、少しうっかり屋だ。' WHERE character_id = 'CH017810';
UPDATE characters SET description = 'ユズキの双子の弟。混血である。兄のユズキとは異なり、陽気で注目されるのが大好きだ。自分自身を愛しているが、兄への愛情はそれ以上に深い。' WHERE character_id = 'CH017811';
UPDATE characters SET description = '周囲を盛り上げるのが得意で、人を喜ばせたいという強い思いを持っています。コミュニケーション能力が高く、かなりの冗談好きです。楽観的ですが、その反面、物事への緊迫感が欠ける傾向もあります。' WHERE character_id = 'CH017812';
UPDATE characters SET description = 'ミロクは物静かだが真面目だ。彼は新しい仕事に臨む際、乗り越えなければならない困難の一つひとつから新しいことを学ぼうという姿勢で臨んでいる。先輩たちの影に隠れたくはないのだ。' WHERE character_id = 'CH017813';
UPDATE characters SET description = '彼は、THRIVEの所属事務所である芸能事務所「Brave Entertainment」の社長である。また、アツシの弟でもある。' WHERE character_id = 'CH017814';
UPDATE characters SET description = '作曲、編曲、作詞、プロデュースも手掛ける有名なミュージシャン。彼が手掛けた曲の多くは、大ヒットを記録した。' WHERE character_id = 'CH017815';
UPDATE characters SET description = '映画『侍の嘆き』の監督。' WHERE character_id = 'CH017816';
UPDATE characters SET description = 'B-PROJECTの音楽業界におけるベテラン。あるテレビ番組で、桜田春樹に楽曲を提供してもらっていたことが明らかになったが、そのことで桜田のファンから批判を浴びた。' WHERE character_id = 'CH017817';
UPDATE characters SET description = '映画『侍の嘆き』の助監督。' WHERE character_id = 'CH017818';
UPDATE characters SET description = '第2部門に所属する、ツバサの新しい上司。以前は同業界の別の会社に勤めており、シーズン3からガンダラ・ミュージックに入社したばかりだ。' WHERE character_id = 'CH017819';
UPDATE characters SET description = 'ツバサが所属する部署の責任者。' WHERE character_id = 'CH017820';
UPDATE characters SET description = '作曲から編曲に至るまで、あらゆる分野で天才的な才能を発揮する超有名な音楽クリエイター。彼が生み出す楽曲は素晴らしく、「アワズ・マジック」と呼ばれている。' WHERE character_id = 'CH017821';
UPDATE characters SET description = '彼は、キタコレやMooNsを所属アーティストに抱える芸能事務所「ダイコク・プロダクション」の社長である。' WHERE character_id = 'CH017822';
